// ─── Member Badge (Twitch-style) ──────────────────────────────────────────────
// Druhý parameter (user) je voliteľný: personál dostane ROLOVÝ odznak namiesto
// veku členstva — majiteľ/tréner predsa nie je „Nováčik".
// Odznaky = ROLA alebo AKTÍVNE ČLENSTVO (Marek 25.8.: vekové odznaky boli nezrozumiteľné).
// u.member_tier udržiava refreshMemberTier() pri každej zmene členstva + denný job.
const TIER_BADGES = {
  bronze:         { emoji:'🥉', label:'Bronze', color:'#cd7f32' },
  silver:         { emoji:'🥈', label:'Silver', color:'#a8a9ad' },
  gold:           { emoji:'🥇', label:'Gold',   color:'#C9A84C' },
  kids:           { emoji:'🧒', label:'Kids',   color:'#FF6B9D' },
  online_basic:   { emoji:'💻', label:'Online', color:'#4CAF50' },
  online_premium: { emoji:'💻', label:'Online', color:'#9C27B0' },
};
function getMemberBadge(createdAt, u) {
  if (u) {
    if (u.is_admin) return { emoji:'👑', label:'Majiteľ', months:0, color:'#C9A84C', staff:true };
    if (u.user_type==='trainer') return { emoji:'💃', label:'Tréner', months:0, color:'#e0a656', staff:true };
    if (u.is_assistant) return { emoji:'🤝', label:'Asistent', months:0, color:'#e0a656', staff:true };
    const t = TIER_BADGES[u.member_tier];
    if (t) return { ...t, months:0 };
  }
  return { emoji:'', label:'', months:0, color:'#666' }; // bez členstva → bez odznaku
}
async function refreshMemberTier(userId){
  try{
    if(!userId) return;
    const t=today();
    const mems=(await q.find(db.memberships,{user_id:userId, status:'active'}))
      .filter(m=>!m._type && (!m.expires_at || String(m.expires_at)>=t) && TIER_BADGES[m.plan_id]);
    const rank={gold:3, silver:2, online_premium:2, bronze:1, online_basic:1, kids:1};
    mems.sort((a,b)=>(rank[b.plan_id]||0)-(rank[a.plan_id]||0));
    await q.update(db.users,{_id:userId},{$set:{member_tier: mems[0]?mems[0].plan_id:null}});
  }catch(e){}
}

function userPublic(u) {
  if (!u) return null;
  const badge = getMemberBadge(u.created_at, u);
  const loyalty = getLoyaltyStatus(u.visit_count || 0);
  const role = USER_ROLES[u.user_type] || USER_ROLES.client;
  return {
    id: u._id, name: u.name, email: u.email, phone: u.phone||'',
    referral_code: u.referral_code, rank: u.rank||1,
    rankName: RANKS[(u.rank||1)-1].name, rankBadge: RANKS[(u.rank||1)-1].badge,
    is_admin: !!u.is_admin, user_type: u.user_type||'partner',
    bank_account: u.bank_account||'', created_at: u.created_at,
    memberBadge: badge, loyalty,
    role_label: role.label, role_icon: role.icon, dash_url: role.dashUrl,
    visit_count: u.visit_count || 0,
    notes: u.notes || '',
    sponsor_id: u.sponsor_id || null,
  };
}

// Resolve dash URL from user object — one portal for everyone except trainer/admin
function dashUrlFor(u) {
  if (!u) return '/';
  if (u.is_admin || u.user_type === 'admin') return '/admin';
  if (u.user_type === 'trainer') return '/trainer';
  return '/client-dashboard'; // client, lead, partner, manager → all get unified portal
}

// ─── Utility ──────────────────────────────────────────────────────────────────
// Dátum podľa SLOVENSKÉHO času — server beží v UTC a medzi 22:00–00:00 SK by inak
// „dnes" bol včerajšok (rozbíjalo to reset mesačnej súťaže, rezervácie po 22:00 atď.)
function today()        { return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Bratislava'}).format(new Date()); }
function nowISO()       { return new Date().toISOString(); }
function currentMonth() { return new Date().toISOString().slice(0,7); }
function dateAgo30()    { const d=new Date(); d.setDate(d.getDate()-30); return d.toISOString().slice(0,10); }
function oid()          { return Math.random().toString(36).slice(2,9).toUpperCase(); }

// Next date for a given day-of-week (0=Sun … 6=Sat), from today or future
function nextDateForDay(dow) {
  const d = new Date();
  const diff = (dow - d.getDay() + 7) % 7;
  d.setDate(d.getDate() + (diff === 0 ? 7 : diff));
  return d.toISOString().slice(0,10);
}
// Zhodné s klientským getNextDateISO: ak je dnes deň hodiny a je pred 22:00, počíta DNES.
function displayNextDateForDay(dow) {
  const now = new Date(); const today = now.getDay();
  let diff = dow - today; if(diff < 0 || (diff === 0 && now.getHours() >= 22)) diff += 7;
  const d = new Date(now); d.setDate(d.getDate() + diff);
  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}

// Pre trénerský panel platí dnešok, kým je naozaj dnes. displayNextDateForDay()
// preklápa na ďalší týždeň už o 22:00 (aby si klientka nebookla hodinu, ktorá
// práve skončila) — lenže tréner po hodine ešte zapisuje dochádzku a zoznam
// ľudí mu takto o desiatej večer zmizol.
function sessionDateFor(c){
  if(!c) return today();
  if(c.only_date) return c.only_date;
  if(c.day_of_week === new Date().getDay()) return today();
  return displayNextDateForDay(c.day_of_week);
}

// Jednorazový termín: `only_date` (YYYY-MM-DD) obmedzí hodinu na jediný dátum —
// napr. mimoriadny online prenos. Rozvrh je inak čisto týždenný (day_of_week), takže
// bez tohto by sa hodina opakovala každý týždeň. Po svojom dni ju klientky prestanú
// vidieť a netreba ju ručne vypínať; admin ju v zozname hodín vidí ďalej.
function classRunsOn(c, date){ return !c || !c.only_date || c.only_date === (date || today()); }

// ─── MLM helpers ─────────────────────────────────────────────────────────────
async function getAllDescendants(pid) {
  const seen=new Set([pid]); const queue=[pid]; const res=[];
  while(queue.length){
    const cur=queue.shift();
    const kids=await q.find(db.users,{sponsor_id:cur,is_admin:{$ne:true}});
    for(const k of kids) if(!seen.has(k._id)){seen.add(k._id);res.push(k._id);queue.push(k._id);}
  }
  return res;
}
async function getPersonal30(uid){
  const txs=await q.find(db.transactions,{partner_id:uid,date:{$gte:dateAgo30()}});
  return txs.reduce((s,t)=>s+t.amount,0);
}
async function getTeam30(uid){
  const desc=await getAllDescendants(uid);
  if(!desc.length) return 0;
  const txs=await q.find(db.transactions,{partner_id:{$in:desc},date:{$gte:dateAgo30()}});
  return txs.reduce((s,t)=>s+t.amount,0);
}
async function calcRank(uid){
  const p=await getPersonal30(uid), t=await getTeam30(uid);
  let rank=1;
  for(let i=RANKS.length-1;i>=0;i--) if(p>=RANKS[i].personalMin&&t>=RANKS[i].teamMin){rank=RANKS[i].id;break;}
  await q.update(db.users,{_id:uid},{$set:{rank}});
  return rank;
}
async function saveCommissions(txId,partnerId,amount){
  const month=currentMonth();
  const awarded=[]; // {user_id, amount, level}
  // ROZDIELOVÝ MODEL (pravidlá v2, od 20. 8. 2026): každý v línii dostane rozdiel
  // medzi percentom svojej hodnosti a najvyšším percentom už vyplateným pod ním.
  // Priama sponzorka dostane plné percento; súčet línie nikdy neprekročí 20 %.
  // Hodnosť sa berie z mesačnej uzávierky (u.amb_rank), noví začínajú ako Starter.
  // Pôvodný sčítavací model 10/5/3/2/1 (spolu 21 %) je týmto nahradený;
  // staré provízie sa spätne neprepočítavajú.
  let curId=partnerId, paidRate=0;
  for(let line=0; line<5 && curId; line++){
    const cur=await q.one(db.users,{_id:curId});
    if(!cur) break;
    const myRate = ambRate(cur.amb_rank || 1);
    const diff = Math.max(0, +(myRate - paidRate).toFixed(4));
    const amt = +(amount*diff).toFixed(2);
    if(amt>0){
      await q.insert(db.commissions,{transaction_id:txId,partner_id:cur._id,source_partner_id:partnerId,
        level:line,percentage:diff,rate_rank:cur.amb_rank||1,rules_version:2,
        amount:amt,status:'pending',month,created_at:nowISO()});
      awarded.push({user_id:cur._id, amount:amt, level:line});
      paidRate = Math.max(paidRate, myRate);
    }
    if(paidRate>=0.20) break;
    curId=cur.sponsor_id||null;
  }
  notifyCommissionRecipients(txId, awarded).catch(e=>console.error('Commission notify:',e.message));
}

// In-app + email notification to each person who earned a commission from a sale
async function notifyCommissionRecipients(txId, awarded){
  const tx = await q.one(db.transactions,{_id:txId});
  const client = tx?.client_name || '';
  const product = tx?.product_name || 'predaj';
  for(const a of awarded){
    if(!(a.amount>0)) continue;
    const u = await q.one(db.users,{_id:a.user_id});
    if(!u) continue;
    const kind = a.level===0 ? 'Priama provízia (línia 1)' : `Provízia z línie ${a.level+1}`;
    await q.insert(db.notifications,{user_id:u._id, type:'commission',
      title:`💰 Nová provízia +${a.amount.toFixed(2)} €`,
      body:`${kind} z predaja „${product}"${client?` – ${client}`:''}.`,
      read:false, created_at:nowISO()});
    if(u.email && !u.email.includes('@internal.local')){
      sendMail(u.email, `💰 Nová provízia +${a.amount.toFixed(2)} € — Fusion Academy`,
        emailTemplate('Máš novú províziu! 🎉',
          `<p>Ahoj <b>${u.name}</b>,</p><p>Práve ti pribudla <b>${kind.toLowerCase()}</b> <b style="color:#C9A84C">+${a.amount.toFixed(2)} €</b> z predaja <b>${product}</b>${client?` (klient ${client})`:''}.</p><p>Zostatok a výplatu si pozri vo svojom profile.</p>`,
          '📊 Moje provízie', `${APP_URL}/dashboard`)).catch(()=>{});
    }
  }
}

// Auto-award MLM commission for an automatic purchase (Stripe/PayPal/cash membership).
// Recipient = the buyer's sponsor (who referred them). No-op if the buyer has no sponsor.
async function awardPurchaseCommission({buyer_id, amount, product_name}){
  try {
    if(!buyer_id || !(amount>0)) return;
    const buyer = await q.one(db.users,{_id:buyer_id});
    if(!buyer) return;
    // 🔔 Admin notifikácia o KAŽDOM predaji (okrem test účtov) — beží cez tento
    // centrálny hook, ktorý volá každý predaj (členstvá, permanentky, vstupy,
    // súkromné hodiny, merch/objednávky, obnovy — hotovosť aj online platby).
    if(!/@test-fa-qa\.local$/i.test(String(buyer.email||''))){
      (async()=>{ const admins=await q.find(db.users,{is_admin:true});
        for(const a of admins) await q.insert(db.notifications,{user_id:a._id,type:'sale',
          title:`💶 Predaj: ${(+amount).toFixed(2)} €`,
          body:`${buyer.name} — ${product_name||'Nákup'}`,read:false,created_at:nowISO()});
      })().catch(e=>console.error('sale notify:',e.message));
    }
    // Referral výzva: kamoška sa ráta, až keď zaplatí — skontroluj odmenu sponzorke
    if(buyer.sponsor_id) referralGoalCheck(buyer.sponsor_id).catch(()=>{});
    // First paid purchase promotes a lead → client
    if(buyer.user_type==='lead'){
      await q.update(db.users,{_id:buyer._id},{$set:{user_type:'client'}});
      await q.insert(db.notifications,{user_id:buyer._id,type:'role_change',title:'Vitaj medzi klientmi! 🎉',body:'Tvoja prvá platba prebehla – si náš klient.',read:false,created_at:nowISO()}).catch(()=>{});
    }
    if(!buyer.sponsor_id) return;
    const amt = +(+amount).toFixed(2);
    const tx = await q.insert(db.transactions,{
      partner_id: buyer.sponsor_id, client_id: buyer._id, client_name: buyer.name,
      product_id:null, product_name: product_name||'Členstvo', amount: amt,
      date: today(), notes:'Automatická provízia z online predaja', auto:true,
      commission_only:true, // excluded from revenue totals (revenue counted via payment/membership record)
      created_at:nowISO()
    });
    await saveCommissions(tx._id, buyer.sponsor_id, amt);
    await calcRank(buyer.sponsor_id);
  } catch(e){ console.error('awardPurchaseCommission:', e.message); }
}

// ─── Auth middleware ──────────────────────────────────────────────────────────
const auth      = async(req,res,next) => {
  if(!req.session.uid) return res.status(401).json({error:'Nie ste prihlásený'});
  // Vynútené odhlásenie po admin resete hesla: session verzia < aktuálna user verzia
  if(req.session.sv !== undefined){
    const u = await q.one(db.users,{_id:req.session.uid});
    if(u && (u.sess_ver||0) > req.session.sv){
      req.session.destroy(()=>{});
      return res.status(401).json({error:'Boli ste odhlásený. Vytvorte si nové heslo.', pw_reset:true});
    }
  }
  next();
};
const adminAuth = async(req,res,next) => {
  if(!req.session.uid) return res.status(401).json({error:'Nie ste prihlásený'});
  const u=await q.one(db.users,{_id:req.session.uid});
  if(!u?.is_admin) return res.status(403).json({error:'Nemáte oprávnenie'});
  req.user=u; req._auditActor=u.name; next();
};

// Ambasádorská sekcia — odomkne sa až tomu, komu rolu pridelí admin.
const ambassadorAuth = async(req,res,next)=>{
  if(!req.session?.uid) return res.status(401).json({error:'Nie ste prihlásený'});
  const u = await q.one(db.users,{_id:req.session.uid});
  // Tréner je automaticky ambasádor — reprezentuje firmu a privádza ľudí,
  // takže sekciu má sprístupnenú bez prepínania.
  if(!u || !(u.is_admin || u.user_type==='ambassador' || u.user_type==='trainer' || u.is_assistant))
    return res.status(403).json({error:'Táto časť je len pre ambasádorky Fusion Academy'});
  req.ambUser = u;
  next();
};


