// Aktivačné maily: +3 h („Ešte ti chýba jeden krok") a D2 („Stále chceš skúsiť Zumbu?").
// Pred odoslaním sa stav vždy prepočíta zo zdrojových dát; dedupe cez booking_nudge*_at.
async function firstBookingNudgeTick(){
  const MIN1=+(process.env.FIRST_NUDGE_MIN_MIN||180);       // +3 h
  const MIN2=+(process.env.FIRST_NUDGE2_MIN_MIN||2*24*60);  // D2
  let budget=30;
  const out={checked:0, selected:[], sent:0};
  if(!(await mailBudgetOk(5))) return out;
  const isTestU=x=>/test/i.test(x.name||'')||/test/i.test(x.email||'');
  const now=Date.now();
  const users=(await q.find(db.users,{account_creation_type:'self_registration'}))
    .filter(u=>u.registration_at && u.email && /@/.test(u.email)
      && !/@import\.local$|@guest\./i.test(u.email)
      && !u.do_not_contact && !u.offers_optout && !isTestU(u) && u.active!==false);
  for(const u of users){
    if(budget<=0) break;
    const ageMin=(now-Date.parse(u.registration_at))/60000;
    if(!(ageMin>=MIN1 && ageMin<14*24*60)) continue;
    const which = !u.booking_nudge1_at ? 1 : (!u.booking_nudge2_at && ageMin>=MIN2 ? 2 : 0);
    if(!which) continue;
    out.checked++;
    if(!(await firstBookingEligible(u))) continue;   // revalidácia stavu tesne pred odoslaním
    const items=await firstClassSuggestions(u,3);
    if(!items.length) continue;
    out.selected.push(u.email);
    const first=String(u.name||'').split(' ')[0]||'tanečníčka';
    const list=items.map(i=>'<li><b>'+i.day_name+' '+i.date.slice(8,10)+'. '+i.date.slice(5,7)+'.</b> · '+i.time_start+' · '+i.name+' · '+i.city+'</li>').join('');
    const cta=APP_URL+'/client-dashboard?utm_source=email&utm_medium=activation&utm_campaign=first-booking-nudge'+which;
    const subj = which===1 ? 'Ešte ti chýba jeden krok 💃' : 'Stále chceš skúsiť Zumbu? 💃';
    const body = which===1
      ? '<p>registráciu už máš hotovú — teraz si už len vyber hodinu, na ktorú chceš prísť. <b>Prvá návšteva je zadarmo.</b></p><p>Najbližšie termíny:</p><ul style="line-height:1.9">'+list+'</ul><p>Rezervácia zaberie pár sekúnd a nič ťa nestojí.</p>'
      : '<p>tvoja <b>prvá hodina zadarmo</b> stále čaká. Nemusíš vedieť tancovať — stačí prísť, trénerka ťa prevedie hodinou.</p><p>Najbližšie termíny:</p><ul style="line-height:1.9">'+list+'</ul>';
    const ok=await sendMail(u.email, subj, emailTemplate('Ahoj '+first+'! 💛', body, '🗓️ Vybrať si hodinu', cta), {priority:5, template:'first_booking_nudge'}).catch(()=>false);
    if(ok){ out.sent++; budget--; await q.update(db.users,{_id:u._id},{$set:{['booking_nudge'+which+'_at']:nowISO()}}); }
  }
  return out;
}
setInterval(()=>{ firstBookingNudgeTick().catch(e=>console.error('first booking nudge:',e.message)); }, 20*60*1000);
// QA/ops: manuálne spustenie ticku (vráti koho vybral a koľkým reálne poslal)
app.post('/api/admin/qa/run-first-booking-nudge', adminAuth, async(req,res)=>{
  try{ res.json({ok:true, ...(await firstBookingNudgeTick())}); }
  catch(e){ res.status(500).json({error:e.message}); }
});

// ── Zabudnuté heslo: klientka si ho resetne sama cez e-mail ──────────────────
// Bez potvrdzovania existencie účtu (žiadne user-enumeration), token platí 60 min,
// v DB je len jeho SHA-256 hash. Po resete sa zneplatnia staré prihlásenia (sess_ver).
const rlForgot = rateLimit({max:5, windowMs:15*60*1000, message:'Priveľa žiadostí o reset hesla. Skús to o 15 minút.'});
app.post('/api/forgot-password', rlForgot, async(req,res)=>{
  try{
    const email=String(req.body.email||'').toLowerCase().trim();
    res.json({ok:true, message:'Ak účet existuje, poslali sme naň e-mail s odkazom na reset hesla.'});
    if(!email || !/@/.test(email) || /@import\.local$|@guest\./i.test(email)) return;
    const u=await q.one(db.users,{email});
    if(!u || u.active===false) return;
    if(!u.password && u.google_id){
      await sendMail(email,'Prihlásenie do Fusion Academy',
        emailTemplate('Tvoj účet používa Google 💛',
        '<p>Chcela si si resetovať heslo, ale tvoj účet nemá heslo — prihlasuješ sa tlačidlom <b>Prihlásiť sa cez Google</b> (účet '+email+').</p><p>Ak si o reset nežiadala ty, tento e-mail pokojne ignoruj.</p>',
        '🔑 Prihlásiť sa', APP_URL+'/')).catch(()=>{});
      return;
    }
    const crypto=require('crypto');
    const token=crypto.randomBytes(32).toString('hex');
    const hash=crypto.createHash('sha256').update(token).digest('hex');
    await q.update(db.users,{_id:u._id},{$set:{pw_reset_token_hash:hash, pw_reset_expires:new Date(Date.now()+60*60*1000).toISOString()}});
    const first=String(u.name||'').split(' ')[0]||'tanečníčka';
    await sendMail(email,'Reset hesla — Fusion Academy',
      emailTemplate('Ahoj '+first+'! 🔑',
      '<p>Prišla nám žiadosť o reset hesla k tvojmu účtu. Nové heslo si nastavíš kliknutím na tlačidlo — odkaz platí <b>60 minút</b>.</p><p>Ak si o reset nežiadala ty, tento e-mail ignoruj — heslo zostáva nezmenené.</p>',
      '🔐 Nastaviť nové heslo', APP_URL+'/reset-heslo?t='+token),{priority:2, template:'password_reset'}).catch(()=>{});
  }catch(e){ console.error('forgot-password:', e.message); }
});

app.post('/api/reset-password', rlLogin, async(req,res)=>{
  try{
    const token=String(req.body.token||''); const password=String(req.body.password||'');
    if(!/^[a-f0-9]{64}$/.test(token)) return res.status(400).json({error:'Neplatný odkaz na reset hesla.'});
    if(password.length<6) return res.status(400).json({error:'Heslo musí mať aspoň 6 znakov.'});
    const crypto=require('crypto');
    const hash=crypto.createHash('sha256').update(token).digest('hex');
    const u=await q.one(db.users,{pw_reset_token_hash:hash});
    if(!u || !u.pw_reset_expires || u.pw_reset_expires < nowISO())
      return res.status(400).json({error:'Odkaz je neplatný alebo vypršal (platí 60 minút). Požiadaj o reset znova.'});
    const newVer=(u.sess_ver||0)+1;
    await q.update(db.users,{_id:u._id},{$set:{password:await bcrypt.hash(password,10), sess_ver:newVer},
      $unset:{pw_reset_token_hash:true, pw_reset_expires:true, pw_reset:true}});
    req.session.uid=u._id; req.session.sv=newVer; // rovno ju prihlás
    await q.insert(db.notifications,{user_id:u._id,type:'security',title:'🔐 Heslo zmenené',
      body:'Tvoje heslo bolo práve zmenené cez e-mailový reset. Ak si to nebola ty, ozvi sa nám.',read:false,created_at:nowISO()}).catch(()=>{});
    res.json({ok:true, redirect_to:dashUrlFor(u)});
  }catch(e){ res.status(500).json({error:e.message}); }
});

// Klient si po admin resete vytvorí nové heslo (bez starého). Funguje len ak má nastavený pw_reset.
app.post('/api/set-new-password', rlLogin, async(req,res)=>{
  try {
    const {email,password}=req.body;
    if(!password || password.length<6) return res.status(400).json({error:'Heslo musí mať aspoň 6 znakov'});
    const u=await q.one(db.users,{email:(email||'').toLowerCase().trim()});
    if(!u || !u.pw_reset) return res.status(400).json({error:'Pre tento email nie je vyžiadaný reset hesla. Skús sa prihlásiť alebo zaregistrovať.'});
    if(u.active===false) return res.status(403).json({error:'Váš účet je zablokovaný. Kontaktujte správcu.'});
    // Okno na nastavenie hesla je časovo obmedzené (72 h od resetu) — bez toho by
    // ktokoľvek, kto pozná e-mail, mohol účet prevziať kedykoľvek v budúcnosti.
    if(u.pw_reset_at){
      const ageH=(Date.now()-new Date(u.pw_reset_at).getTime())/3600000;
      if(ageH>72){
        await q.update(db.users,{_id:u._id},{$set:{pw_reset:false}});
        return res.status(400).json({error:'Platnosť resetu vypršala (72 hodín). Požiadaj správcu o nový reset hesla.'});
      }
    }
    await q.update(db.users,{_id:u._id},{$set:{password:await bcrypt.hash(password,10), pw_reset:false, pw_reset_at:null}});
    // Stopa pre audit: kto a kedy si po resete nastavil nové heslo
    await q.insert(db.audit,{action:'password_set_after_reset', actor:u.name, target:u._id,
      meta:{email:u.email, ip:req.ip||''}, created_at:nowISO()}).catch(()=>{});
    req.session.uid=u._id;
    req.session.sv=(u.sess_ver||0);
    res.json({ok:true, redirect_to:dashUrlFor(u)});
  } catch(e){ res.status(500).json({error:e.message}); }
});

// Pri registrácii: zisti, či daný email už evidujeme (importovaný z Glofoxu, ešte bez hesla),
// aby sme jej ukázali „už ťa máme, stačí nastaviť heslo" + čo na ňu čaká (vstupy / členstvo).
app.get('/api/check-registration', rlLookup, async(req,res)=>{
  try {
    const email=(req.query.email||'').toLowerCase().trim();
    if(!email || !/@/.test(email)) return res.json({pending:false});
    const u=await q.one(db.users,{email});
    // Účet, ktorý si ešte nenastavil heslo (importovaný lead/člen alebo po admin resete)
    const pending = u && !u.password && (u.imported || u.pw_reset);
    if(!pending) return res.json({pending:false});
    const m = await checkMembership(u._id);
    res.json({
      pending:true,
      name:u.name||'',
      entries: u.single_entries||0,
      membership: m ? {plan_name:m.plan_name||'Členstvo', expires_at:m.expires_at} : null,
      reset: !!u.pw_reset && !u.imported
    });
  } catch(e){ res.json({pending:false}); }
});

// Celé meno: aspoň 2 slová po 2+ písmenách, bez bodiek/číslic (nie „erika.magurova" ani „zuzana")
function validFullName(n){
  const t=String(n||'').trim().replace(/\s+/g,' ');
  if(t.length<5 || t.length>80) return false;
  if(/[.@_\/0-9]/.test(t)) return false;
  const words=t.split(' ').filter(w=>/^[A-Za-zÀ-ž\u0100-\u017F\u0400-\u04FF'-]{2,}$/.test(w));
  return words.length>=2;
}
app.post('/api/register', rlSignup, async(req,res)=>{
  try {
    const {name,email,password,phone,sponsorCode,user_type}=req.body;
    if(!name||!email||!password) return res.status(400).json({error:'Meno, email a heslo sú povinné'});
    // Serverová validácia (frontend sa dá obísť) — formát mailu, dĺžka hesla a rozumné limity polí
    const emailNorm=String(email||'').toLowerCase().trim();
    if(!/^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(emailNorm) || emailNorm.length>120)
      return res.status(400).json({error:'Zadaj platnú e-mailovú adresu.'});
    if(String(password).length<6) return res.status(400).json({error:'Heslo musí mať aspoň 6 znakov.'});
    if(String(name).trim().length<2 || String(name).length>80)
      return res.status(400).json({error:'Meno musí mať 2 až 80 znakov.'});
    if(!validFullName(name))
      return res.status(400).json({error:'Zadaj celé meno a priezvisko — napr. „Erika Magurová" (bez bodiek a skratiek).'});
    if(phone && String(phone).length>30) return res.status(400).json({error:'Telefónne číslo je príliš dlhé.'});
    // ── Existujúci e-mail? Ak je to importovaný lead bez účtu, „claimni" ho ───────
    const existing=await q.one(db.users,{email:emailNorm});
    if(existing){
      if(!existing.password && ((existing.imported && !existing.claimed) || existing.pw_reset || existing.guest)){
        const set={ password:await bcrypt.hash(password,10), claimed:true, pw_reset:false,
          name: (name||existing.name), phone: (phone||existing.phone||''),
          city: String(req.body.city||existing.city||'').trim().slice(0,60),
          consent_at: req.body.consent ? nowISO() : existing.consent_at,
          free_credits: existing.guest ? (existing.free_credits||0) : Math.max(existing.free_credits||0, 1) }; // guest už má prvú hodinu cez booking — nestackovať
        if(existing.guest){ set.guest=false; }
        await q.update(db.users,{_id:existing._id},{$set:set});
        req.session.uid=existing._id;
        req.session.sv=existing.sess_ver||0;
        cancelSequence(existing._id,'app_launch').catch(()=>{});
        // upozorni adminov o novej registrácii
        try { const admins=await q.find(db.users,{is_admin:true});
          for(const a of admins) await q.insert(db.notifications,{user_id:a._id,type:'new_lead',
            title:'🆕 Importovaný lead si vytvoril účet',
            body:`${set.name} · ${emailNorm}`, read:false, created_at:nowISO()}); } catch(e){}
        announceNewMember(existing._id).catch(()=>{});
        return res.json({ ok:true, id:existing._id, claimed:true, free_bonus:true, redirect_to:'/client-dashboard' });
      }
      return res.status(400).json({error:'Tento e-mail je už zaregistrovaný. Skús sa prihlásiť.'});
    }
    let sponsor_id=null;
    if(sponsorCode&&sponsorCode.toUpperCase()!=='ADMIN'){
      const sp=await q.one(db.users,{referral_code:new RegExp('^'+sponsorCode+'$','i')});
      if(!sp) return res.status(400).json({error:'Referral kód neexistuje'});
      sponsor_id=sp._id;
    }
    // No sponsor → assign the founder (Marek Gruber) as default sponsor,
    // so every member always sits under someone in the structure.
    if(!sponsor_id){
      const founder=await q.one(db.users,{email:'gruber.marek@gmail.com'});
      if(founder && founder.email!==email.toLowerCase().trim()) sponsor_id=founder._id;
    }
    const base=name.split(' ')[0].toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,8);
    let code=base+Math.floor(10+Math.random()*90);
    while(await q.one(db.users,{referral_code:code})) code=base+Math.floor(100+Math.random()*900);
    // New self-registrations start as a LEAD (admins call/nurture them) and are
    // auto-promoted to 'client' on their first paid purchase. Explicit staff
    // roles (trainer/partner/manager/admin) passed via API are kept as given.
    const utype = (user_type && !['client','lead'].includes(user_type)) ? user_type : 'lead';
    // ── Marketing attribution (first-touch, captured client-side) ─────────────
    const attr = req.body.attribution||{};
    const clean = v => String(v||'').slice(0,200);
    const utm_source=clean(attr.utm_source), utm_medium=clean(attr.utm_medium), utm_campaign=clean(attr.utm_campaign);
    const fbclid=clean(attr.fbclid), gclid=clean(attr.gclid);
    let lead_source = req.body.lead_source||'';
    if(!lead_source){
      if(gclid) lead_source='google';
      else if(fbclid) lead_source='meta';
      else if(utm_source) lead_source=utm_source.toLowerCase();
      else if(sponsor_id) lead_source='referral';
    }
    // ── Venčekový registračný kód (QR triedy): priradí účet ku škole a triede ──
    let vencekClass=null, vencekRole='student';
    if(req.body.vencek_code){
      vencekClass=await q.one(db.venceky_classes,{code:String(req.body.vencek_code).toUpperCase().trim()});
      if(!vencekClass) return res.status(400).json({error:'Venčekový kód triedy neexistuje. Skontroluj QR/kód od školy.'});
      vencekRole=['student','parent','teacher','director'].includes(req.body.vencek_role)?req.body.vencek_role:'student';
    }
    const u=await q.insert(db.users,{name,email:email.toLowerCase().trim(),password:await bcrypt.hash(password,10),phone:phone||'',city:String(req.body.city||'').trim().slice(0,60),referral_code:code,sponsor_id,rank:1,is_admin:false,active:true,user_type:utype,bank_account:'',notes:'',visit_count:0,referral_credit:0,lead_source,utm_source,utm_medium,utm_campaign,fbclid,gclid,landing_page:clean(attr.landing),referrer:clean(attr.referrer),consent_at: req.body.consent ? nowISO() : null,created_at:today(),account_creation_type:'self_registration',registration_at:nowISO(),registration_at_source:'actual',
      ...(vencekClass? (['student','parent'].includes(vencekRole)
        ? {venceky_class_id:vencekClass._id, venceky_school_id:vencekClass.school_id, venceky_role:vencekRole,
           ...(vencekRole==='parent'?{vencek_child_name:String(req.body.vencek_child_name||'').slice(0,80)}:{})}
        : {vencek_pending_role:vencekRole, vencek_pending_class_id:vencekClass._id, vencek_pending_school_id:vencekClass.school_id})
      :{})});
    if(vencekClass){
      const roleLbl={student:'žiak',parent:'rodič',teacher:'UČITEĽ — čaká na schválenie',director:'RIADITEĽ — čaká na schválenie'}[vencekRole];
      try{ const admins=await q.find(db.users,{is_admin:true});
        for(const a of admins) await q.insert(db.notifications,{user_id:a._id,type:'venceky',
          title: ['teacher','director'].includes(vencekRole)?'⏳ Venčeky: čaká na schválenie':'🎓 Nový venčekár',
          body:`${name} (${roleLbl}) — trieda ${vencekClass.name}${vencekRole==='parent'&&req.body.vencek_child_name?' · dieťa: '+String(req.body.vencek_child_name).slice(0,80):''}`,
          read:false, created_at:nowISO()}); }catch(e){}
      if(['teacher','director'].includes(vencekRole)){
        await q.insert(db.notifications,{user_id:u._id,type:'venceky',
          title:'⏳ Účet čaká na schválenie',
          body:'Ďakujeme! Prístup učiteľa/riaditeľa k venčekovému prehľadu vám odomkneme po overení — zvyčajne do pár hodín. Zvyšok appky môžete používať hneď.',
          read:false, created_at:nowISO()}).catch(()=>{});
      }
      // Uvítacie benefity: 1× Zumba zdarma hneď + kupón VENCEKRODIC = 1. mesiac Zumby ZADARMO
      // (poďakovanie rodičom aj zamestnancom školy, že si vybrali práve nás)
      if(['student','parent'].includes(vencekRole)) try{
        const vrp=await q.one(db.promo_codes,{code:'VENCEKRODIC'});
        if(!vrp)
          await q.insert(db.promo_codes,{ code:'VENCEKRODIC', type:'percent', value:100, applies_to:'membership',
            max_uses:0, once_per_user:true, min_amount:0, expires_at:null, active:true, used_count:0,
            note:'Venčeky — mesiac Zumby zadarmo pre rodičov a zamestnancov školy', created_at:nowISO() });
        else if(vrp.value!==100)
          await q.update(db.promo_codes,{_id:vrp._id},{$set:{value:100,
            note:'Venčeky — mesiac Zumby zadarmo pre rodičov a zamestnancov školy'}});
        await q.update(db.users,{_id:u._id},{$set:{free_credits:1}});
        await q.insert(db.notifications,{user_id:u._id,type:'venceky',
          title:'🎁 Vitaj vo Fusion Venčekoch!',
          body:'Máš u nás 1× vstup na Zumbu ZDARMA a kupón VENCEKRODIC = celý 1. MESIAC Zumby zadarmo (platí aj pre rodičov) — poďakovanie, že ste si vybrali práve nás. 💛',
          read:false, created_at:nowISO()});
      }catch(e){}
    }
    req.session.uid=u._id;
    req.session.sv=0;
    // ── Referral: za SAMOTNÚ registráciu už NIE JE odmena (zneužívalo by sa) ───
    // Kredit sponzorovi ide až keď privedený človek reálne MINIE peniaze
    // (10 % z členstva / permanentky — rieši sa pri platbe, nie tu).
    if(sponsor_id){
      const sp = await q.one(db.users,{_id:sponsor_id});
      if(sp){
        await q.insert(db.notifications,{user_id:sponsor_id,type:'referral_credit',title:`🎉 ${name} sa registroval/a cez tvoj link!`,body:`Odmena ti príde, keď si kúpi členstvo alebo vstupy (10 % z nákupu).`,read:false,created_at:nowISO()});
      }
      referralGoalCheck(sponsor_id).catch(()=>{});
      // Structure-growth notification for everyone higher up the chain (beyond the direct sponsor)
      const ancestors = await getAllAncestors(sponsor_id); // sponsor's own upline
      for(const aid of ancestors){
        const total = await downlineCountOf(aid);
        await q.insert(db.notifications,{user_id:aid, type:'structure_growth',
          title:'📈 Tvoja štruktúra narástla!',
          body:`${name} sa pridal/a do tvojej štruktúry. Spolu máš už ${total} ľudí pod sebou.`,
          read:false, created_at:nowISO()}).catch(()=>{});
      }
    }
    // Notify all admins about the new lead (in-app + email) so they can call/nurture
    if(utype==='lead'){
      const sponsorName = sponsor_id ? (await q.one(db.users,{_id:sponsor_id}))?.name : null;
      const src = lead_source ? ` · zdroj: ${lead_source}` : '';
      const admins = await q.find(db.users,{is_admin:true});
      for(const a of admins){
        await q.insert(db.notifications,{user_id:a._id, type:'new_lead',
          title:'🆕 Nová registrácia – lead',
          body:`${name} · ${email}${phone?' · '+phone:''}${sponsorName?' · sponzor: '+sponsorName:''}${src}`,
          read:false, created_at:nowISO()});
        if(a.email && !a.email.includes('@internal.local'))
          sendMail(a.email, `🆕 Nový lead: ${name}`,
            emailTemplate('Nová registrácia – lead 📞',
              `<p>Práve sa zaregistroval nový lead:</p>
               <ul style="color:#ccc">
                 <li><b>${name}</b></li>
                 <li>✉️ ${email}</li>
                 ${phone?`<li>📞 ${phone}</li>`:''}
                 ${sponsorName?`<li>👤 Sponzor: ${sponsorName}</li>`:''}
                 ${lead_source?`<li>📍 Zdroj: ${lead_source}</li>`:''}
               </ul>
               <p>Ozvi sa mu čo najskôr a zapíš si poznámky v CRM. 💪</p>`,
              '📋 Otvoriť CRM', `${APP_URL}/admin`)).catch(()=>{});
      }
    }
    // Email automation: enqueue welcome + lead_nurture sequences
    enqueueSequence(u._id, 'welcome').then(()=>processEmailQueue()).catch(()=>{});
    enqueueSequence(u._id, 'lead_nurture').catch(()=>{});
    // Server-side conversion tracking
    metaCapi('CompleteRegistration',{email:u.email, fbclid, fbp:clean(attr.fbp),
      event_id:clean(attr.event_id)||undefined, source_url:clean(attr.landing)||undefined}).catch(()=>{});
    announceNewMember(u._id).catch(()=>{});
    res.json({ok:true, userType:utype, redirect_to: dashUrlFor(u)});
  } catch(e){
    if(e.message?.includes('unique')) return res.status(400).json({error:'Email je už zaregistrovaný'});
    res.status(500).json({error:e.message});
  }
});

