// Admin: referral funnel (kliky → mestá → hodiny → bookingy → prišli → kúpili)
app.get('/api/admin/referral-funnel', adminAuth, async(req,res)=>{
  try{
    const ev=(await q.find(db.referral_events,{})).filter(e=>!e.test);
    const cnt=t=>ev.filter(e=>e.type===t).length;
    const bookedEv=ev.filter(e=>e.type==='booked');
    const guestIds=[...new Set(bookedEv.map(e=>e.guest_id).filter(Boolean))];
    let attended=0, purchased=0, second=0;
    for(const gid of guestIds){
      const bs=await q.find(db.bookings,{user_id:gid});
      const att=bs.filter(b=>b.status==='attended').length;
      if(att>=1) attended++;
      if(att>=2) second++;
      if(await q.one(db.transactions,{user_id:gid})) purchased++;
    }
    const steps=[
      {label:'Otvorili pozvánku', n:cnt('click')},
      {label:'Vybrali mesto', n:cnt('city')},
      {label:'Rezervovali hodinu', n:cnt('booked')},
      {label:'Prišli na 1. hodinu', n:attended},
      {label:'Nakúpili', n:purchased},
      {label:'Prišli na 2. hodinu', n:second},
    ];
    // per pozývajúca klientka
    const bySp={};
    for(const e of ev){ const k=e.sponsor_id; bySp[k]=bySp[k]||{clicks:0,booked:0,guests:new Set()};
      if(e.type==='click') bySp[k].clicks++;
      if(e.type==='booked'){ bySp[k].booked++; if(e.guest_id) bySp[k].guests.add(e.guest_id); } }
    const users=await q.find(db.users,{});
    const uMap=Object.fromEntries(users.map(x=>[x._id,x.name]));
    const inviters=[];
    for(const [sid,d] of Object.entries(bySp)){
      let att=0, buy=0;
      for(const gid of d.guests){ const bs=await q.find(db.bookings,{user_id:gid});
        if(bs.some(b=>b.status==='attended')) att++;
        if(await q.one(db.transactions,{user_id:gid})) buy++; }
      inviters.push({name:uMap[sid]||'?', clicks:d.clicks, booked:d.booked, attended:att, purchased:buy});
    }
    inviters.sort((a,b)=>b.booked-a.booked);
    res.json({ok:true, steps, inviters:inviters.slice(0,30)});
  }catch(e){ res.status(500).json({error:e.message}); }
});

app.get('/api/public/schedule', async(req,res)=>{
  try{
    res.setHeader('Access-Control-Allow-Origin','*');
    if(pubSchedCache && Date.now()-pubSchedCache.at<5*60*1000) return res.json(pubSchedCache.data);
    const classes=(await q.find(db.classes,{active:true}))
      .filter(c=>classRunsOn(c, displayNextDateForDay(c.day_of_week)))
      .sort((a,b)=>(a.day_of_week-b.day_of_week)||String(a.time_start||'').localeCompare(b.time_start||''));
    const out=[];
    for(const c of classes){
      const date=displayNextDateForDay(c.day_of_week);
      const cancel=await q.one(db.class_cancellations,{class_id:c._id, date});
      const booked=(await q.find(db.bookings,{class_id:c._id, booking_date:date})).filter(b=>b.status!=='cancelled').length;
      let instructor=c.instructor||'';
      try{
        if(c.category==='Online') instructor=await onlineInstructorFor(c, date);
        else { const si=await sessionInstructor(c, date); if(si?.overridden) instructor=si.instructor; }
      }catch(e){}
      out.push({ name:c.name, category:c.category||'', location:c.location||'', day_of_week:c.day_of_week,
        time_start:c.time_start||'', time_end:c.time_end||'', instructor,
        next_date:date, cancelled:!!cancel, cancel_reason:cancel?.reason||null,
        capacity:+c.capacity||0, spots_left: c.capacity? Math.max(0,(+c.capacity)-booked) : null });
    }
    const data={ok:true, classes:out, updated_at:nowISO()};
    pubSchedCache={at:Date.now(), data};
    res.json(data);
  }catch(e){ res.status(500).json({error:e.message}); }
});

app.get('/api/classes', async(req,res)=>{
  try {
    const loggedIn = !!(req.session && req.session.uid);
    const viewer = loggedIn ? await q.one(db.users,{_id:req.session.uid}).catch(()=>null) : null;
    // Jednorazové termíny po svojom dni miznú klientkam aj trénerom; admin ich vidí
    // ďalej, aby ich vedel dočistiť.
    const allCls = await q.find(db.classes,{active:true});
    const classes = viewer?.is_admin ? allCls
      : allCls.filter(c=>classRunsOn(c, displayNextDateForDay(c.day_of_week)));
    const result=[];
    for(const c of classes){
      const bdate = displayNextDateForDay(c.day_of_week);
      const booking_count = await q.count(db.bookings,{class_id:c._id, booking_date:bdate, status:{$ne:'cancelled'}});
      const bookedAll = await q.count(db.bookings,{class_id:c._id,status:{$ne:'cancelled'}});
      // Obohatenie (inštruktor + prihlásení) je „best effort" — nesmie zhodiť načítanie hodín.
      let si={instructor:c.instructor||'—', instructor_id:c.instructor_id||null};
      let attendees;
      try {
        si = await sessionInstructor(c, bdate);
        if(loggedIn){
          // len id/meno + av flag (fotka sa ťahá cez /api/avatar/:id — žiadne base64 v JSON)
          const rows=await q.find(db.bookings,{class_id:c._id, booking_date:bdate, status:{$in:['confirmed','attended']}});
          attendees=[];
          for(const r of rows){
            if(r.is_child_booking){ attendees.push({name:r.child_name||'dieťa', child:true, parent:r.booked_by_name||null}); continue; }
            const ru=await q.one(db.users,{_id:r.user_id});
            if(isTestContact(ru?.email)) continue; // 🕵️ test účet nikdy nezobrazovať klientkam
            attendees.push({id:r.user_id, name:r.user_name||ru?.name||'Člen', av:!!(ru&&ru.avatar)});
          }
        }
      } catch(e){ console.error('classes enrich:', e.message); }
      // Zrušený najbližší termín — klient to MUSÍ vidieť na karte, nie až pri rezervácii
      const cancelRec = await q.one(db.class_cancellations,{class_id:c._id, date:bdate}).catch(()=>null);
      result.push({...c, booking_count, next_date:bdate, booked:booking_count, booked_all:bookedAll,
        instructor:si.instructor, instructor_id:si.instructor_id||c.instructor_id||null,
        attendees, attendee_count: attendees?attendees.length:booking_count,
        cancelled: !!cancelRec, cancel_reason: cancelRec?.reason||null,
        spotsLeft:Math.max(0,c.capacity-booking_count), dayName:DAYS_SK[c.day_of_week]});
    }
    result.sort((a,b)=>(a.day_of_week||0)-(b.day_of_week||0)||String(a.time_start||'').localeCompare(String(b.time_start||'')));
    res.json(result);
  } catch(e){ console.error('/api/classes:', e.message); res.status(500).json({error:e.message}); }
});

// Avatar používateľa ako OBRÁZOK (nie base64 v JSON) — prehliadač ho načíta lenivo a nezaťaží zoznamy.
app.get('/api/avatar/:userId', async(req,res)=>{
  try{
    const u=await q.one(db.users,{_id:req.params.userId});
    // Rešpektuj anonymitu — kto si zapol „anonymný profil", nesmie mať verejnú fotku
    // (ostatné endpointy anonymitu ctia, tento ju obchádzal).
    if(u && u.anonymous && req.session?.uid !== u._id) return res.status(404).end();
    const av=u&&u.avatar;
    const m = typeof av==='string' && av.match(/^data:(image\/[a-z+]+);base64,(.+)$/i);
    if(!m) return res.status(404).end();
    res.set('Content-Type', m[1]);
    res.set('Cache-Control', 'private, max-age=300'); // 5 min cache
    res.send(Buffer.from(m[2], 'base64'));
  }catch(e){ res.status(404).end(); }
});

// Zoznam prihlásených NA JEDNU hodinu (mená + či majú fotku; fotka sa ťahá cez /api/avatar/:id)
app.get('/api/classes/:id/attendees', auth, async(req,res)=>{
  try{
    const c=await q.one(db.classes,{_id:req.params.id});
    if(!c) return res.status(404).json({error:'Hodina nenájdená'});
    const date=/^\d{4}-\d{2}-\d{2}$/.test(req.query.date||'') ? req.query.date : displayNextDateForDay(c.day_of_week);
    const rows=await q.find(db.bookings,{class_id:c._id, booking_date:date, status:{$in:['confirmed','attended']}});
    const list=[];
    const me=req.session.uid;
    for(const r of rows){
      if(r.is_child_booking){ list.push({name:r.child_name||'dieťa', child:true, parent:r.booked_by_name||null}); continue; }
      const ru=await q.one(db.users,{_id:r.user_id});
      if(ru && ru.anonymous){ list.push({name:'Člen (skrytý)', anonymous:true}); continue; }
      const fst = (r.user_id && r.user_id!==me) ? await friendState(me, r.user_id) : 'self';
      list.push({id:r.user_id, name:r.user_name||ru?.name||'Člen', av:!!(ru&&ru.avatar), friend_state:fst});
    }
    const si=await sessionInstructor(c, date);
    res.json({ class_name:c.name, date, instructor:si.instructor, instructor_id:si.instructor_id||null,
      instructor_av: !!(si.instructor_id && (await q.one(db.users,{_id:si.instructor_id}))?.avatar), attendees:list });
  }catch(e){ res.status(500).json({error:e.message}); }
});

app.get('/api/classes/:id', async(req,res)=>{
  const c=await q.one(db.classes,{_id:req.params.id});
  if(!c) return res.status(404).json({error:'Hodina nenájdená'});
  const bdate = displayNextDateForDay(c.day_of_week);
  const booking_count = await q.count(db.bookings,{class_id:c._id, booking_date:bdate, status:{$ne:'cancelled'}});
  const si = await sessionInstructor(c, bdate);
  res.json({...c, booking_count, next_date:bdate, booked:booking_count, instructor:si.instructor, instructor_id:si.instructor_id||c.instructor_id||null, spotsLeft:Math.max(0,c.capacity-booking_count), dayName:DAYS_SK[c.day_of_week]});
});

