// Search people by name to add as friends (anonymous users are hidden)
app.get('/api/community/search', auth, async(req,res)=>{
  try {
    const me=req.session.uid;
    const s=(req.query.q||'').trim().toLowerCase();
    if(s.length<2) return res.json({people:[]});
    let users=await q.find(db.users,{is_admin:{$ne:true},active:true,is_child:{$ne:true},anonymous:{$ne:true},$or:[{imported:{$ne:true}},{claimed:true}]});
    users=users.filter(u=>u._id!==me && ((u.nickname||'').toLowerCase().includes(s) || (u.name||'').toLowerCase().includes(s)));
    users=users.slice(0,20);
    const people=await Promise.all(users.map(async u=>{
      const refCount=await downlineCountOf(u._id);
      const nb=referralBadge(refCount, u.gender==='male'?'male':'female');
      return { id:u._id, name:u.name, nickname:u.nickname||'', avatar:u.avatar||null,
        name_badge: nb?`${nb.emoji} ${nb.title}`:'',
        friend_state: await friendState(me, u._id) };
    }));
    res.json({people});
  } catch(e){ res.status(500).json({error:e.message}); }
});

// ── Private messages (1-on-1 DMs between members) ─────────────────────────────
const dmKey = (a,b) => 'dm_' + [String(a),String(b)].sort().join('_');

// List my conversations (other participant, last message, unread count)
app.get('/api/dm/conversations', auth, async(req,res)=>{
  const me = req.session.uid;
  const msgs = await q.find(db.messages, {is_dm:true, participants:me});
  const convs = {};
  for(const m of msgs){
    const other = m.from_id===me ? m.to_id : m.from_id;
    const c = convs[other] = convs[other] || {other_id:other, last_text:'', last_at:'', last_from:'', unread:0};
    if(!c.last_at || m.created_at>c.last_at){ c.last_at=m.created_at; c.last_text=m.text; c.last_from=m.from_id; }
    if(m.to_id===me && !m.read) c.unread++;
  }
  const users = Object.fromEntries((await q.find(db.users,{})).map(u=>[u._id,u]));
  const list = Object.values(convs).map(c=>({
    ...c, other_name: users[c.other_id]?.name||'Neznámy užívateľ',
    other_badge: getMemberBadge(users[c.other_id]?.created_at, users[c.other_id])
  })).sort((a,b)=>(b.last_at||'').localeCompare(a.last_at||''));
  res.json({conversations:list, unread_total:list.reduce((s,c)=>s+c.unread,0)});
});

// Message history with one user (marks incoming as read)
app.get('/api/dm/history/:userId', auth, async(req,res)=>{
  const me = req.session.uid, other = req.params.userId;
  if(other===me) return res.status(400).json({error:'Nemôžeš písať sám sebe'});
  const other_u = await q.one(db.users,{_id:other});
  if(!other_u) return res.status(404).json({error:'Užívateľ nenájdený'});
  const key = dmKey(me,other);
  const msgs = await q.find(db.messages,{is_dm:true, dm_key:key},{created_at:1});
  await q.update(db.messages,{is_dm:true,dm_key:key,to_id:me,read:{$ne:true}},{$set:{read:true}},{multi:true});
  // Zmaž aj zvončekovú notifikáciu o neprečítaných správach od tohto odosielateľa
  await q.update(db.notifications,{user_id:me, type:'dm', from_id:other, read:false},{$set:{read:true}},{multi:true});
  res.json({ messages: msgs.slice(-100),
    other:{ id:other, name:other_u.name, badge:getMemberBadge(other_u.created_at, other_u) } });
});

// ── Community feed (nástenka): posts + reactions + comments ───────────────────
const FEED_EMOJIS = ['❤️','👏','🔥','💪','🎉'];
function feedView(p, meId, nameMap, meIsAdmin, voterMap, starsList){
  const nm = id => (nameMap && nameMap[id]) || 'Člen';
  const reactions = p.reactions||{};
  const summary = FEED_EMOJIS.map(e=>{ const ids=reactions[e]||[];
    return { emoji:e, count:ids.length, mine:ids.includes(meId), likers: ids.map(id=>({id,name:nm(id)})) }; });
  const comments = (p.comments||[]).slice(-20).map(c=>({
    id:c.id||null, user_id:c.user_id, name:c.name, text:c.text, at:c.at,
    likes:(c.likes||[]).length, liked:(c.likes||[]).includes(meId),
    likers:(c.likes||[]).map(id=>({id,name:nm(id)}))
  }));
  return {
    id:p._id, author_id:p.author_id, author_name:p.author_name, author_badge:p.author_badge||null,
    text:p.text||'', image:p.image||null, created_at:p.created_at,
    system_event: !!p.system_event,
    event_kind: p.event_kind||null,
    event_avatar: p.event_avatar||null,
    event_actors: p.event_actors||[],
    event_cta: p.event_cta||null,
    pinned: !!p.pinned,
    poll: p.poll ? pollResult(p, meId, voterMap) : null,
    stars: p.event_kind==='top_stars' ? (starsList||[]) : null,
    reactions:summary,
    comments,
    comment_count:(p.comments||[]).length,
    can_delete: p.author_id===meId || !!meIsAdmin
  };
}
// ── Komunitná nástenka: automatické oznamy o dianí v komunite ─────────────────
async function postCommunityEvent(opts){
  try{
    const post = await q.insert(db.feed,{
      author_id:'community', author_name:'Komunita', author_badge:{emoji:'🤝',label:'Komunita'},
      system_event:true, event_kind:opts.kind||'', event_avatar:opts.avatar||null,
      event_actors:(opts.actors||[]).filter(a=>a&&a.id).map(a=>({id:a.id,name:a.name||'Člen'})),
      event_cta:opts.cta||null,
      text:opts.text||'', image:null, reactions:{}, comments:[], created_at:nowISO()
    });
    io.emit('feed_new', feedView(post, null));
  }catch(e){}
}
// Nedávno už bol rovnaký typ oznamu pre daného člena? (proti spamu — napr. zmena fotky)
async function recentCommunityEvent(kind, actorId, hours){
  try{
    const since = new Date(Date.now()-hours*3600e3).toISOString();
    const hit = await q.one(db.feed,{ system_event:true, event_kind:kind, 'event_actors.id':actorId, created_at:{$gte:since} });
    return !!hit;
  }catch(e){ return false; }
}
// Člen viditeľný v komunite? (skryté importované leady bez účtu neoznamujeme)
function isCommunityVisible(u){ return !!u && u.active!==false && !u.is_child && !(u.imported && !u.claimed); }
async function announceFriendship(idA, idB){
  const [a,b]=await Promise.all([q.one(db.users,{_id:idA}), q.one(db.users,{_id:idB})]);
  if(!isCommunityVisible(a) || !isCommunityVisible(b)) return;
  await postCommunityEvent({ kind:'friendship', avatar:a.avatar||b.avatar||null,
    actors:[{id:a._id,name:a.name},{id:b._id,name:b.name}],
    cta:'💛 Poteš ich lajkom',
    text:`🤝 ${a.name} a ${b.name} sú teraz priatelia!` });
}
async function announceGiftCredit(gifterId, recipientId, amount, anon){
  const rcpt=await q.one(db.users,{_id:recipientId});
  if(!isCommunityVisible(rcpt)) return;
  const gifter = anon ? null : await q.one(db.users,{_id:gifterId});
  const actors = gifter && isCommunityVisible(gifter) ? [{id:gifter._id,name:gifter.name},{id:rcpt._id,name:rcpt.name}] : [{id:rcpt._id,name:rcpt.name}];
  const who = (gifter && isCommunityVisible(gifter)) ? gifter.name : 'Niekto anonymne';
  await postCommunityEvent({ kind:'gift_credit', avatar:(gifter&&isCommunityVisible(gifter)?gifter.avatar:null)||rcpt.avatar||null,
    actors, cta:'💝 Šírme dobrú náladu',
    text:`💝 ${who} podaroval/a kredit členke ${rcpt.name}. Krásne gesto! 🌟` });
}
async function announceAvatarChange(userId){
  const u=await q.one(db.users,{_id:userId});
  if(!isCommunityVisible(u) || !u.avatar) return;
  if(await recentCommunityEvent('avatar', userId, 24)) return; // max 1× za 24h
  await postCommunityEvent({ kind:'avatar', avatar:u.avatar,
    actors:[{id:u._id,name:u.name}], cta:'👀 Mrkni na profil',
    text:`📸 ${u.name} má novú profilovku!` });
}
async function announceProfileComment(author, target, text){
  if(!isCommunityVisible(author) || !isCommunityVisible(target)) return;
  const snippet = (text||'').length>90 ? text.slice(0,90)+'…' : text;
  await postCommunityEvent({ kind:'profile_comment', avatar:author.avatar||target.avatar||null,
    actors:[{id:author._id,name:author.name},{id:target._id,name:target.name}],
    cta:'💬 Napíš aj ty niekomu na profil',
    text:`💬 ${author.name} napísal/a ${target.name} na profil: „${snippet}"` });
}
async function announceNewMember(userId){
  const u=await q.one(db.users,{_id:userId});
  if(!isCommunityVisible(u)) return;
  if(await recentCommunityEvent('welcome', userId, 168)) return; // neopakuj
  const first=(u.name||'').split(' ')[0]||u.name;
  await postCommunityEvent({ kind:'welcome', avatar:u.avatar||null,
    actors:[{id:u._id,name:u.name}], cta:'🎉 Privítaj ju',
    text:`🎉 Vitajte nového člena — ${u.name}! Privítajme ${first} komentárom alebo lajkom 💛` });
}
// Anketa žánrov — pripnutá na nástenke (idempotentne pri štarte)
