// Top hviezdy — pripnutá oslava najaktívnejších členiek (zoznam sa počíta naživo)
async function ensureTopStars(){
  try{
    const existing=await q.one(db.feed,{event_kind:'top_stars', stars_slug:'top20'});
    if(existing) return;
    await q.insert(db.feed,{
      author_id:'community', author_name:'Komunita', author_badge:{emoji:'⭐',label:'Top hviezdy'},
      system_event:true, event_kind:'top_stars', stars_slug:'top20', pinned:true,
      text:'⭐ Toto sú naše TOP hviezdy! Gratulujeme každej jednej, že si s nami užíva tie najlepšie momenty na parkete 💛',
      event_cta:'Zatlieskaj im 👏', image:null, reactions:{}, comments:[], created_at:nowISO()
    });
    console.log('✅  Top hviezdy vytvorené na nástenke');
  }catch(e){ console.error('ensureTopStars:', e.message); }
}
// Aktuálny rebríček top N členiek podľa počtu návštev (klikateľné profily)
async function computeTopStars(n){
  const users=(await q.find(db.users,{})).filter(u=>
    isCommunityVisible(u) && !u.is_admin && u.user_type!=='trainer' && (u.visit_count||0)>0);
  users.sort((a,b)=>(b.visit_count||0)-(a.visit_count||0) || (a.name||'').localeCompare(b.name||''));
  return users.slice(0,n||20).map((u,i)=>({ rank:i+1, id:u._id, name:u.nickname||u.name,
    avatar:u.avatar||null, visits:u.visit_count||0 }));
}
// Vypočíta výsledky ankety pre feedView
function pollResult(p, meId, voterMap){
  const poll=p.poll||{}; const votes=poll.votes||{}; const opts=poll.options||[];
  const tally={}; opts.forEach(o=>tally[o.key]=[]);
  Object.entries(votes).forEach(([uid,key])=>{ if(tally[key]) tally[key].push(uid); });
  const total=Object.keys(votes).length;
  let max=0; opts.forEach(o=>{ if(tally[o.key].length>max) max=tally[o.key].length; });
  return { question:poll.question||'', total, my_vote:votes[meId]||null,
    options: opts.map(o=>({ key:o.key, label:o.label, emoji:o.emoji,
      count:tally[o.key].length, pct: total?Math.round(tally[o.key].length/total*100):0,
      winning: tally[o.key].length>0 && tally[o.key].length===max,
      voters: tally[o.key].map(id=>({ id, name:(voterMap&&voterMap[id]?.name)||'Člen', avatar:(voterMap&&voterMap[id]?.avatar)||null })) })) };
}
// Postaví mapu id→meno pre všetkých, čo reagovali/komentovali na dané príspevky
async function feedNameMap(posts){
  const ids=new Set();
  posts.forEach(p=>{ Object.values(p.reactions||{}).forEach(arr=>arr.forEach(id=>ids.add(id)));
    (p.comments||[]).forEach(c=>{ if(c.user_id) ids.add(c.user_id); (c.likes||[]).forEach(id=>ids.add(id)); }); });
  const map={};
  if(ids.size){ const us=await q.find(db.users,{_id:{$in:[...ids]}}); us.forEach(u=>map[u._id]=u.nickname||u.name); }
  return map;
}
app.get('/api/feed', auth, async(req,res)=>{
  let posts = (await q.find(db.feed,{})).sort((a,b)=>(b.created_at||'').localeCompare(a.created_at||'')).slice(0,50);
  // Pripnuté (napr. anketa) idú navrch
  posts = posts.sort((a,b)=>(b.pinned?1:0)-(a.pinned?1:0));
  const nameMap = await feedNameMap(posts);
  // Mapa id→{meno,fotka} pre hlasujúcich v anketách
  const voterIds=new Set();
  posts.forEach(p=>{ if(p.poll&&p.poll.votes) Object.keys(p.poll.votes).forEach(id=>voterIds.add(id)); });
  const voterMap={};
  if(voterIds.size){ const us=await q.find(db.users,{_id:{$in:[...voterIds]}}); us.forEach(u=>voterMap[u._id]={name:u.nickname||u.name, avatar:u.avatar||null}); }
  const me = await q.one(db.users,{_id:req.session.uid});
  // Živý zoznam top hviezd (ak je taký príspevok na nástenke)
  const starsList = posts.some(p=>p.event_kind==='top_stars') ? await computeTopStars(20) : [];
  res.json(posts.map(p=>feedView(p, req.session.uid, nameMap, me?.is_admin, voterMap, starsList)));
});
app.post('/api/feed', auth, async(req,res)=>{
  try {
    const text=(req.body.text||'').trim();
    let image=req.body.image||null;
    if(image){
      if(typeof image!=='string' || !/^data:image\/(png|jpeg|jpg|webp);base64,/.test(image) || image.length>900000)
        return res.status(400).json({error:'Neplatný alebo príliš veľký obrázok'});
    }
    if(!text && !image) return res.status(400).json({error:'Prázdny príspevok'});
    if(text.length>2000) return res.status(400).json({error:'Text je príliš dlhý'});
    const u=await q.one(db.users,{_id:req.session.uid});
    const post=await q.insert(db.feed,{
      author_id:u._id, author_name:u.name, author_badge:getMemberBadge(u.created_at, u),
      text:text.slice(0,2000), image:image||null, reactions:{}, comments:[], created_at:nowISO()
    });
    const view=feedView(post, req.session.uid);
    io.emit('feed_new', view);
    res.json({ok:true, post:view});
  } catch(e){ res.status(500).json({error:e.message}); }
});
app.post('/api/feed/:id/react', auth, async(req,res)=>{
  try {
    const emoji=req.body.emoji;
    if(!FEED_EMOJIS.includes(emoji)) return res.status(400).json({error:'Neplatná reakcia'});
    const post=await q.one(db.feed,{_id:req.params.id});
    if(!post) return res.status(404).json({error:'Príspevok nenájdený'});
    const reactions=post.reactions||{};
    const arr=reactions[emoji]||[];
    const uid=req.session.uid;
    reactions[emoji] = arr.includes(uid) ? arr.filter(x=>x!==uid) : [...arr, uid];
    await q.update(db.feed,{_id:post._id},{$set:{reactions}});
    const updated=await q.one(db.feed,{_id:post._id});
    io.emit('feed_update', {id:post._id});
    res.json({ok:true, post:feedView(updated, uid, await feedNameMap([updated]))});
  } catch(e){ res.status(500).json({error:e.message}); }
});
// Hlasovanie v ankete (toggle: opätovný klik na tú istú možnosť hlas zruší)
app.post('/api/feed/:id/vote', auth, async(req,res)=>{
  try{
    const post=await q.one(db.feed,{_id:req.params.id});
    if(!post || !post.poll) return res.status(404).json({error:'Anketa nenájdená'});
    const key=String(req.body.option||'');
    if(!(post.poll.options||[]).some(o=>o.key===key)) return res.status(400).json({error:'Neplatná možnosť'});
    const uid=req.session.uid;
    const votes=post.poll.votes||{};
    if(votes[uid]===key) delete votes[uid]; else votes[uid]=key;
    await q.update(db.feed,{_id:post._id},{$set:{'poll.votes':votes}});
    io.emit('feed_update', {id:post._id});
    const updated=await q.one(db.feed,{_id:post._id});
    // znovu poskladaj voterMap
    const ids=Object.keys(votes); const voterMap={};
    if(ids.length){ const us=await q.find(db.users,{_id:{$in:ids}}); us.forEach(u=>voterMap[u._id]={name:u.nickname||u.name, avatar:u.avatar||null}); }
    const me=await q.one(db.users,{_id:uid});
    res.json({ok:true, post:feedView(updated, uid, await feedNameMap([updated]), me?.is_admin, voterMap)});
  }catch(e){ res.status(500).json({error:e.message}); }
});
// Lajk na komentár (+ kto lajkol)
app.post('/api/feed/:id/comments/:cid/like', auth, async(req,res)=>{
  try {
    const post=await q.one(db.feed,{_id:req.params.id});
    if(!post) return res.status(404).json({error:'Nenájdené'});
    const uid=req.session.uid;
    const comments=(post.comments||[]).map(c=>{
      if(c.id===req.params.cid){ const likes=c.likes||[]; c.likes = likes.includes(uid)?likes.filter(x=>x!==uid):[...likes,uid]; }
      return c;
    });
    await q.update(db.feed,{_id:post._id},{$set:{comments}});
    const updated=await q.one(db.feed,{_id:post._id});
    io.emit('feed_update', {id:post._id});
    res.json({ok:true, post:feedView(updated, uid, await feedNameMap([updated]))});
  } catch(e){ res.status(500).json({error:e.message}); }
});
app.post('/api/feed/:id/comment', auth, async(req,res)=>{
  try {
    const text=(req.body.text||'').trim();
    if(!text || text.length>500) return res.status(400).json({error:'Komentár je prázdny alebo pridlhý'});
    const post=await q.one(db.feed,{_id:req.params.id});
    if(!post) return res.status(404).json({error:'Príspevok nenájdený'});
    const u=await q.one(db.users,{_id:req.session.uid});
    const comment={id:'c'+Date.now().toString(36)+Math.floor(Math.random()*1000), user_id:u._id, name:u.name, text:text.slice(0,500), at:nowISO(), likes:[]};
    await q.update(db.feed,{_id:post._id},{$push:{comments:comment}});
    // notify post author about the comment (if someone else commented)
    if(post.author_id!==u._id){
      await q.insert(db.notifications,{user_id:post.author_id, type:'feed_comment',
        title:`💬 ${u.name} komentoval tvoj príspevok`, body:text.slice(0,80), read:false, created_at:nowISO()});
    }
    const updated=await q.one(db.feed,{_id:post._id});
    io.emit('feed_update', {id:post._id});
    res.json({ok:true, post:feedView(updated, u._id, await feedNameMap([updated]))});
  } catch(e){ res.status(500).json({error:e.message}); }
});
app.delete('/api/feed/:id', auth, async(req,res)=>{
  const post=await q.one(db.feed,{_id:req.params.id});
  if(!post) return res.status(404).json({error:'Nenájdené'});
  const me=await q.one(db.users,{_id:req.session.uid});
  if(post.author_id!==req.session.uid && !me?.is_admin) return res.status(403).json({error:'Nemáš oprávnenie'});
  await q.remove(db.feed,{_id:post._id});
  io.emit('feed_delete', {id:post._id});
  res.json({ok:true});
});

