// Admin: vyhľadať používateľa ako potenciálneho sponzora (meno/email/kód)
app.get('/api/admin/user-search', adminAuth, async(req,res)=>{
  const s=searchNorm((req.query.q||'').trim());
  if(s.length<2) return res.json({people:[]});
  const includeImported = req.query.all==='1' || req.query.imported==='1';
  let users=await q.find(db.users,{is_child:{$ne:true}});
  if(!includeImported) users=users.filter(u=>!u.imported||u.claimed);
  const byCode=users.filter(u=>searchNorm(u.referral_code).includes(s));
  users=[...new Set([...rankUserMatches(users,s), ...byCode])].slice(0,15);
  res.json({people:users.map(u=>({id:u._id,name:u.name,email:u.email,code:u.referral_code||'',type:u.user_type||'', imported:!!u.imported&&!u.claimed}))});
});

// Admin: priradiť/zmeniť sponzora klienta (napr. keď sa zaregistroval bez kódu)
app.put('/api/admin/users/:id/sponsor', adminAuth, async(req,res)=>{
  try {
    const u=await q.one(db.users,{_id:req.params.id}); if(!u) return res.status(404).json({error:'Nenájdený'});
    const sponsorId=req.body.sponsor_id||null;
    if(sponsorId){
      if(sponsorId===u._id) return res.status(400).json({error:'Nemôže byť sám sebe sponzorom'});
      const sp=await q.one(db.users,{_id:sponsorId}); if(!sp) return res.status(404).json({error:'Sponzor nenájdený'});
      // zabráň cyklu (nový sponzor nesmie byť pod týmto používateľom)
      const desc=await getAllDescendants(u._id);
      if(desc.includes(sponsorId)) return res.status(400).json({error:'Tento človek je v tvojej štruktúre – vznikol by cyklus'});
    }
    await q.update(db.users,{_id:u._id},{$set:{sponsor_id:sponsorId}});
    await auditLog(req,'set_sponsor',u._id,{old:u.sponsor_id},{new:sponsorId},'');
    res.json({ok:true});
  } catch(e){ res.status(500).json({error:e.message}); }
});
app.put('/api/admin/users/:id/awards', adminAuth, async(req,res)=>{
  const u=await q.one(db.users,{_id:req.params.id}); if(!u) return res.status(404).json({error:'Nenájdený'});
  const set={};
  if(req.body.visit_count!==undefined) set.visit_count=Math.max(0,parseInt(req.body.visit_count)||0);
  if(req.body.private_hours!==undefined) set.private_hours=Math.max(0,parseInt(req.body.private_hours)||0);
  if(req.body.taught_group_hours!==undefined) set.taught_group_hours=Math.max(0,parseInt(req.body.taught_group_hours)||0);
  if(req.body.taught_private_hours!==undefined) set.taught_private_hours=Math.max(0,parseInt(req.body.taught_private_hours)||0);
  if(req.body.referral_credit!==undefined) set.referral_credit=Math.max(0,+parseFloat(req.body.referral_credit).toFixed(2)||0);
  if(req.body.single_entries!==undefined) set.single_entries=Math.max(0,parseInt(req.body.single_entries)||0);
  if(req.body.free_credits!==undefined) set.free_credits=Math.max(0,parseInt(req.body.free_credits)||0);
  if(Array.isArray(req.body.merch_owned)) set.merch_owned=req.body.merch_owned.filter(x=>MERCH_KEYWORDS[x]);
  if(Array.isArray(req.body.manual_achievements)) set.manual_achievements=req.body.manual_achievements.filter(id=>ACHIEVEMENTS.some(a=>a.id===id));
  if(Object.keys(set).length) await q.update(db.users,{_id:u._id},{$set:set});
  await auditLog(req,'user_awards_update',u._id,{visit_count:u.visit_count,merch:u.merch_owned,manual:u.manual_achievements},set,'');
  res.json({ok:true});
});

// ── OPRAVA HISTORICKÝCH PREDAJOV (chyba: permanentka sa nepripísala, členstvo
// chýbalo v účtovníctve). Zdroj pravdy = auditný log, ktorý sa písal vždy.
// GET  = suchý náhľad (nič nemení), POST ?apply=1 = vykonanie opravy.
async function analyzeSaleRepairs(){
  const audits=(await q.find(db.audit,{})).filter(a=>a.action==='membership_sell'||a.action==='membership_gift');
  const out=[];
  for(const a of audits){
    const af=a.after||{}; const planId=af.plan_id; const plan=planId?MEMBERSHIP_PLANS[planId]:null;
    if(!plan) continue;
    const u=await q.one(db.users,{_id:a.target}); if(!u) continue;
    const when=(a.created_at||'').slice(0,10);
    const amount=+af.amount||0;
    const gift=!!af.gift;
    const item={ audit_id:a._id, date:when, user_id:u._id, name:u.name, email:u.email,
      plan_id:planId, plan_name:plan.name, amount, gift, problems:[], fix:{} };
    if(plan.type==='bundle'){
      // Vstupy sa vtedy nepripísali vôbec (server bundle preskakoval)
      const already=await q.one(db.memberships,{user_id:u._id, plan_id:planId, status:'bundle'});
      if(!already){
        item.problems.push(`nepripísaných ${plan.entries||1} vstupov`);
        item.fix.entries=plan.entries||1;
        item.fix.bundle_record=true;
      }
      if(!gift && amount>0){
        const tx=await q.one(db.transactions,{type:'single_entry', user_id:u._id, amount, created_at:{$gte:when+'T00:00:00', $lte:when+'T23:59:59'}});
        if(!tx){ item.problems.push(`chýba ${amount.toFixed(2)} € v účtovníctve`); item.fix.transaction=true; }
      }
    } else {
      // Členstvo bez payment_method → neviditeľné v tržbách
      if(!gift && amount>0){
        const mem=(await q.find(db.memberships,{user_id:u._id, plan_id:planId})).find(m=>(m.created_at||'').slice(0,10)===when);
        if(mem && !mem.payment_method){
          item.problems.push(`členstvo chýba v účtovníctve (${amount.toFixed(2)} €)`);
          item.fix.membership_payment_method=true; item.fix.membership_id=mem._id;
        }
      }
    }
    // Faktúra sa pri predaji cez profil/panel nevystavovala vôbec
    if(!gift && amount>0){
      const invs=(await q.find(db.invoices,{user_id:u._id})).filter(i=>i.type!=='credit_note');
      // Doplnená faktúra sa označí id-čkom auditného záznamu → oprava je idempotentná
      // a nikdy nevytvorí duplicitnú faktúru pri opakovanom spustení.
      const hasInv=invs.some(i=> i.repaired_audit===a._id ||
        (Math.abs((+i.total||0)-amount)<0.01 && ((i.issued_at||i.created_at||'').slice(0,10)===when)));
      if(!hasInv){ item.problems.push('chýba faktúra'); item.fix.invoice=true; }
    }
    if(item.problems.length) out.push(item);
  }
  out.sort((x,y)=>(x.date||'').localeCompare(y.date||''));
  const missingEur=out.reduce((s,i)=>s+((i.fix.transaction||i.fix.membership_payment_method)?i.amount:0),0);
  const missingEntries=out.reduce((s,i)=>s+(i.fix.entries||0),0);
  return { count:out.length, missing_revenue:+missingEur.toFixed(2), missing_entries:missingEntries, items:out };
}
app.get('/api/admin/repair-sales', adminAuth, async(req,res)=>{
  try{ res.json({ok:true, dry_run:true, ...(await analyzeSaleRepairs())}); }
  catch(e){ res.status(500).json({error:e.message}); }
});
