// Jednorazové „spárovanie": faktúry doplnené pred zavedením značky repaired_audit
// sa k svojmu predaju priradia dodatočne, aby sa uz nikdy nevytvorili druhýkrát.
app.post('/api/admin/repair-sales/stamp', adminAuth, async(req,res)=>{
  try{
    const plan=await analyzeSaleRepairs(); let stamped=0;
    for(const it of plan.items){
      if(!it.fix.invoice) continue;
      const cand=(await q.find(db.invoices,{user_id:it.user_id})).filter(i=>i.type!=='credit_note' && !i.repaired_audit && Math.abs((+i.total||0)-it.amount)<0.01);
      if(cand.length){
        await q.update(db.invoices,{_id:cand[0]._id},{$set:{repaired_audit:it.audit_id, issued_at:it.date, paid_at:it.date}});
        stamped++;
      }
    }
    res.json({ok:true, stamped});
  }catch(e){ res.status(500).json({error:e.message}); }
});

// ── CELKOVÁ KONTROLA PREDAJOV od spustenia appky ─────────────────────────────
// Krížom porovná KAŽDÝ zdroj tržby s faktúrami a účtovníctvom a nájde diery
// bez ohľadu na to, ktorou cestou sa predávalo.
app.get('/api/admin/sales-health', adminAuth, async(req,res)=>{
  try{
    const users=Object.fromEntries((await q.find(db.users,{})).map(u=>[u._id,u]));
    const invoices=(await q.find(db.invoices,{})).filter(i=>i.type!=='credit_note');
    const invByUser={}; invoices.forEach(i=>{ (invByUser[i.user_id]=invByUser[i.user_id]||[]).push(i); });
    const hasInvoice=(uid,amount,date)=>(invByUser[uid]||[]).some(i=>Math.abs((+i.total||0)-(+amount||0))<0.01 &&
      Math.abs(new Date(i.issued_at||i.created_at||0)-new Date(date||0))<3*86400000);
    const issues=[];
    const add=(kind,date,name,amount,what,detail)=>issues.push({kind,date:(date||'').slice(0,10),name,amount:+(+amount).toFixed(2),what,detail});

    // Platby kartou (Stripe) sú v tržbách cez db.payments — pri nich sa payment_method
    // na členstve NESMIE doplniť, inak by sa tržba započítala dvakrát.
    const payments=(await q.find(db.payments,{})).filter(p=>['completed','active'].includes(p.status));
    const paidByCard=(uid,amount,date)=>payments.some(p=>p.user_id===uid && Math.abs((+p.amount||0)-(+amount||0))<0.01 &&
      Math.abs(new Date(p.captured_at||p.activated_at||p.created_at||0)-new Date(date||0))<5*86400000);
    // 1) Členstvá: platené, ale bez payment_method → nie sú v tržbách
    for(const m of await q.find(db.memberships,{})){
      if(m._type || m.gift || m.migrated) continue;
      const price=+m.price||0; if(price<=0) continue;
      const u=users[m.user_id]; if(!u) continue;
      const when=m.created_at||m.started_at;
      if(!m.payment_method && m.status!=='bundle' && !paidByCard(m.user_id, price, when))
        add('členstvo mimo účtovníctva', when, u.name, price, m.plan_name||'Členstvo', 'chýba spôsob platby');
      if(!hasInvoice(m.user_id, price, when))
        add('chýba faktúra', when, u.name, price, m.plan_name||'Členstvo', m.payment_method||(paidByCard(m.user_id,price,when)?'karta':'hotovosť?'));
    }
    // 2) Transakcie (vstupy, súkromné hodiny, členstvá zapísané trénerom)
    for(const t of await q.find(db.transactions,{})){
      if(t.commission_only) continue;
      const amt=+t.amount||0; if(amt<=0) continue;
      if(!['membership','single_entry','private_lesson','subscription_renewal'].includes(t.type)) continue;
      const u=users[t.user_id]; if(!u) continue;
      if(!hasInvoice(t.user_id, amt, t.created_at))
        add('chýba faktúra', t.created_at, u.name, amt, t.note||t.type, '');
    }
    // 3) Zaplatené objednávky bez faktúry
    for(const o of (await q.find(db.orders,{}))){
      if(o.status!=='paid') continue;
      const amt=+o.total||0; if(amt<=0) continue;
      const uid=o.partner_id||null;
      const hit=invoices.some(i=>Math.abs((+i.total||0)-amt)<0.01 && Math.abs(new Date(i.issued_at||i.created_at||0)-new Date(o.paid_at||o.created_at||0))<3*86400000
        && ((i.client_email||'').toLowerCase()===(o.client_email||'').toLowerCase() || i.user_id===uid));
      if(!hit) add('chýba faktúra', o.paid_at||o.created_at, o.client_name||'—', amt, 'E-shop '+(o.order_number||''), '');
    }
    // 4) Duplicitné faktúry (rovnaký klient, suma aj deň)
    const seen={}, dup=[];
    invoices.forEach(i=>{ const k=(i.user_id||i.client_name)+'|'+(+i.total||0)+'|'+(i.issued_at||'').slice(0,10);
      if(seen[k]) dup.push({number:i.number, name:i.client_name, total:i.total, date:i.issued_at}); else seen[k]=i.number; });

    issues.sort((a,b)=>(a.date||'').localeCompare(b.date||''));
    const total=issues.reduce((s,i)=>s+(i.kind==='členstvo mimo účtovníctva'?i.amount:0),0);
    // Oprava (len s ?apply=1): doplní spôsob platby chýbajúcim členstvám a dogeneruje
    // chýbajúce faktúry k pôvodným dátumom. Faktúry idú ticho, bez e-mailu klientke.
    let applied=null;
    if(req.query.apply==='1'){
      // ?filter=eshop → doplní LEN chýbajúce faktúry k e-shopovým objednávkam
      // (nedotkne sa členstiev, kým nie je istý spôsob platby)
      const onlyEshop = req.query.filter==='eshop';
      let memFixed=0, invAdded=0;
      if(!onlyEshop) for(const m of await q.find(db.memberships,{})){
        if(m._type || m.gift || m.migrated || m.payment_method || m.status==='bundle') continue;
        const price=+m.price||0; if(price<=0) continue;
        const when=m.created_at||m.started_at;
        if(paidByCard(m.user_id, price, when)) continue; // kartu už účtovníctvo vidí
        await q.update(db.memberships,{_id:m._id},{$set:{payment_method:'cash', repaired:true}});
        memFixed++;
      }
      const mkInv=async(uid,name,email,desc,amount,date)=>{
        await createInvoice({user_id:uid, client_name:name, client_email:email,
          items:[{desc, qty:1, total:+amount}], total:+amount, method:'Hotovosť',
          issued_at:(date||'').slice(0,10), paid_at:(date||'').slice(0,10), silent:true,
          repaired_audit:'health_'+uid+'_'+(+amount)+'_'+(date||'').slice(0,10)}).catch(()=>{});
        invAdded++;
      };
      for(const it of issues.filter(i=>i.kind==='chýba faktúra' && (!onlyEshop || /^E-shop/.test(i.what)))){
        const u=Object.values(users).find(x=>x.name===it.name);
        await mkInv(u?u._id:null, it.name, u?u.email:'', it.what, it.amount, it.date);
      }
      await auditLog(req,'sales_health_repair','bulk',null,{memFixed, invAdded},'Doplnenie chýbajúcich tržieb a faktúr');
      applied={memberships_fixed:memFixed, invoices_added:invAdded};
    }
    res.json({ok:true, issues_count:issues.length, revenue_missing_from_accounting:+total.toFixed(2),
      duplicate_invoices:dup, applied, issues});
  }catch(e){ res.status(500).json({error:e.message}); }
});
app.post('/api/admin/repair-sales', adminAuth, async(req,res)=>{
  try{
    const plan=await analyzeSaleRepairs();
    if(req.query.apply!=='1') return res.json({ok:true, dry_run:true, ...plan});
    let entriesAdded=0, txAdded=0, memFixed=0, invAdded=0;
    for(const it of plan.items){
      const u=await q.one(db.users,{_id:it.user_id}); if(!u) continue;
      if(it.fix.entries){
        await q.update(db.users,{_id:u._id},{$set:{single_entries:(u.single_entries||0)+it.fix.entries}});
        entriesAdded+=it.fix.entries;
        if(it.fix.bundle_record){
          const p=MEMBERSHIP_PLANS[it.plan_id];
          await q.insert(db.memberships,{user_id:u._id,user_name:u.name,plan_id:it.plan_id,plan_name:it.plan_name,
            price:it.gift?0:it.amount, status:'bundle', started_at:it.date+'T12:00:00.000Z',
            expires_at:new Date(new Date(it.date).getTime()+(p?.duration_days||90)*86400000).toISOString(),
            gift:!!it.gift, repaired:true, created_at:it.date+'T12:00:00.000Z'});
        }
        // Bez notifikácie — klientky o zdržaní nevedeli, netreba ich zneisťovať.
        // Stopa o oprave ostáva v auditnom logu.
      }
      if(it.fix.transaction){
        await q.insert(db.transactions,{type:'single_entry', user_id:u._id, user_name:u.name, amount:it.amount,
          payment_method:'cash', method:'cash', note:`${it.plan_name} (spätná oprava z auditu)`,
          plan_id:it.plan_id, repaired:true, created_at:it.date+'T12:00:00.000Z', month:it.date.slice(0,7)});
        txAdded++;
      }
      if(it.fix.membership_payment_method && it.fix.membership_id){
        await q.update(db.memberships,{_id:it.fix.membership_id},{$set:{payment_method:'cash', price:it.amount, repaired:true}});
        memFixed++;
      }
      if(it.fix.invoice){
        await createInvoice({user_id:u._id, client_name:u.name, client_email:u.email,
          items:[{desc:(MEMBERSHIP_PLANS[it.plan_id]?.type==='bundle'?it.plan_name:`Členstvo ${it.plan_name}`), qty:1, total:it.amount}],
          total:it.amount, method:'Hotovosť', paid_at:it.date, issued_at:it.date,
          silent:true, repaired_audit:it.audit_id}).catch(()=>{});
        invAdded++;
      }
    }
    await auditLog(req,'repair_sales','bulk',null,{items:plan.count, entriesAdded, txAdded, memFixed, invAdded},'Spätná oprava predajov z auditného logu');
    res.json({ok:true, applied:true, items:plan.count, entries_added:entriesAdded, transactions_added:txAdded, memberships_fixed:memFixed, invoices_added:invAdded});
  }catch(e){ res.status(500).json({error:e.message}); }
});

// Admin: úprava kreditu klienta — pridať/odobrať/nastaviť
app.post('/api/admin/users/:id/credit', adminAuth, async(req,res)=>{
  try {
    const u=await q.one(db.users,{_id:req.params.id}); if(!u) return res.status(404).json({error:'Nenájdený'});
    const op=req.body.op; const val=+parseFloat(req.body.amount);
    if(isNaN(val)) return res.status(400).json({error:'Neplatná suma'});
    let cur=+(u.referral_credit||0);
    let nc = op==='set' ? val : op==='add' ? cur+val : op==='sub' ? cur-val : cur;
    nc=+Math.max(0,nc).toFixed(2);
    await q.update(db.users,{_id:u._id},{$set:{referral_credit:nc}});
    await q.insert(db.notifications,{user_id:u._id,type:'credit',title:'💳 Úprava kreditu adminom',body:`Nový zostatok kreditu: ${nc.toFixed(2)} €`,read:false,created_at:nowISO()}).catch(()=>{});
    await auditLog(req,'credit_adjust',u._id,{old:cur},{op,val,new:nc},'');
    res.json({ ok:true, referral_credit:nc });
  } catch(e){ res.status(500).json({error:e.message}); }
});

// Admin: úprava jednorázových vstupov (permanentky) — nastaviť/pridať/odobrať (aj oprava chýb z importu)
app.post('/api/admin/users/:id/entries', adminAuth, async(req,res)=>{
  try {
    const u=await q.one(db.users,{_id:req.params.id}); if(!u) return res.status(404).json({error:'Nenájdený'});
    const op=req.body.op; const val=parseInt(req.body.amount);
    if(isNaN(val)) return res.status(400).json({error:'Neplatný počet'});
    let cur=parseInt(u.single_entries||0);
    let ne = op==='set' ? val : op==='add' ? cur+val : op==='sub' ? cur-val : cur;
    ne=Math.max(0,ne);
    await q.update(db.users,{_id:u._id},{$set:{single_entries:ne}});
    await q.insert(db.notifications,{user_id:u._id,type:'entries',title:'🎟️ Úprava vstupov',body:`Aktuálny počet jednorázových vstupov: ${ne}`,read:false,created_at:nowISO()}).catch(()=>{});
    await auditLog(req,'entries_adjust',u._id,{old:cur},{op,val,new:ne},'');
    res.json({ ok:true, single_entries:ne });
  } catch(e){ res.status(500).json({error:e.message}); }
});

// Admin: zapnúť/vypnúť ambasádorku. Rola odomyká celú ambasádorskú sekciu.
// ═══ Admin sekcia AMBASÁDORI — jedno miesto (Marek 28.8.) ═══
app.get('/api/admin/ambassadors', adminAuth, async(req,res)=>{
  try{
    const users=await q.find(db.users,{});
    const od30=Date.now()-30*86400000;
    const ts=x=>new Date(x||0).getTime();
    const clenovia=users.filter(u=>!u.is_child && (u.is_admin||['trainer','manager','ambassador'].includes(u.user_type||'')||u.is_assistant));
    const kontakty=db.coach_contacts?await q.find(db.coach_contacts,{}):[];
    const casy=db.coach_cases?await q.find(db.coach_cases,{}):[];
    const ulohy=db.coach_tasks?await q.find(db.coach_tasks,{}):[];
    const txs=await q.find(db.transactions,{});
    const podlaSponzora={};
    for(const u of users){ if(u.sponsor_id&&!u.is_admin&&!u.is_child) (podlaSponzora[u.sponsor_id]=podlaSponzora[u.sponsor_id]||[]).push(u); }
    const rola=u=>u.is_admin?'admin':u.user_type==='trainer'?'trénerka':u.user_type==='manager'?'manažérka':u.user_type==='ambassador'?'ambasádorka':'asistentka';
    const members=clenovia.map(u=>{
      const moje=kontakty.filter(c=>c.trainer_id===u._id);
      const linia=podlaSponzora[u._id]||[];
      const liniaIds=new Set(linia.map(x=>x._id));
      const objem30=txs.filter(t=>liniaIds.has(t.user_id)&&(+t.amount||0)>0&&!t.commission_only&&ts(t.created_at||t.date)>=od30)
        .reduce((s2,t)=>s2+(+t.amount||0),0);
      return { id:u._id, name:u.name, email:u.email, rola:rola(u),
        since:(u.ambassador_since||'').slice(0,10)||null,
        kontakty_30d:moje.filter(c=>ts(c.created_at)>=od30).length,
        zaujem_30d:moje.filter(c=>ts(c.created_at)>=od30&&['interested','will_come','booked','replied'].includes(c.outcome)).length,
        konverzie:casy.filter(c=>c.trainer_id===u._id&&c.converted&&!c.conversion_revoked_at).length,
        linia:linia.length, objem_30d:+objem30.toFixed(2),
        body_30d:ulohy.filter(t=>t.trainer_id===u._id&&t.done&&ts(t.done_at||t.created_at)>=od30)
          .reduce((s2,t)=>s2+(+t.points||0),0) };
    }).sort((a,b)=>b.objem_30d-a.objem_30d||b.kontakty_30d-a.kontakty_30d);
    // prihlášky na školenie + spárovanie s účtom podľa mailu/telefónu
    const p9=v=>{let x=String(v||'').replace(/[^\d]/g,'');if(x.startsWith('421'))x=x.slice(3);if(x.startsWith('0'))x=x.slice(1);return x.length===9?x:null;};
    const podlaMailu={}, podlaTel={};
    for(const u of users){ if(u.email)podlaMailu[u.email.toLowerCase()]=u; const t=p9(u.phone); if(t&&!podlaTel[t])podlaTel[t]=u; }
    const signups=(await q.find(db.rentals,{_type:'amb_training'}))
      .sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)))
      .map(r2=>{ const u=(r2.email&&podlaMailu[r2.email.toLowerCase()])||podlaTel[p9(r2.phone)]||null;
        return { id:r2._id, name:r2.name, phone:r2.phone||'', email:r2.email||'', city:r2.city||'',
          training_date:r2.training_date||'', prihlasena:(r2.created_at||'').slice(0,10),
          status:r2.status||'new', completed_at:(r2.completed_at||'').slice(0,10)||null,
          user_id:u?u._id:null, user_name:u?u.name:null,
          uz_ambasadorka:!!(u&&(u.is_admin||u.is_assistant||['trainer','manager','ambassador'].includes(u.user_type||''))) };});
    res.json({ok:true, members, signups});
  }catch(e){ res.status(500).json({error:e.message}); }
});
