app.delete('/api/admin/users/:id', adminAuth, async(req,res)=>{
  const u=await q.one(db.users,{_id:req.params.id});
  if(!u) return res.status(404).json({error:'Nenájdený'});
  if(u.is_admin) return res.status(400).json({error:'Admin účet nemožno zmazať'});
  // Remove all related data
  await q.remove(db.users,      {_id:req.params.id});
  await q.remove(db.transactions,{partner_id:req.params.id},{multi:true});
  await q.remove(db.commissions, {partner_id:req.params.id},{multi:true});
  await q.remove(db.bookings,    {user_id:req.params.id},   {multi:true});
  // Re-assign their downline to their own sponsor
  const sponsorId = u.sponsor_id || null;
  await q.update(db.users,{sponsor_id:req.params.id},{$set:{sponsor_id:sponsorId}},{multi:true});
  res.json({ok:true});
});

// Zlúčenie účtov: prenesie históriu zo zdrojového (:id) do cieľového (target_id) a zdroj zmaže.
app.post('/api/admin/users/:id/merge-into', adminAuth, async(req,res)=>{
  try{
    const src=await q.one(db.users,{_id:req.params.id});
    const tgtId=String(req.body.target_id||'');
    const tgt=await q.one(db.users,{_id:tgtId});
    if(!src||!tgt) return res.status(404).json({error:'Účet nenájdený'});
    if(src._id===tgt._id) return res.status(400).json({error:'Nemôžeš zlúčiť účet sám so sebou'});
    if(src.is_admin) return res.status(400).json({error:'Admin účet nemožno zlúčiť/zmazať'});
    // 1) Presuň záznamy zo zdroja na cieľ (podľa polí s user id)
    const reassign=async(coll,field)=>{ await q.update(coll,{[field]:src._id},{$set:{[field]:tgt._id}},{multi:true}); };
    await reassign(db.bookings,'user_id');       await reassign(db.bookings,'booked_by');
    await reassign(db.transactions,'user_id');   await reassign(db.transactions,'partner_id');
    await reassign(db.commissions,'partner_id'); await reassign(db.commissions,'user_id');
    await reassign(db.memberships,'user_id');
    await reassign(db.payments,'user_id');       await reassign(db.payments,'member_id');
    await reassign(db.invoices,'user_id');
    await reassign(db.notifications,'user_id');   await reassign(db.notifications,'from_id');
    await reassign(db.profile_likes,'profile_id');await reassign(db.profile_likes,'liker_id');
    await reassign(db.profile_comments,'profile_id'); await reassign(db.profile_comments,'author_id');
    await reassign(db.tips,'to_user');           await reassign(db.tips,'from_user');
    await reassign(db.task_logs,'user_id');
    await reassign(db.orders,'user_id');
    await reassign(db.feed,'author_id');
    // downline: kto mal za sponzora zdroj → dostane cieľ
    await q.update(db.users,{sponsor_id:src._id},{$set:{sponsor_id:tgt._id}},{multi:true});
    // priateľstvá zdroja radšej odstráň (páry sú kľúčované, aby nevznikli duplicity/rozbité väzby)
    await q.remove(db.friends,{users:src._id},{multi:true});
    // meal plan: ak cieľ nemá, prenes zdrojový
    if(!(await q.one(db.meal_plans,{user_id:tgt._id}))) await reassign(db.meal_plans,'user_id');
    else await q.remove(db.meal_plans,{user_id:src._id},{multi:true});
    // 2) Spočítaj/zjednoť polia na cieľovom účte
    const num=k=>(+src[k]||0)+(+tgt[k]||0);
    const uni=k=>Array.from(new Set([...(tgt[k]||[]),...(src[k]||[])]));
    const set={
      visit_count:num('visit_count'), private_hours:num('private_hours'),
      taught_group_hours:num('taught_group_hours'), taught_private_hours:num('taught_private_hours'),
      single_entries:num('single_entries'), free_credits:num('free_credits'),
      referral_credit:+num('referral_credit').toFixed(2), referral_credit_pending:+num('referral_credit_pending').toFixed(2),
      manual_achievements:uni('manual_achievements'), merch_owned:uni('merch_owned'),
      free_class_used: !!(tgt.free_class_used||src.free_class_used),
      birthday: tgt.birthday||src.birthday||'',
      gender: tgt.gender||src.gender||null,
      avatar: tgt.avatar||src.avatar||null,
      // „členom od" = skorší z oboch
      created_at: [tgt.created_at,src.created_at].filter(Boolean).sort()[0] || tgt.created_at
    };
    await q.update(db.users,{_id:tgt._id},{$set:set});
    // 3) Zmaž zdrojový účet
    await q.remove(db.users,{_id:src._id});
    await auditLog(req,'merge_users',src._id,{source:src.name},{into:tgt._id,into_name:tgt.name},'Zlúčenie účtov');
    res.json({ok:true, target_id:tgt._id, target_name:tgt.name, visit_count:set.visit_count});
  }catch(e){ res.status(500).json({error:e.message}); }
});

app.post('/api/admin/transactions', adminAuth, async(req,res)=>{
  try {
    const{client_id,product_id,amount,notes,date}=req.body;
    let {partner_id,client_name}=req.body;
    // If a real client account is chosen, use its name and auto-derive the sponsor
    // (the person who registered them) as the commission recipient — unless an
    // explicit partner_id override was provided.
    let client=null;
    if(client_id){
      client=await q.one(db.users,{_id:client_id});
      if(client){
        client_name = client_name || client.name;
        if(!partner_id) partner_id = client.sponsor_id || null;
      }
    }
    if(!client_name||!amount) return res.status(400).json({error:'Klient a suma sú povinné'});
    const prod=product_id?await q.one(db.products,{_id:product_id}):null;
    const product_name=prod?prod.name:(req.body.product_name||'Iný predaj');
    const finalAmt=+parseFloat(amount).toFixed(2);
    const tx=await q.insert(db.transactions,{partner_id:partner_id||null,client_id:client_id||null,client_name,product_id:product_id||null,product_name,amount:finalAmt,date:date||today(),notes:notes||''});
    // Commission only when we have a recipient (sponsor or explicit partner)
    if(partner_id){ await saveCommissions(tx._id,partner_id,finalAmt); await calcRank(partner_id); }
    res.json({ok:true,id:tx._id,commission:!!partner_id,partner_id:partner_id||null});
  } catch(e){res.status(500).json({error:e.message});}
});

app.delete('/api/admin/transactions/:id', adminAuth, async(req,res)=>{
  await q.remove(db.commissions,{transaction_id:req.params.id},{multi:true});
  await q.remove(db.transactions,{_id:req.params.id});
  res.json({ok:true});
});

// Admin: predaj merchu klientovi (veľkosť/farba). Vytvorí zaplatenú objednávku →
// odomkne merch odznak, pošle notifikácie kupujúcemu aj priateľom, zaráta províziu línie.
app.post('/api/admin/merch-sale', adminAuth, async(req,res)=>{
  try{
    const client=await q.one(db.users,{_id:String(req.body.client_id||'')});
    const prod=await q.one(db.products,{_id:String(req.body.product_id||'')});
    if(!client) return res.status(404).json({error:'Klient nenájdený'});
    if(!prod) return res.status(404).json({error:'Produkt nenájdený'});
    const vr=variantsFor(prod.name);
    const size=(vr&&vr.sizes&&vr.sizes.includes(req.body.size))?req.body.size:null;
    const color=(vr&&vr.colors&&vr.colors.includes(req.body.color))?req.body.color:null;
    if(vr&&vr.sizes&&!size) return res.status(400).json({error:'Vyber veľkosť'});
    if(vr&&vr.colors&&!color) return res.status(400).json({error:'Vyber farbu'});
    const qty=Math.max(1,Math.min(20,parseInt(req.body.qty)||1));
    const method=['cash','card','transfer'].includes(req.body.payment_method)?req.body.payment_method:'cash';
    const subtotal=+(prod.price*qty).toFixed(2);
    const order_number='FA'+Date.now().toString(36).toUpperCase();
    const order=await q.insert(db.orders,{ order_number, user_id:client._id, client_name:client.name, client_email:(client.email||'').toLowerCase(),
      client_phone:client.phone||'', city:client.city||'',
      items:[{product_id:prod._id, product_name:prod.name, price:prod.price, qty, subtotal, size, color, commission_rate:prod.commission_rate}],
      total:subtotal, status:'paid', payment_method:method, sold_by:req.session.uid, manual:true,
      created_at:nowISO(), paid_at:nowISO() });
    // Tržba + provízia (sponzorovi klienta)
    const tx=await q.insert(db.transactions,{ partner_id:client.sponsor_id||null, client_id:client._id, client_name:client.name,
      product_id:prod._id, product_name:prod.name+variantLabel({size,color}), amount:subtotal, date:today(),
      payment_method:method, notes:'Predaj merchu (admin)', month:today().slice(0,7), created_at:nowISO() });
    if(client.sponsor_id){ await saveCommissions(tx._id, client.sponsor_id, subtotal).catch(()=>{}); await calcRank(client.sponsor_id).catch(()=>{}); }
    // Odznak + notifikácie (kupujúci + priatelia) — cez spoločný hook
    await grantMerchFromOrder(order);
    await q.insert(db.notifications,{ user_id:client._id, type:'purchase', title:'🛍️ Nový nákup',
      body:`${prod.name}${variantLabel({size,color})} — ${subtotal.toFixed(2)} €. Ďakujeme! 💛`, read:false, created_at:nowISO() }).catch(()=>{});
    await auditLog(req,'merch_sale',client._id,{},{product:prod.name,size,color,amount:subtotal},'');
    res.json({ ok:true, order_number, product:prod.name, size, color, amount:subtotal });
  }catch(e){ res.status(500).json({error:e.message}); }
});

app.get('/api/admin/orders', adminAuth, async(req,res)=>{
  const{status}=req.query;
  const filter=status?{status}:{};
  const orders=await q.find(db.orders,filter);
  orders.sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||'')));
  // Doplň user_id (na preklik na profil) — z objednávky alebo podľa e-mailu
  const byEmail={};
  for(const o of orders){
    if(o.user_id) continue;
    const em=(o.client_email||'').toLowerCase(); if(!em) continue;
    if(!(em in byEmail)){ const u=await q.one(db.users,{email:em}); byEmail[em]=u?u._id:null; }
    o.user_id=byEmail[em];
  }
  res.json(orders);
});

app.put('/api/admin/orders/:id', adminAuth, async(req,res)=>{
  try {
    const{status, take, dispatch}=req.body;
    const order=await q.one(db.orders,{_id:req.params.id});
    if(!order) return res.status(404).json({error:'Nenájdená'});
    // „Vybavené / Odoslané" — potvrdenie, že objednávka je vyriešená (odovzdaná/odoslaná poštou)
    if(dispatch!==undefined){
      const me=await q.one(db.users,{_id:req.session.uid});
      await q.update(db.orders,{_id:req.params.id},{$set:{dispatched:!!dispatch, dispatched_at:dispatch?nowISO():null, dispatched_by_name:dispatch?(me?.name||''):''}});
      await auditLog(req,'order_dispatch',order.order_number,{},{dispatched:!!dispatch},'');
      return res.json({ok:true, dispatched:!!dispatch});
    }
    // „Prevziať" — priradí objednávku aktuálnemu adminovi (kto to vybavuje)
    if(take){
      const me=await q.one(db.users,{_id:req.session.uid});
      await q.update(db.orders,{_id:req.params.id},{$set:{handled_by:req.session.uid, handled_by_name:me?.name||'', handled_at:nowISO()}});
      await auditLog(req,'order_take',order.order_number,{},{by:me?.name},'');
      if(!status) return res.json({ok:true, handled_by_name:me?.name||''});
    }
    if(!status) return res.json({ok:true});
    await q.update(db.orders,{_id:req.params.id},{$set:{status,updated_at:nowISO(),...(status==='paid'?{paid_at:nowISO()}:{})}});
    if(status==='paid' && order.status!=='paid'){
      // Kto objednávku kúpil (ak je to náš člen) — pre províziu po jeho sponzorskej línii
      const esc=s=>String(s||'').replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
      const buyer = order.client_email
        ? await q.one(db.users,{email:new RegExp('^'+esc(order.client_email.trim())+'$','i')})
        : null;
      if(buyer && buyer.sponsor_id){
        // Provízia hore po genealógii kupujúceho (rovnako ako pri členstve).
        // Sponzor tak dostane affiliate kredit aj za merch kúpený niekým v jeho línii.
        for(const item of order.items){
          await awardPurchaseCommission({ buyer_id: buyer._id, amount:item.subtotal, product_name: item.product_name });
        }
      } else if(order.partner_id){
        // Predaj cez referral kód (kupujúci nie je náš člen) — provízia referrerovi.
        for(const item of order.items){
          const tx=await q.insert(db.transactions,{partner_id:order.partner_id,client_name:order.client_name,product_id:item.product_id||null,product_name:item.product_name,amount:item.subtotal,date:today(),notes:'E-shop objednávka '+order.order_number,order_id:order._id});
          await saveCommissions(tx._id,order.partner_id,item.subtotal);
        }
        await calcRank(order.partner_id);
      }
      grantMerchFromOrder(order);
    }
    res.json({ok:true});
  } catch(e){res.status(500).json({error:e.message});}
});

app.get('/api/admin/commissions/summary', adminAuth, async(req,res)=>{
  const month=req.query.month||currentMonth();
  const allU=await q.find(db.users,{is_admin:{$ne:true}});
  const allC=await q.find(db.commissions,{month});
  const result=allU.map(u=>{
    const uc=allC.filter(c=>c.partner_id===u._id);
    const pending=uc.filter(c=>c.status==='pending').reduce((s,c)=>s+c.amount,0);
    const paid=uc.filter(c=>c.status==='paid').reduce((s,c)=>s+c.amount,0);
    return{id:u._id,name:u.name,email:u.email,bank_account:u.bank_account||'',rank:u.rank||1,rankName:RANKS[(u.rank||1)-1].name,pending:+pending.toFixed(2),paid:+paid.toFixed(2)};
  }).filter(r=>r.pending>0||r.paid>0);
  result.sort((a,b)=>b.pending-a.pending);
  res.json(result);
});

