// Resolve an instructor_id → {id, name}. Falls back to given name if no id.
async function resolveInstructor(instructor_id, fallbackName){
  if(instructor_id){
    const u=await q.one(db.users,{_id:instructor_id});
    if(u) return {instructor_id:u._id, instructor:u.name};
  }
  return {instructor_id:'', instructor:fallbackName||'Marek Gruber'};
}

// Inštruktor konkrétneho termínu hodiny (class_id + dátum). Ak je nastavený override
// (admin ho zmenil alebo sa tréner prihlásil, že učí), platí až kým ho niekto nezmení.
// Inak sa použije štandardný inštruktor hodiny.
async function sessionInstructor(cls, date){
  if(cls && date){
    const ov = await q.one(db.session_instructors,{class_id:cls._id, date});
    if(ov && ov.instructor_id) return { instructor_id:ov.instructor_id, instructor:ov.instructor_name||'—', overridden:true };
  }
  return { instructor_id:cls?.instructor_id||'', instructor:cls?.instructor||'—', overridden:false };
}
// Mapa všetkých override-ov (class_id|date → {id,name}) — pre hromadný výpočet zárobkov
async function sessionInstructorMap(){
  const rows=await q.find(db.session_instructors,{});
  const m={};
  rows.forEach(r=>{ if(r.instructor_id) m[r.class_id+'|'+r.date]={id:r.instructor_id,name:r.instructor_name||'—'}; });
  return m;
}

app.post('/api/admin/classes', adminAuth, async(req,res)=>{
  const{name,emoji,category,instructor,instructor_id,location,day_of_week,time_start,time_end,capacity,level,description,price,color,only_date,stream_city}=req.body;
  if(!name||day_of_week===undefined||!time_start) return res.status(400).json({error:'Vyplňte povinné polia'});
  const ins=await resolveInstructor(instructor_id,instructor);
  // only_date = jednorazový termín (mimoriadna hodina); prázdne = štandardné týždenné opakovanie
  const c=await q.insert(db.classes,{name,emoji:emoji||'💃',category:category||'Tanec',instructor:ins.instructor,instructor_id:ins.instructor_id,location:location||'Banská Bystrica',day_of_week:+day_of_week,time_start,time_end:time_end||'',capacity:+capacity||30,level:level||'Všetky úrovne',description:description||'',price:+price||10,color:color||'#e94560',only_date:only_date||null,stream_city:stream_city||null,active:true});
  res.json({ok:true,id:c._id});
});

app.put('/api/admin/classes/:id', adminAuth, async(req,res)=>{
  // Meň len POSLANÉ polia — čiastočný update (napr. len kapacita) predtým
  // prepísal ostatné polia na undefined/NaN a hodinu deaktivoval.
  const b=req.body, $set={};
  for(const f of ['name','category','location','time_start','time_end','level','description','color','stream_city']) if(b[f]!==undefined) $set[f]=b[f];
  // Prázdny reťazec = zruš jednorazovosť (hodina sa vráti k týždennému opakovaniu)
  if(b.only_date!==undefined) $set.only_date = b.only_date || null;
  if(b.emoji!==undefined) $set.emoji=b.emoji||'💃';
  if(b.day_of_week!==undefined) $set.day_of_week=+b.day_of_week;
  if(b.capacity!==undefined) $set.capacity=+b.capacity;
  if(b.price!==undefined) $set.price=+b.price;
  if(b.active!==undefined) $set.active=!!b.active;
  if(b.instructor!==undefined || b.instructor_id!==undefined){
    const ins=await resolveInstructor(b.instructor_id,b.instructor);
    $set.instructor=ins.instructor; $set.instructor_id=ins.instructor_id;
  }
  await q.update(db.classes,{_id:req.params.id},{$set});
  res.json({ok:true});
});


app.delete('/api/admin/classes/:id', adminAuth, async(req,res)=>{
  await q.update(db.classes,{_id:req.params.id},{$set:{active:false}});
  res.json({ok:true});
});

// Keep only Zumba / Zumba ONLINE classes — deactivates everything else. Audited & reversible.
app.post('/api/admin/classes/keep-zumba-only', adminAuth, async(req,res)=>{
  try {
    const isZumba = c => /zumba/i.test(c.name||'') || /zumba|online/i.test(c.category||'');
    const active = (await q.find(db.classes,{active:true}));
    const toRemove = active.filter(c=>!isZumba(c));
    for(const c of toRemove) await q.update(db.classes,{_id:c._id},{$set:{active:false}});
    await auditLog(req,'classes_keep_zumba_only','classes',{removed_count:toRemove.length},
      {removed:toRemove.map(c=>c.name)}, req.body.reason||'');
    res.json({ ok:true, removed:toRemove.length, kept:active.length-toRemove.length,
      removedNames:[...new Set(toRemove.map(c=>c.name))] });
  } catch(e){ res.status(500).json({error:e.message}); }
});

