async function pointsSummaryData(from, to){
  {
    const fromD=(from||'0000').slice(0,10), toD=(to||'9999').slice(0,10);
    const inRange=d=>{ d=(d||'').slice(0,10); return d>=fromD && d<=toD; };
    const users=(await q.find(db.users,{is_admin:{$ne:true}, is_child:{$ne:true}})).filter(u=>!(u.imported&&!u.claimed)&&!u.anonymous);
    const bookings=await q.find(db.bookings,{});
    const isOnline=b=>/online/i.test(b.class_name||'')||/online/i.test(b.class_location||'')||b.online===true;
    const byUser={};
    for(const b of bookings){ if(b.user_id && ['attended','confirmed'].includes(b.status) && inRange(b.booking_date||b.created_at)) (byUser[b.user_id]=byUser[b.user_id]||[]).push(b); }
    const allU=await q.find(db.users,{});
    const refByUser={};
    for(const u of users){ if(u.sponsor_id && inRange(u.created_at)) refByUser[u.sponsor_id]=(refByUser[u.sponsor_id]||0)+1; }
    // noví platiaci členovia (po líniách) + merch v rozsahu
    const adjacency={}; allU.forEach(u=>{ if(u.sponsor_id) (adjacency[u.sponsor_id]=adjacency[u.sponsor_id]||[]).push(u._id); });
    const buyerSet=new Set();
    (await q.find(db.memberships,{})).forEach(m=>{ const plan=MEMBERSHIP_PLANS[m.plan_id]; if(plan&&plan.type==='bundle') return;
      const d=(m.started_at||m.start_date||m.created_at||'').slice(0,10); if(inRange(d) && (+m.price>0||m.payment_method||m.status)) buyerSet.add(m.user_id); });
    const emailToId={}; allU.forEach(u=>{ if(u.email) emailToId[u.email.toLowerCase()]=u._id; });
    const merchMap={};
    (await q.find(db.orders,{})).filter(o=>o.status==='paid').forEach(o=>{ if(!inRange(o.paid_at||o.created_at)) return;
      const uid=emailToId[(o.client_email||'').toLowerCase()]; if(!uid) return;
      (o.items||[]).forEach(it=>{ if(isMerchItem(it)) merchMap[uid]=(merchMap[uid]||0)+(+it.qty||1); }); });
    const rows=[]; const catTotals={hours:0, online:0, refs:0, membership:0, newmem:0, merch:0, merchline:0, review:0, private:0};
    // Absolvované súkromné hodiny v období (rátajú sa do súťaže rovnako ako skupinové)
    const privBy={}; (await q.find(db.private_bookings,{status:'completed'})).forEach(b=>{ if(b.client_id && inRange(b.date)) privBy[b.client_id]=(privBy[b.client_id]||0)+1; });
    const spinBy={}; (await q.find(db.spins,{})).forEach(s=>{ if(inRange(s.date)){ const b=spinBy[s.user_id]=spinBy[s.user_id]||{p:0,c:0}; b.p+=(+s.points||0); if(!s.milestone) b.c++; } });
    const puzzleBy={}; (await q.find(db.puzzle_solves,{})).forEach(p=>{ if(inRange(p.date)){ const b=puzzleBy[p.user_id]=puzzleBy[p.user_id]||{p:0,c:0}; b.p+=(+p.points||0); b.c++; } });
    const reviewBy={}; (await q.find(db.review_claims,{status:'approved'})).forEach(c=>{ if(inRange(c.decided_at||c.created_at)) reviewBy[c.user_id]=(reviewBy[c.user_id]||0)+1; });
    const paidTiers=await paidMembershipTierMap();
    for(const u of users){
      const bks=byUser[u._id]||[];
      const online=bks.filter(isOnline).length;
      const hours=bks.length-online;
      const refs=refByUser[u._id]||0;
      const m=await checkMembership(u._id);
      const hasMem=!!m;
      const nm=newMemberPointsFor(u._id, adjacency, buyerSet);
      const md=merchDownlinePointsFor(u._id, adjacency, merchMap);
      const merchCount=merchMap[u._id]||0;
      const effTier=hasMem?effectiveMemTier(paidTiers[u._id]||null, m.plan_id, !!m.gift):null;
      const privCount=privBy[u._id]||0;
      const pi=buildPointItems({hours, online, refs, hasMem, memName:hasMem?(MEMBERSHIP_PLANS[m.plan_id]?.name||m.plan_name||'Členstvo'):null, memTier:effTier, newMemberCount:nm.count, newMemberPoints:nm.points, merchCount, merchLineCount:md.count, merchLinePoints:md.points, privCount, spinPoints:(spinBy[u._id]||{}).p||0, spinCount:(spinBy[u._id]||{}).c||0, reviewCount:reviewBy[u._id]||0, puzzlePoints:(puzzleBy[u._id]||{}).p||0, puzzleCount:(puzzleBy[u._id]||{}).c||0});
      if(pi.total<=0) continue;
      catTotals.hours+=hours*MP_WEIGHTS.hour; catTotals.online+=online*MP_WEIGHTS.hour;
      catTotals.refs+=refs*MP_WEIGHTS.referral; catTotals.membership+=hasMem?membershipPointsFor(effTier):0;
      catTotals.newmem+=nm.points; catTotals.merch+=merchCount*MP_WEIGHTS.merch; catTotals.merchline+=md.points;
      catTotals.review+=(reviewBy[u._id]||0)*10; catTotals.private+=privCount*MP_WEIGHTS.private;
      rows.push({ id:u._id, name:u.name, total:pi.total, hours, online, refs, hasMem, private_hours:privCount,
        items:pi.items.filter(i=>i.points>0).map(i=>({label:i.label, count:i.count, points:i.points})) });
    }
    rows.sort((a,b)=>b.total-a.total);
    return { from:fromD, to:toD, count:rows.length, rows, catTotals,
      grandPoints: rows.reduce((s,r)=>s+r.total,0) };
  }
}
// ═══════════════════════════════════════════════════════════════════════════════
// FUNNEL: registrácia → rezervácia → účasť → platba
// ═══════════════════════════════════════════════════════════════════════════════
// Kohorta = klientky, ktoré sa REGISTROVALI v danom období. Ich kroky sa rátajú
// aj keď nastali neskôr — inak by posledný týždeň vyzeral vždy katastrofálne.
// Importované z Glofoxu sem nepatria (prišli mimo appky, skresľovali by akvizíciu),
// detské profily tiež nie (konverziu rieši rodičovský účet).
app.get('/api/admin/funnel', adminAuth, async(req,res)=>{
  try{
    // Timestampy sú len cache — pred zobrazením ich prepočítame z rezervácií a platieb,
    // aby dashboard sedel aj po ručnej oprave dát alebo importe.
    await rebuildFunnelStamps().catch(()=>{});
    const from=(req.query.from||'').slice(0,10) || '0000-01-01';
    const to=(req.query.to||'').slice(0,10) || '9999-12-31';
    const city=String(req.query.city||'');
    const campaign=String(req.query.campaign||'');
    const inRange=d=>{ d=String(d||'').slice(0,10); return d>=from && d<=to; };

    let users=(await q.find(db.users,{is_admin:{$ne:true}, is_child:{$ne:true}}))
      .filter(u=>!u.anonymous && !u.imported && !(u.glofox_attendances>0) && u.user_type!=='trainer')
      .filter(u=>inRange(u.created_at));
    if(campaign) users=users.filter(u=>(u.utm_campaign||'(bez kampane)')===campaign);

    // mesto klientky = mesto jej prvej rezervácie (u.city je len to, čo si vyplnila)
    const bks=await q.find(db.bookings,{});
    const firstCity={}, firstBk={};
    for(const b of bks){
      if(!b.user_id || b.status==='cancelled') continue;
      const d=b.created_at||b.booking_date;
      if(!firstBk[b.user_id] || String(d)<String(firstBk[b.user_id])){ firstBk[b.user_id]=d; firstCity[b.user_id]=b.class_location||''; }
    }
    if(city) users=users.filter(u=>(firstCity[u._id]||u.city||'—')===city);

    const days=(a,b)=>{ const x=Date.parse(String(a).slice(0,10)), y=Date.parse(String(b).slice(0,10));
      return (Number.isFinite(x)&&Number.isFinite(y)) ? Math.round((y-x)/864e5) : null; };
    // Funnel musí byť monotónny: kto prišiel, ten sa aj prihlásil (aj keď rezerváciu
    // vytvoril kiosk pri príchode alebo išlo o súkromnú hodinu bez skupinovej rezervácie).
    // Bez toho vychádzali kroky >100 %.
    const step={registered:users.length, booked:0, attended:0, returned:0, paid:0, paid_after_attend:0, membership:0};
    const lag={booking:[], attend:[], back:[], pay:[]};
    const rows=[];
    for(const u of users){
      const a=u.first_attended_at, a2=u.second_attended_at, p=u.first_paid_at;
      const b=u.first_booking_at || a;
      if(b){ step.booked++; const d=days(u.created_at,b); if(d!=null) lag.booking.push(d); }
      if(a){ step.attended++; const d=days(b||u.created_at,a); if(d!=null) lag.attend.push(d); }
      if(a2){ step.returned++; const d=days(a,a2); if(d!=null) lag.back.push(d); }
      if(p){ step.paid++; const d=days(a||u.created_at,p); if(d!=null) lag.pay.push(d); }
      // „účasť → platba" sa ráta len z tých, čo naozaj prišli; kto kúpil členstvo
      // online bez toho, aby prišiel, patrí do tržieb, nie do tejto konverzie
      if(a && p) step.paid_after_attend++;
      if(u.first_membership_at) step.membership++;
      rows.push({ id:u._id, name:u.name, registered:String(u.created_at||'').slice(0,10),
        city:firstCity[u._id]||u.city||'—', campaign:u.utm_campaign||'(bez kampane)', source:u.utm_source||u.lead_source||'—',
        booked:!!b, attended:!!a, returned:!!a2, paid:!!p, paid_after_attend:!!(a&&p) });
    }
    const med=a=>{ if(!a.length) return null; const s=[...a].sort((x,y)=>x-y); return s[Math.floor(s.length/2)]; };
    const pct=(n,d)=>d?+(n/d*100).toFixed(1):0;

    // rozpad podľa kampane a mesta — kde presne padá
    const by=(keyFn)=>{
      const m={};
      for(const r of rows){ const k=keyFn(r); const o=m[k]=m[k]||{key:k, registered:0, booked:0, attended:0, paid:0, paid_after_attend:0};
        o.registered++; if(r.booked)o.booked++; if(r.attended)o.attended++; if(r.paid)o.paid++; if(r.paid_after_attend)o.paid_after_attend++; }
      return Object.values(m).map(o=>({...o, to_booked:pct(o.booked,o.registered), to_attended:pct(o.attended,o.booked), to_paid:pct(o.paid_after_attend,o.attended)}))
        .sort((x,y)=>y.registered-x.registered);
    };

    // no-show za rovnaké obdobie (podľa dátumu hodiny, nie registrácie)
    const period=bks.filter(b=>inRange(b.booking_date));
    const att=period.filter(b=>b.attendance_status==='attended').length;
    const ns=period.filter(b=>b.attendance_status==='no_show').length;

    res.json({ ok:true, from, to,
      steps:step,
      rates:{ to_booked:pct(step.booked,step.registered), to_attended:pct(step.attended,step.booked),
        to_returned:pct(step.returned,step.attended),
        to_paid:pct(step.paid_after_attend,step.attended), reg_to_attended:pct(step.attended,step.registered) },
      median_days:{ to_booking:med(lag.booking), to_attend:med(lag.attend), to_back:med(lag.back), to_pay:med(lag.pay) },
      no_show:{ attended:att, no_show:ns, rate:pct(ns, att+ns), since:await noShowFrom() },
      by_campaign:by(r=>r.campaign), by_city:by(r=>r.city),
      cities:[...new Set(rows.map(r=>r.city))].sort(),
      campaigns:[...new Set(rows.map(r=>r.campaign))].sort(),
      stuck:{
        no_booking: rows.filter(r=>!r.booked).slice(0,50),
        booked_not_attended: rows.filter(r=>r.booked&&!r.attended).slice(0,50),
        attended_not_returned: rows.filter(r=>r.attended&&!r.returned).slice(0,50),
        attended_not_paid: rows.filter(r=>r.attended&&!r.paid).slice(0,50)
      }});
  }catch(e){ res.status(500).json({error:e.message}); }
});
