// Export bodov klientov za obdobie ako CSV
app.get('/api/admin/points-summary.csv', adminAuth, async(req,res)=>{
  try {
    const from=req.query.from||'', to=req.query.to||'';
    const d=await pointsSummaryData(from, to);
    const esc=v=>`"${String(v??'').replace(/"/g,'""')}"`;
    const rows=[['Klient','Hodiny','Online','Súkromné','Odporúčania','Členstvo','Spolu body','Za čo'].join(';')];
    for(const u of (d.rows||[])){
      const za=u.items.map(i=>`${i.label} ${i.points}b`).join(' | ');
      rows.push([u.name,u.hours,u.online,u.private_hours||0,u.refs,u.hasMem?'áno':'nie',u.total,za].map(esc).join(';'));
    }
    res.setHeader('Content-Type','text/csv; charset=utf-8');
    res.setHeader('Content-Disposition',`attachment; filename=body_klientov_${from||'vse'}_${to||''}.csv`);
    res.send('﻿'+rows.join('\r\n'));
  } catch(e){ res.status(500).json({error:e.message}); }
});

// Draft payouts for a month = computed stats × rules, merged with any saved payout records
app.get('/api/admin/payouts', adminAuth, async(req,res)=>{
  try {
    const month=req.query.month||today().slice(0,7);
    const stats=await trainerMonthStats(month);
    const rules=Object.fromEntries((await q.find(db.payout_rules,{})).map(r=>[r.trainer,r]));
    const saved=Object.fromEntries((await q.find(db.payouts,{month, _type:{$exists:false}})).map(p=>[p.trainer,p]));
    const nameToId=Object.fromEntries((await q.find(db.users,{})).map(u=>[u.name,u._id]));
    const rows=await Promise.all(stats.map(async st=>{
      const {base,bonuses}=computePayout(rules[st.instructor],st);
      const sv=saved[st.instructor];
      const deductions=sv?.deductions||0;
      const affiliate = nameToId[st.instructor] ? await affiliateCommissionFor(nameToId[st.instructor], month) : 0;
      const b=sv?sv.base:base, bo=sv?sv.bonuses:bonuses;
      const cash=await cashCollectedFor(st.instructor, month); // hotovosť u trénera = zrážka
      const priv = nameToId[st.instructor] ? await privateEarningsFor(nameToId[st.instructor], month) : {amount:0,count:0};
      const tips = nameToId[st.instructor] ? await trainerTipsForMonth(nameToId[st.instructor], month) : 0;
      const total=+((b+bo+affiliate+tips+priv.amount-deductions-cash.deduct)).toFixed(2);
      // Koľko už bolo reálne vyplatené (čiastočné platby) a koľko zostáva
      const paid_total=+((sv?.payments||[]).reduce((s,p)=>s+(+p.amount||0),0) || (sv?.status==='paid'&&!(sv?.payments||[]).length ? total : 0)).toFixed(2);
      return { trainer:st.instructor, trainer_id:nameToId[st.instructor]||null, month, ...st, affiliate, tips,
        base:b, bonuses:bo, deductions, private:priv.amount,
        cash_deduct:cash.deduct, cash_pending:cash.pending,
        total, paid_total, outstanding:+Math.max(0,total-paid_total).toFixed(2),
        premium_total:+(sv?.premium_total||0),
        payments:sv?.payments||[],
        status:sv?.status||'draft', saved:!!sv, id:sv?._id||null, note:sv?.note||'',
        payment_method:sv?.payment_method||null, paid_at:sv?.paid_at||null, history:sv?.history||[] };
    }));
    res.json({month, rows, rules});
  } catch(e){ res.status(500).json({error:e.message}); }
});

// Save/generate a payout record (locks the computed numbers)
app.post('/api/admin/payouts', adminAuth, async(req,res)=>{
  try {
    const {trainer, month}=req.body;
    if(!trainer||!month) return res.status(400).json({error:'Chýba trainer/month'});
    const stats=(await trainerMonthStats(month)).find(s=>s.instructor===trainer)||{sessions:0,attendances:0,revenue:0,newClients:0,fullClasses:0};
    const rule=await q.one(db.payout_rules,{trainer});
    const {base,bonuses}=computePayout(rule,stats);
    const existing=await q.one(db.payouts,{trainer,month});
    const rec={trainer,month,base,bonuses,deductions:existing?.deductions||0,
      total:+(base+bonuses-(existing?.deductions||0)).toFixed(2),
      stats,status:existing?.status||'draft',note:existing?.note||'',updated_at:nowISO()};
    let saved;
    if(existing){ await q.update(db.payouts,{_id:existing._id},{$set:rec}); saved={...existing,...rec}; }
    else { saved=await q.insert(db.payouts,{...rec,history:[],created_at:nowISO()}); }
    await auditLog(req,'payout_generate',`${trainer} ${month}`,existing||null,rec,'');
    res.json({ok:true, id:saved._id});
  } catch(e){ res.status(500).json({error:e.message}); }
});

// Update status / deductions / note (append to history + audit)
const PAYOUT_STATUSES=['draft','approved','paid','held','cancelled'];
app.put('/api/admin/payouts/:id', adminAuth, async(req,res)=>{
  try {
    const p=await q.one(db.payouts,{_id:req.params.id});
    if(!p) return res.status(404).json({error:'Výplata nenájdená'});
    const patch={};
    if(req.body.status!==undefined){ if(!PAYOUT_STATUSES.includes(req.body.status)) return res.status(400).json({error:'Neplatný stav'}); patch.status=req.body.status; }
    if(req.body.deductions!==undefined) patch.deductions=+req.body.deductions||0;
    if(req.body.note!==undefined) patch.note=String(req.body.note);
    const deductions=patch.deductions!==undefined?patch.deductions:p.deductions;
    patch.total=+(p.base+p.bonuses-deductions).toFixed(2);
    patch.updated_at=nowISO();
    const histEntry={at:nowISO(), actor:req._auditActor||null, change:{...patch}, reason:req.body.reason||''};
    await q.update(db.payouts,{_id:p._id},{$set:patch, $push:{history:histEntry}});
    await auditLog(req,'payout_update',`${p.trainer} ${p.month}`,{status:p.status,deductions:p.deductions,total:p.total},patch,req.body.reason||'');
    res.json({ok:true});
  } catch(e){ res.status(500).json({error:e.message}); }
});

// Uzavrieť mesiac + vyplatiť trénerovi (spôsob: card|cash).
// Ak výplata ešte nie je vygenerovaná, dogeneruje sa (zamkne čísla), potom sa označí ako vyplatená,
// zapíše sa spôsob platby, história, audit, a trénerovi príde notifikácia + e-mail.
app.post('/api/admin/payouts/pay', adminAuth, async(req,res)=>{
  try {
    const {trainer, month}=req.body;
    const method=req.body.method;
    if(!trainer||!month) return res.status(400).json({error:'Chýba trainer/month'});
    if(!['card','cash'].includes(method)) return res.status(400).json({error:'Neplatný spôsob platby'});
    // 1) zabezpeč záznam výplaty (vygeneruj ak chýba) — zamkne čísla z dochádzky + affiliate
    const stats=(await trainerMonthStats(month)).find(s=>s.instructor===trainer)||{sessions:0,attendances:0,revenue:0,newClients:0,fullClasses:0,session_atts:[]};
    const rule=await q.one(db.payout_rules,{trainer});
    const {base,bonuses}=computePayout(rule,stats);
    const tUser=await q.one(db.users,{name:trainer});
    const affiliate = tUser ? await affiliateCommissionFor(tUser._id, month) : 0;
    const tips = tUser ? await trainerTipsForMonth(tUser._id, month) : 0;
    let rec=await q.one(db.payouts,{trainer,month});
    const deductions=rec?.deductions||0;
    // Hotovosť, ktorú tréner vybral a neodovzdal → zníži výplatu a zúčtuje sa
    const cash=await cashCollectedFor(trainer, month);
    const priv = tUser ? await privateEarningsFor(tUser._id, month) : {amount:0,count:0};
    const total=+(base+bonuses+affiliate+tips+priv.amount-deductions-cash.deduct).toFixed(2);
    // Čiastočné vyplatenie: admin môže zadať konkrétnu sumu (amount) — zvyšok
    // ostáva „na vyplatenie". Bez sumy sa vyplatí celý zostatok naraz.
    const prevPayments=rec?.payments||[];
    const paidBefore=+prevPayments.reduce((s,p)=>s+(+p.amount||0),0).toFixed(2);
    const outstandingBefore=+Math.max(0,total-paidBefore).toFixed(2);
    let amount = req.body.amount!==undefined && req.body.amount!==null && req.body.amount!=='' ? +req.body.amount : outstandingBefore;
    if(!(amount>0)) return res.status(400).json({error:'Suma na vyplatenie musí byť väčšia ako 0.'});
    amount=+amount.toFixed(2);
    if(outstandingBefore<=0) return res.status(400).json({error:'Za tento mesiac už je všetko vyplatené.'});
    // Suma NAD zostatok sa neoreže — eviduje sa ako 🎁 prémia (odmena navyše od štúdia)
    const premium=+Math.max(0, amount-outstandingBefore).toFixed(2);
    const payments=[...prevPayments, {amount, method, at:nowISO(), by:req.trainerUser?.name||req._auditActor?.name||'Admin', ...(premium>0?{premium}:{})}];
    const paid_total=+(paidBefore+amount).toFixed(2);
    const premium_total=+payments.reduce((s,p)=>s+(+p.premium||0),0).toFixed(2);
    const fullyPaid=paid_total>=total-0.009;
    const payMeta={ status:fullyPaid?'paid':'partial', payment_method:method, paid_at:nowISO(),
      paid_by_name:req.trainerUser?.name||req._auditActor?.name||'Admin',
      payments, paid_total, premium_total,
      base, bonuses, affiliate, tips, private:priv.amount, deductions, cash_deduct:cash.deduct, total, stats, updated_at:nowISO() };
    // Označ 'held' hotovosť ako zúčtovanú s výplatou (peniaze si nechal, výplata je o to nižšia)
    for(const cr of cash.rows.filter(r=>r.status==='held')){
      await q.update(db.payouts,{_id:cr._id},{$set:{status:'settled_payout', settled_at:nowISO(), settled_by:'výplata '+month}});
    }
    const histEntry={at:nowISO(), actor:req._auditActor||null, change:{status:payMeta.status,payment_method:method,amount,paid_total,total}, reason:fullyPaid?'Uzavretie mesiaca a vyplatenie':'Čiastočné vyplatenie'};
    if(rec){ await q.update(db.payouts,{_id:rec._id},{$set:payMeta, $push:{history:histEntry}}); }
    else { rec=await q.insert(db.payouts,{trainer,month,...payMeta,note:'',history:[histEntry],created_at:nowISO()}); }
    // 2) notifikácia + e-mail trénerovi
    const methodTxt = method==='cash' ? 'v hotovosti' : 'kartou / prevodom';
    const [y,mo]=month.split('-'); const MONTHS_SK=['','január','február','marec','apríl','máj','jún','júl','august','september','október','november','december'];
    const monthTxt=`${MONTHS_SK[+mo]||mo} ${y}`;
    if(tUser){
      await q.insert(db.notifications,{ user_id:tUser._id, type:'payout',
        title: fullyPaid ? `💵 Výplata za ${monthTxt}: ${paid_total.toFixed(2)} €` : `💵 Vyplatené ${amount.toFixed(2)} € za ${monthTxt}`,
        body: fullyPaid
          ? `Tvoja výplata za ${monthTxt} bola uzavretá a vyplatená ${methodTxt}${premium_total>0?` vrátane 🎁 prémie ${premium_total.toFixed(2)} €`:''}. Výplatná páska ti prišla na email. Ďakujeme! 💛`
          : `Dostala si ${amount.toFixed(2)} € ${methodTxt} za ${monthTxt}. Zostáva na vyplatenie ${(total-paid_total).toFixed(2)} € z celkových ${total.toFixed(2)} €.`,
        read:false, created_at:nowISO() }).catch(()=>{});
      // Rozpis výplaty (spoločný pre pásku trénerke aj doklad pre účtovníctvo)
      const lines=[
        ['Základ za odučené hodiny', base],['Bonusy', bonuses],['Affiliate provízie', affiliate],
        ['💛 Tipy od klientov (80 %)', tips],[`🎭 Súkromné hodiny${priv.count?` (${priv.count}×)`:''}`, priv.amount],
      ].filter(l=>l[1]>0);
      if(deductions>0) lines.push(['Zrážky', -deductions]);
      if(cash.deduct>0) lines.push(['Vybraná hotovosť od klientov (necháva si)', -cash.deduct]);
      if(premium_total>0) lines.push(['🎁 Prémia od štúdia (nad rámec výplaty)', premium_total]);
      const rowsHtml=lines.map(l=>`<tr><td style="padding:7px 0;border-bottom:1px solid #333">${l[0]}</td><td style="padding:7px 0;border-bottom:1px solid #333;text-align:right;color:#C9A84C;font-weight:700">${l[1].toFixed(2)} €</td></tr>`).join('');
      const paysHtml=payments.map(p=>`<tr><td style="padding:5px 0;border-bottom:1px solid #2a2a2a;color:#999;font-size:.85em">💸 ${String(p.at||'').slice(0,10)} · ${p.method==='cash'?'hotovosť':'karta/prevod'}${p.premium?` · z toho prémia ${(+p.premium).toFixed(2)} €`:''}</td><td style="padding:5px 0;border-bottom:1px solid #2a2a2a;text-align:right;color:#81c784">${(+p.amount).toFixed(2)} €</td></tr>`).join('');
      const tableHtml=`<table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;margin-top:8px">${rowsHtml}
        <tr><td style="padding:12px 0 4px;font-weight:800">SPOLU vyplatené</td><td style="padding:12px 0 4px;text-align:right;font-weight:800;font-size:1.15em;color:#81c784">${paid_total.toFixed(2)} €</td></tr>
        ${paysHtml}</table>`;
      if(fullyPaid){
        // 1) Výplatná páska trénerke
        if(tUser.email) sendMail(tUser.email, `💵 Výplatná páska – ${monthTxt} — Fusion Academy`,
          emailTemplate(`Výplatná páska – ${monthTxt}`,
            `<p>Ahoj <b>${tUser.name.split(' ')[0]}</b>,</p><p>tvoja výplata za <b>${monthTxt}</b> je uzavretá a vyplatená ${methodTxt}.</p>
             <p style="color:#999;font-size:.85em">${stats.sessions||0} odučených hodín · ${stats.attendances||0} účastí</p>${tableHtml}
             ${premium_total>0?`<p>🎁 Prémia ${premium_total.toFixed(2)} € je odmena navyše od štúdia — ďakujeme za skvelú prácu!</p>`:''}
             <p>Ďakujeme! 💛</p>`, 'Otvoriť appku', `${APP_URL}/trainer`)).catch(()=>{});
        // 2) Doklad pre účtovníctvo adminom
        const admins=await q.find(db.users,{is_admin:true});
        for(const a of admins){ if(a.email) sendMail(a.email, `🧾 Doklad o výplate — ${trainer} · ${monthTxt}`,
          emailTemplate(`Doklad o výplate trénera`,
            `<p><b>Tréner:</b> ${trainer}<br><b>Obdobie:</b> ${monthTxt}<br><b>Uzavrel:</b> ${payMeta.paid_by_name} · ${nowISO().slice(0,10)}</p>${tableHtml}
             <p style="color:#999;font-size:.8em">Nárok podľa výpočtu: ${total.toFixed(2)} €${premium_total>0?` · prémia navyše: ${premium_total.toFixed(2)} €`:''} · vyplatené spolu: ${paid_total.toFixed(2)} €</p>`,
            'Otvoriť výplaty', `${APP_URL}/admin`)).catch(()=>{}); }
      } else if(tUser.email){
        sendMail(tUser.email, `💵 Čiastočná výplata za ${monthTxt} — Fusion Academy`,
          `Ahoj ${tUser.name.split(' ')[0]},\n\ndostala si ${amount.toFixed(2)} € ${methodTxt} za ${monthTxt}. Zostáva na vyplatenie ${(total-paid_total).toFixed(2)} € z celkových ${total.toFixed(2)} €.\n\nFusion Academy`).catch(()=>{});
      }
    }
    await auditLog(req,'payout_pay',`${trainer} ${month} · ${method} · ${total.toFixed(2)} €`,rec?{status:rec.status}:null,payMeta,'');
    res.json({ok:true, total, amount, paid_total, premium, premium_total, outstanding:+Math.max(0,total-paid_total).toFixed(2), fully_paid:fullyPaid, method, trainer, month});
  } catch(e){ res.status(500).json({error:e.message}); }
});

app.get('/api/admin/payouts/export.csv', adminAuth, async(req,res)=>{
  const month=req.query.month||today().slice(0,7);
  const stats=await trainerMonthStats(month);
  const rules=Object.fromEntries((await q.find(db.payout_rules,{})).map(r=>[r.trainer,r]));
  const saved=Object.fromEntries((await q.find(db.payouts,{month, _type:{$exists:false}})).map(p=>[p.trainer,p]));
  const esc=v=>`"${String(v??'').replace(/"/g,'""')}"`; const num=n=>(+n).toFixed(2).replace('.',',');
  const rows=[['Tréner','Mesiac','Hodiny','Účasti','Tržby','Základ','Bonusy','Zrážky','Spolu','Stav'].join(';')];
  for(const st of stats){
    const {base,bonuses}=computePayout(rules[st.instructor],st); const sv=saved[st.instructor];
    const b=sv?sv.base:base, bo=sv?sv.bonuses:bonuses, ded=sv?.deductions||0;
    rows.push([st.instructor,month,st.sessions,st.attendances,num(st.revenue),num(b),num(bo),num(ded),num(b+bo-ded),sv?.status||'draft'].map(esc).join(';'));
  }
  res.setHeader('Content-Type','text/csv; charset=utf-8');
  res.setHeader('Content-Disposition',`attachment; filename=vyplaty_${month}.csv`);
  res.send('﻿'+rows.join('\r\n'));
});

// ─── PHASE K: Refundácie ────────────────────────────────────────────────────────
const REFUND_REASONS={ requested:'Na žiadosť klienta', duplicate:'Duplicitná platba', service_issue:'Problém so službou', cancelled_class:'Zrušená hodina', goodwill:'Ústretovosť', error:'Chyba účtovania', other:'Iné' };
const REFUND_TYPES=['full','partial','storno','credit_note','app_credit','transfer'];

async function ppRefundCapture(captureId, amount){
  const token=await ppGetToken();
  const r=await fetch(`${PAYPAL_BASE}/v2/payments/captures/${captureId}/refund`,{
    method:'POST', headers:{'Authorization':`Bearer ${token}`,'Content-Type':'application/json'},
    body: JSON.stringify(amount?{amount:{value:(+amount).toFixed(2),currency_code:'EUR'}}:{})
  });
  return { status:r.status, body: await r.json().catch(()=>({})) };
}

app.get('/api/admin/refund-reasons', adminAuth, (req,res)=>res.json({reasons:REFUND_REASONS,types:REFUND_TYPES}));

// ─── PHASE M: Exporty jedným klikom ─────────────────────────────────────────────
function toCsv(header, rows){
  const esc=v=>`"${String(v??'').replace(/"/g,'""')}"`;
  const out=[header.join(';')];
  for(const r of rows) out.push(r.map(esc).join(';'));
  return '﻿'+out.join('\r\n');
}
async function exportDataset(name){
  const num=n=>(+n||0).toFixed(2).replace('.',',');
  if(name==='members'){
    const users=(await q.find(db.users,{is_admin:{$ne:true}})).filter(u=>!u.is_child);
    const membs=await q.find(db.memberships,{});
    const active=Object.fromEntries(membs.filter(m=>(m.expires_at||'')>new Date().toISOString()).map(m=>[m.user_id,m]));
    return {file:'clenovia.csv', csv:toCsv(['Meno','Email','Telefon','Rola','Aktivne clenstvo','Expirace','Navstevy','Registracia'],
      users.map(u=>[u.name,u.email,u.phone||'',u.user_type||'client',active[u._id]?.plan_name||'—',(active[u._id]?.expires_at||'').slice(0,10),u.visit_count||0,(u.created_at||'').slice(0,10)]))};
  }
  if(name==='campaigns'){
    const list=await q.find(db.campaigns,{}); const revMap=await campaignRevenueMap();
    return {file:'kampane.csv', csv:toCsv(['Nazov','Platforma','Od','Do','Rozpocet','Naklad','Imprese','Kliky','Registracie','Clenstva','Trzby','ROAS'],
      list.map(c=>{ const rev=revMap[(c.name||'').toLowerCase().trim()]?.revenue||0; return [c.name,c.platform,c.date_from||'',c.date_to||'',num(c.budget),num(c.spend),c.impressions||0,c.clicks||0,c.registrations||0,c.memberships||0,num(rev),(rev/Math.max(+c.spend||1,1)).toFixed(2)];}))};
  }
  if(name==='payments'){
    const users=Object.fromEntries((await q.find(db.users,{})).map(u=>[u._id,u.name]));
    const list=(await q.find(db.payments,{})).filter(p=>['completed','active'].includes(p.status));
    return {file:'platby.csv', csv:toCsv(['Datum','Klient','Popis','Suma','Brana','Stav'],
      list.map(p=>[(p.captured_at||p.created_at||'').slice(0,10),users[p.user_id]||'—',p.description||'',num(p.amount),p.provider||p.payment_method||'—',p.status]))};
  }
  if(name==='refunds'){
    const list=await q.find(db.refunds,{});
    return {file:'refundacie.csv', csv:toCsv(['Datum','Klient','Typ','Suma','Dovod','Brana','Dobropis'],
      list.map(r=>[(r.created_at||'').slice(0,10),r.client_name||'—',r.type,num(r.amount),REFUND_REASONS[r.reason]||r.reason,r.gateway||'—',r.credit_note||'']))};
  }
  if(name==='crm'){
    const users=(await q.find(db.users,{is_admin:{$ne:true}})).filter(u=>!u.is_child);
    const payments=(await q.find(db.payments,{})).filter(p=>['completed','active'].includes(p.status));
    const membs=(await q.find(db.memberships,{})).filter(m=>m.payment_method);
    const paid={}; payments.forEach(p=>paid[p.user_id]=(paid[p.user_id]||0)+(+p.amount||0)); membs.forEach(m=>paid[m.user_id]=(paid[m.user_id]||0)+(+m.price||0));
    return {file:'crm.csv', csv:toCsv(['Meno','Email','Telefon','LTV','Navstevy','Zdroj','Kampan','Registracia'],
      users.map(u=>[u.name,u.email,u.phone||'',num(paid[u._id]||0),u.visit_count||0,u.utm_source||u.lead_source||'',u.utm_campaign||'',(u.created_at||'').slice(0,10)]))};
  }
  return null;
}
app.get('/api/admin/export/:dataset.csv', adminAuth, async(req,res)=>{
  try {
    const d=await exportDataset(req.params.dataset);
    if(!d) return res.status(404).send('Neznámy export');
    res.setHeader('Content-Type','text/csv; charset=utf-8');
    res.setHeader('Content-Disposition',`attachment; filename=${d.file}`);
    res.send(d.csv);
  } catch(e){ res.status(500).send(e.message); }
});

