// Shop funnel eventy (view/checkout) — nákupy sa berú z transakcií, nie z frontendu
app.post('/api/shop/event', auth, async(req,res)=>{
  try{
    const type=String(req.body.type||'');
    if(!['shop_open','checkout_open'].includes(type)) return res.json({ok:true});
    const u=await q.one(db.users,{_id:req.session.uid});
    if(/@test-fa-qa\.local$/.test(u?.email||'')) return res.json({ok:true, test:true});
    // max 1 event daného typu na deň a osobu — žiadny spam v štatistikách
    const key='shopq_'+type+'_'+req.session.uid+'_'+today();
    if(!(await q.one(db.settings,{key}))){
      await q.insert(db.settings,{key, value:1, at:nowISO()});
      await q.insert(db.shop_events,{user_id:req.session.uid, type, item:String(req.body.item||'').slice(0,60), day:today(), created_at:nowISO()});
    }
    res.json({ok:true});
  }catch(e){ res.json({ok:false}); }
});
app.get('/api/admin/shop-analytics', adminAuth, async(req,res)=>{
  try{
    const month=String(req.query.month||today().slice(0,7));
    const ev=(await q.find(db.shop_events,{})).filter(e=>String(e.day||'').startsWith(month));
    const users=await q.find(db.users,{});
    const testIds=new Set(users.filter(u=>/@test-fa-qa\.local$/.test(u.email||'')).map(u=>u._id));
    const tx=(await q.find(db.transactions,{})).filter(t=>t.month===month && !testIds.has(t.user_id));
    const buyers=new Set(tx.map(t=>t.user_id));
    const cat=t=>t.type==='membership'||t.type==='subscription'?'Členstvá':(t.type==='single_entry'?'Vstupy/permanentky':(t.type==='order'||/tričko|taška|tielko|merch/i.test(t.note||'')?'Merch':(/event|masterclass|workshop/i.test(t.note||'')?'Eventy':'Ostatné')));
    const byCat={};
    for(const t of tx){ const c=cat(t); byCat[c]=byCat[c]||{n:0,sum:0}; byCat[c].n++; byCat[c].sum=+(byCat[c].sum+(+t.amount||0)).toFixed(2); }
    const total=+tx.reduce((a,t)=>a+(+t.amount||0),0).toFixed(2);
    const failed=(await q.find(db.payments,{})).filter(p=>String(p.created_at||'').startsWith(month)&&['failed','cancelled'].includes(p.status)).length;
    const pendingNow=(await q.find(db.payments,{status:'pending_manual'})).length;
    res.json({ok:true, month,
      funnel:{ shop_open:new Set(ev.filter(e=>e.type==='shop_open').map(e=>e.user_id)).size,
        checkout_open:new Set(ev.filter(e=>e.type==='checkout_open').map(e=>e.user_id)).size,
        purchased:buyers.size },
      revenue:{total, orders:tx.length, avg:tx.length?+(total/tx.length).toFixed(2):0, by_category:byCat},
      failed_payments:failed, pending_manual:pendingNow});
  }catch(e){ res.status(500).json({error:e.message}); }
});
app.get('/api/shop/overview', auth, async(req,res)=>{
  try{
    const u=await q.one(db.users,{_id:req.session.uid});
    const m=await checkMembership(u._id);
    const plan=m?MEMBERSHIP_PLANS[m.plan_id]:null;
    // posledná permanentka (bundle) — kvôli celkovému počtu a expirácii
    const bundles=(await q.find(db.memberships,{user_id:u._id, status:'bundle'}))
      .sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));
    const lastBundle=bundles[0]||null;
    const bundlePlan=lastBundle?MEMBERSHIP_PLANS[lastBundle.plan_id]:null;
    // reálna návštevnosť za 30 dní (pre poctivé odporúčania)
    const since=new Date(Date.now()-30*24*3600*1000).toISOString().slice(0,10);
    const visits30=(await q.find(db.bookings,{user_id:u._id, status:'attended'}))
      .filter(b=>String(b.booking_date||'')>=since).length;
    const pending=(await q.find(db.payments,{user_id:u._id, status:'pending_manual'}))
      .map(p=>({id:p._id, description:p.description, amount:p.amount, created_at:p.created_at}));
    const tx=(await q.find(db.transactions,{user_id:u._id}))
      .sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at))).slice(0,20)
      .map(t=>({date:t.created_at, note:t.note||t.type, amount:t.amount, method:t.payment_method||'', type:t.type}));
    const invoices=(await q.find(db.invoices,{user_id:u._id}))
      .sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||''))).slice(0,20)
      .map(i=>({number:i.number, total:i.total, date:i.issued_at||i.created_at}));
    const entries=u.single_entries||0;
    const daysLeft=m?Math.ceil((new Date(m.expires_at)-Date.now())/86400000):null;
    // Odporúčania: max 3, len z reálnych dát — žiadny billboard
    const rec=[];
    if(pending.length) rec.push({key:'pay_pending', title:'Čaká ťa nedokončená platba',
      text:'Máš objednávku na '+pending[0].description+' — zaplať v hotovosti na hodine alebo prevodom a hneď ti ju aktivujeme.'});
    if(m && daysLeft!==null && daysLeft<=5 && !u.stripe_subscription_id)
      rec.push({key:'renew', title:'Členstvo ti čoskoro končí', text:plan?.name+' vyprší o '+daysLeft+' dní. Predĺž si ho, nech nestratíš prístup.', plan_id:m.plan_id});
    if(!m && entries>0 && entries<=2)
      rec.push({key:'entries_low', title:'Dochádza ti permanentka', text:'Zostáva ti '+entries+' '+(entries===1?'vstup':'vstupy')+'. Kúp si ďalšiu, nech nemusíš riešiť platby na hodine.', plan_id:'permanentka10'});
    if(!m && visits30>=5)
      rec.push({key:'membership_worth', title:'Pri tvojom tempe sa oplatí členstvo',
        text:'Za posledný mesiac si bola na '+visits30+' hodinách — na vstupoch je to ~'+(visits30*10)+' €. Bronze členstvo stojí 50 €/mes.', plan_id:'bronze'});
    if(!m && entries<=0 && visits30===0 && !pending.length)
      rec.push({key:'start', title:'Začni členstvom alebo permanentkou', text:'Vyber si, čo ti sedí — mesačné členstvo Bronze za 50 € alebo 10 vstupov za 80 €.'});
    if((u.referral_credit||0)>=10)
      rec.push({key:'credit', title:'Máš '+(+u.referral_credit).toFixed(2)+' € Fusion kreditu 🎉', text:'Môžeš ho použiť ako zľavu pri nákupe členstva alebo permanentky.'});
    res.json({ok:true,
      membership: m?{plan_id:m.plan_id, plan_name:m.plan_name, expires_at:m.expires_at, days_left:daysLeft,
        price:plan?.price||m.price, auto_renew:!!u.stripe_subscription_id, status:m.status}:null,
      entries:{left:entries, total:bundlePlan?.entries||((entries>0&&!bundlePlan)?entries:10), expires_at:lastBundle?.expires_at||null},
      free_credits:u.free_credits||0, credit:+(u.referral_credit||0),
      visits30, pending, purchases:tx, invoices, recommendations:rec.slice(0,3)});
  }catch(e){ res.status(500).json({error:e.message}); }
});

// ── Testovací účet: admin sa prepne do čistého klientskeho účtu (vzhľad + funkčnosť) ──
// Účet je @test-fa-qa.local → mimo Business Ranku, predajných notifikácií aj kampaní.
// Pri každom vstupe sa vyresetuje na prázdno. Návrat cez /api/test-account/back.
const TEST_ACC_EMAIL='test-ucet@test-fa-qa.local';
app.post('/api/admin/test-account', adminAuth, async(req,res)=>{
  try{
    let t=await q.one(db.users,{email:TEST_ACC_EMAIL});
    if(!t){
      t=await q.insert(db.users,{name:'Test Klientka', email:TEST_ACC_EMAIL, password:null,
        phone:'', referral_code:'TESTUCET1', sponsor_id:null, rank:1, is_admin:false, active:true,
        user_type:'client', visit_count:0, referral_credit:0, lead_source:'test',
        consent_at:nowISO(), created_at:today()});
    }
    // reset na prázdny účet
    for(const col of ['bookings','notifications','memberships','transactions','payments','invoices','promo_redemptions','spins','mail_log']){
      try{ await q.remove(db[col],{user_id:t._id},{multi:true}); }catch(e){}
    }
    await q.update(db.users,{_id:t._id},{$set:{visit_count:0, free_class_used:false, free_credits:0,
      single_entries:0, referral_credit:0, membership_plan:null, membership_expires:null, avatar:null,
      gender:null, nickname:'', status:''},
      $unset:{venceky_class_id:true, venceky_role:true, venceky_school_id:true, vencek_alumni:true}});
    req.session.admin_uid=req.session.uid;   // cesta späť
    req.session.uid=t._id; req.session.sv=t.sess_ver||0;
    res.json({ok:true, redirect_to:'/client-dashboard'});
  }catch(e){ res.status(500).json({error:e.message}); }
});
app.post('/api/test-account/back', async(req,res)=>{
  try{
    if(!req.session.admin_uid) return res.status(400).json({error:'Nie si v testovacom účte'});
    const adm=await q.one(db.users,{_id:req.session.admin_uid});
    if(!adm?.is_admin) return res.status(403).json({error:'Chyba návratu'});
    // Uprac po teste aj PRI ODCHODE — reset pri vstupe nestačí: rezervácia z testu
    // by dovtedy visela reálnym klientkam v zozname účastníčok hodiny.
    try{
      const t=await q.one(db.users,{email:TEST_ACC_EMAIL});
      if(t) for(const col of ['bookings','notifications','memberships','transactions','payments','invoices','promo_redemptions','spins','mail_log']){
        try{ await q.remove(db[col],{user_id:t._id},{multi:true}); }catch(e){}
      }
    }catch(e){}
    req.session.uid=adm._id; req.session.sv=adm.sess_ver||0; delete req.session.admin_uid;
    res.json({ok:true, redirect_to:'/admin'});
  }catch(e){ res.status(500).json({error:e.message}); }
});

