// ONLINE CLASS ACCESS
// ═══════════════════════════════════════════════════════════════════════════════
// Online prístup: plán s online:true, alebo Silver/Gold/online podľa id či názvu
// (staré/členstvá z migrácie nemusia mať presné plan_id), tréner/admin vždy.
// „Online zdarma pre všetkých" — admin môže dnešný online prenos otvoriť každému
// (promo deň). Kľúč drží konkrétny dátum, takže o polnoci automaticky vyprší.
async function onlineFreeToday(){ const s=await q.one(db.settings,{key:'online_free_date'}); return s?.value===today(); }
function hasOnlineAccess(m, u){
  if(u && (u.is_admin || u.user_type==='trainer')) return true;
  // Výherný pass (online_passes) tu úmyselne NEdáva plný prístup — spotrebuje sa
  // až klikom „pripojiť sa" (/api/online/enter). Po spotrebe platí do konca dňa:
  if(u && u.online_pass_used_date===today()) return true;
  if(!m) return false;
  const plan=MEMBERSHIP_PLANS[m.plan_id];
  if(plan && plan.online) return true;
  return /silver|gold|online/i.test(String(m.plan_id||'')+' '+String(m.plan_name||''));
}
// Klientske JS chyby → do server logov (diagnostika bielej obrazovky na zariadeniach,
// ku ktorým nemám prístup). Bez dát navyše, len chybová hláška + stránka + prehliadač.
app.post('/api/client-error', rlPublic, async(req,res)=>{
  try{
    const msg=String(req.body.message||'').slice(0,500);
    const page=String(req.body.page||'').slice(0,200);
    const stack=String(req.body.stack||'').slice(0,800);
    console.error(`🐞 CLIENT-ERROR [${page}] uid=${req.session?.uid||'—'} ua=${String(req.headers['user-agent']||'').slice(0,80)}\n   ${msg}\n   ${stack}`);
    res.json({ok:true});
  }catch(e){ res.json({ok:false}); }
});

// Tréner online hodiny pre daný dátum: override na online hodine > override na
// párovej fyzickej hodine (rovnaký deň/čas, mesto = stream_city) > inštruktor
// online hodiny > inštruktor párovej hodiny. (Rovnaká logika ako /api/online/upcoming.)
async function onlineInstructorFor(cls, date){
  try{
    const si=await sessionInstructor(cls, date).catch(()=>null);
    if(si?.overridden) return si.instructor;
    const sameSlot=(await q.find(db.classes,{active:true, day_of_week:cls.day_of_week}))
      .filter(p=>p.category!=='Online' && p.time_start===cls.time_start);
    // najprv presné párovanie podľa mesta streamu, inak hocijaká fyzická hodina v rovnakom čase
    const pair=sameSlot.find(p=>(p.location||'')===(cls.stream_city||'')) || sameSlot[0];
    if(pair){
      const psi=await sessionInstructor(pair, date).catch(()=>null);
      // aktuálny tréner fyzickej hodiny má prednosť pred zastaraným menom na online zázname
      return psi?.overridden ? psi.instructor : (pair.instructor||cls.instructor||'');
    }
    return cls.instructor||'';
  }catch(e){ return cls.instructor||''; }
}
// Najbližší dátum (YYYY-MM-DD), kedy sa hodina koná (dnes, ak je dnes jej deň)
function nextOccurrence(dow){
  const d=new Date(); const diff=(dow-d.getDay()+7)%7;
  return new Date(d.getTime()+diff*86400000).toISOString().slice(0,10);
}

app.get('/api/online/classes', auth, async(req,res)=>{
  try{
  const m = await checkMembership(req.session.uid);
  const mu = await q.one(db.users,{_id:req.session.uid});
  const freeDay = await onlineFreeToday();
  const hasFull = freeDay || hasOnlineAccess(m, mu);
  // Výherný pass z kolesa: spotrebuje sa klikom „pripojiť sa" — má prednosť pred vstupmi
  const passMode = !hasFull && (mu?.online_passes||0)>0;
  // Permanentkárka: prístup má, ale sledovanie ju stojí 1 vstup (odčíta /api/online/enter)
  const entryMode = !hasFull && !passMode && (mu?.single_entries||0)>0;
  const hasAccess = hasFull || passMode || entryMode;
  const classes = (await q.find(db.classes,{category:'Online',active:true}))
    .filter(c=>classRunsOn(c, nextOccurrence(c.day_of_week)));
  const result = await Promise.all(classes.map(async c=>({
    ...c,
    instructor: await onlineInstructorFor(c, nextOccurrence(c.day_of_week)),
    // V entry režime sa stream NEprezradí vopred — vydá ho až /api/online/enter po odpočte
    stream_url: hasFull ? (c.stream_url||null) : null,
    stream_key: hasFull ? (c.stream_key||null) : null,
    has_stream: !!(c.stream_url||c.stream_key),
    has_access: hasAccess,
    locked: !hasAccess,
  })));
  res.json({classes:result, has_access:hasAccess, online_free_today:freeDay, access_mode: hasFull?'full':(passMode?'pass':(entryMode?'entry':null)),
    entries: mu?.single_entries||0, online_passes: mu?.online_passes||0,
    media_base:(process.env.MEDIA_BASE||'').replace(/\/$/,''), membership:m?{plan_id:m.plan_id,plan_name:m.plan_name,expires_at:m.expires_at}:null});
  }catch(e){ res.status(500).json({error:e.message}); }
});

// Vstup do online prenosu pre permanentkárku: odčíta 1 vstup (raz za deň) a vydá stream.
// Plný online prístup (Silver/Gold/Online) prechádza bez odpočtu.
app.post('/api/online/enter', auth, async(req,res)=>{
  try{
    const u=await q.one(db.users,{_id:req.session.uid});
    const m=await checkMembership(u._id);
    const cls=await q.one(db.classes,{_id:String(req.body.class_id||'')});
    if(!cls || cls.category!=='Online' || !classRunsOn(cls, today())) return res.status(404).json({error:'Online hodina nenájdená'});
    const stream={stream_url:cls.stream_url||null, stream_key:cls.stream_key||null};
    if(await onlineFreeToday()) return res.json({ok:true, charged:false, mode:'full', free_day:true, stream});
    if(hasOnlineAccess(m,u)) return res.json({ok:true, charged:false, mode:'full', stream});
    // 1) Výherný pass z kolesa — spotrebuje sa práve teraz, prístup platí do konca dňa
    if((u.online_passes||0)>0){
      await q.update(db.users,{_id:u._id},{$set:{online_passes:(u.online_passes||0)-1, online_pass_used_date:today()}});
      await q.insert(db.notifications,{user_id:u._id, type:'online_pass',
        title:'🎡 Použila si výhernú online hodinu', body:'Príjemné cvičenie! Prístup k dnešnému prenosu ti platí do konca dňa.',
        read:false, created_at:nowISO()}).catch(()=>{});
      await auditLog(req,'online_pass_use',u._id,{passes:u.online_passes},{remaining:(u.online_passes||0)-1, class:cls.name},'');
      return res.json({ok:true, charged:true, mode:'pass', remaining:(u.online_passes||0)-1, stream});
    }
    // 2) Permanentka — 1 vstup, raz za deň
    const entries=u.single_entries||0;
    const guardKey='online_entry_'+u._id+'_'+today();
    if(await q.one(db.settings,{key:guardKey})) return res.json({ok:true, charged:false, mode:'entry', remaining:entries, stream});
    if(entries<=0) return res.status(402).json({error:'Nemáš žiadne vstupy na permanentke.'});
    await q.update(db.users,{_id:u._id},{$set:{single_entries:entries-1}});
    await q.insert(db.settings,{key:guardKey, value:true, at:nowISO()});
    await q.insert(db.notifications,{user_id:u._id, type:'online_entry',
      title:'🎟️ Použitý 1 vstup na online hodinu',
      body:`Za dnešnú online hodinu sa ti odčítal 1 vstup z permanentky. Zostáva ti ${entries-1} ${entries-1===1?'vstup':entries-1>=2&&entries-1<=4?'vstupy':'vstupov'}.`,
      read:false, created_at:nowISO()}).catch(()=>{});
    await auditLog(req,'online_entry_charge',u._id,{entries},{remaining:entries-1, class:cls.name},'');
    res.json({ok:true, charged:true, mode:'entry', remaining:entries-1, stream});
  }catch(e){ res.status(500).json({error:e.message}); }
});

