app.post('/api/admin/online-free-day', adminAuth, async(req,res)=>{
  try{
    const on=!!req.body.on;
    const ex=await q.one(db.settings,{key:'online_free_date'});
    if(on){
      if(ex) await q.update(db.settings,{key:'online_free_date'},{$set:{value:today(), at:nowISO()}});
      else await q.insert(db.settings,{key:'online_free_date', value:today(), at:nowISO()});
      if(!(await q.one(db.settings,{key:'online_free_feed_'+today()}))){
        await q.insert(db.feed,{ author_id:'studio', author_name:'Fusion Academy', author_badge:{emoji:'📢',label:'Oznam'},
          studio_announcement:true,
          text:'💻🎉 Dnešná ONLINE ZUMBA je ZDARMA pre všetkých!\n\nPripoj sa večer cez Dashboard — dnes netreba členstvo ani vstupy. Povedz aj kamoškám! 💃',
          image:null, reactions:{}, comments:[], created_at:nowISO() }).catch(()=>{});
        await q.insert(db.settings,{key:'online_free_feed_'+today(), value:true, at:nowISO()});
      }
    } else if(ex) await q.update(db.settings,{key:'online_free_date'},{$set:{value:null, at:nowISO()}});
    await auditLog(req,'online_free_day',null,{},{on},'').catch(()=>{});
    res.json({ok:true, active:on});
  }catch(e){ res.status(500).json({error:e.message}); }
});

app.get('/api/online/upcoming', auth, async(req,res)=>{
  try{
    const dow=new Date().getDay();
    const toMin=t=>{ const [h,m]=String(t||'0:0').split(':').map(Number); return h*60+m; };
    const nowMin=(d=>d.getHours()*60+d.getMinutes())(new Date());
    const classes=(await q.find(db.classes,{category:'Online', active:true, day_of_week:dow}))
      .filter(c=>classRunsOn(c, today()))
      .sort((a,b)=>(a.time_start||'').localeCompare(b.time_start||''));
    // koniec hodiny: ak time_end chýba, počítaj 60 minút (nie 0 — banner mizol 5 min po štarte)
    const endMin=c=>{ const e=toMin(c.time_end); const s=toMin(c.time_start); return e>s?e:s+60; };
    const inWin=c=> nowMin>=toMin(c.time_start)-90 && nowMin<endMin(c)+5;
    const isRun=c=> nowMin>=toMin(c.time_start) && nowMin<endMin(c)+5;
    // pri viacerých hodinách v okne má prednosť tá, ktorá PRÁVE beží (s najneskorším štartom),
    // inak najbližšia nadchádzajúca — predtým .find() vracal vždy prvú a 19:00 Zumba sa nedostala na rad
    const cands=classes.filter(inWin);
    const cls=cands.filter(isRun).sort((a,b)=>toMin(b.time_start)-toMin(a.time_start))[0]
           || cands.filter(c=>!isRun(c)).sort((a,b)=>toMin(a.time_start)-toMin(b.time_start))[0];
    if(!cls) return res.json({ok:true, upcoming:null});
    const m=await checkMembership(req.session.uid);
    const upcU=await q.one(db.users,{_id:req.session.uid});
    const freeDay=await onlineFreeToday();
    const hasFull=freeDay || hasOnlineAccess(m, upcU);
    const passMode=!hasFull && (upcU?.online_passes||0)>0;   // výherná online hodina z kolesa
    const entryMode=!hasFull && !passMode && (upcU?.single_entries||0)>0; // permanentka: za 1 vstup
    const hasAccess=hasFull||passMode||entryMode;
    const liveKeys=await liveStreamKeys();
    const running = nowMin>=toMin(cls.time_start);
    const live = (cls.stream_key && liveKeys.has(cls.stream_key)) || running; // bez media servera = podľa času
    const booked = !!(await q.one(db.bookings,{class_id:cls._id, user_id:req.session.uid, booking_date:today(), status:{$ne:'cancelled'}}));
    // Tréner pre dnešný termín — výmena (override) môže byť nastavená na online hodine
    // ALEBO na párovej fyzickej hodine (rovnaký deň/čas, mesto = stream_city), z ktorej
    // sa vysiela. Override má vždy prednosť pred štandardným inštruktorom.
    const insName = await onlineInstructorFor(cls, today());
    // Nadväzujúca online hodina z toho istého mesta (18:00 technika → 19:00 Zumba):
    // jeden prenos, klientka má vedieť, že môže ostať pripojená.
    const nxt = classes.find(c=>c._id!==cls._id && (c.stream_city||'')===(cls.stream_city||'')
      && c.time_start===cls.time_end);
    res.json({ok:true, upcoming:{ id:cls._id, name:cls.name, time_start:cls.time_start, time_end:cls.time_end,
      next_part: nxt?{name:nxt.name, time_start:nxt.time_start, time_end:nxt.time_end}:null,
      src:cls.stream_city||'', starts_in_min:Math.max(0,toMin(cls.time_start)-nowMin), running, live,
      instructor:insName, free_today:freeDay,
      has_access:hasAccess, access_mode: hasFull?'full':(passMode?'pass':(entryMode?'entry':null)), entries:upcU?.single_entries||0,
      plan_id:m?m.plan_id:null, booked }});
  }catch(e){ res.status(500).json({error:e.message}); }
});

// Ticker: keď online hodina začne, pošli notifikáciu všetkým s online prístupom (raz/deň/hodinu)
setInterval(async()=>{
  try{
    const dow=new Date().getDay(); const nowHM=new Date().toTimeString().slice(0,5);
    const classes=(await q.find(db.classes,{category:'Online', active:true, day_of_week:dow, time_start:nowHM}))
      .filter(c=>classRunsOn(c, today()));
    for(const cls of classes){
      const guardKey='online_live_'+cls._id+'_'+today();
      if(await q.one(db.settings,{key:guardKey})) continue;
      await q.insert(db.settings,{key:guardKey, value:true, at:nowISO()});
      // Auto-absolvovanie: prihlásené klientky dostanú účasť + body + odznaky hneď pri štarte
      // (majú zaplatené online členstvo). Trénerovi sa NIČ nepripisuje — online hodiny sa
      // nepočítajú do výplat ani odučených hodín (vylúčené v trainerMonthStats).
      try{
        const bks=await q.find(db.bookings,{class_id:cls._id, booking_date:today(), status:'confirmed'});
        for(const b of bks){
          await q.update(db.bookings,{_id:b._id},{$set:{status:'attended', attended_at:nowISO(), attended_by:'online_auto'}});
          if(!b.is_child_booking && b.user_id){
            const bu=await q.one(db.users,{_id:b.user_id});
            if(bu){
              await creditAttendance(bu);
              // Výherný online pass z kolesa sa spotrebuje prvou absolvovanou online hodinou
              const bm=await checkMembership(bu._id);
              const planB=bm?MEMBERSHIP_PLANS[bm.plan_id]:null;
              // Výherný online pass sa tu už NEspotrebúva — odčíta sa až keď
              // klientka reálne klikne „pripojiť sa" (/api/online/enter).
            }
          }
        }
        if(bks.length) console.log(`🌐 Online auto-účasť: ${bks.length} klientok (${cls.time_start} ${cls.stream_city||''})`);
      }catch(e){ console.error('online auto-attend:', e.message); }
      const membs=(await q.find(db.memberships,{status:'active'})).filter(m=>(m.expires_at||'')>new Date().toISOString());
      const notified=new Set();
      for(const m of membs){
        if(!hasOnlineAccess(m,null)||notified.has(m.user_id)) continue;
        notified.add(m.user_id);
        await q.insert(db.notifications,{user_id:m.user_id, type:'online_live',
          title:'🔴 '+String(cls.name||'Online hodina').replace(/s*ONLINE.*$/i,'')+' ONLINE PRÁVE ZAČÍNA!', body:`Živé vysielanie z mesta ${cls.stream_city||''} beží. Pripoj sa jedným klikom!`,
          link:'/online', read:false, created_at:nowISO()}).catch(()=>{});
      }
      console.log(`🔴 Online LIVE notifikácie: ${notified.size} členov (${cls.time_start} ${cls.stream_city||''})`);
    }
  }catch(e){}
}, 60*1000);

// ═══════════════════════════════════════════════════════════════════════════════
// KIOSK MODE — digitálna recepcia (fullscreen tablet pri vstupe do štúdia)
// ═══════════════════════════════════════════════════════════════════════════════
const KIOSK_STUDIOS = { detva:'Detva', zvolen:'Zvolen', bb:'Banská Bystrica', brezno:'Brezno' };
const KIOSK_DEFAULT_WIDGETS = { program:true, stats:true, klient_mesiaca:true, birthdays:true, upsell:true, health:true, app_promo:true, referral:true, challenge:true, custom:true, events:true };
async function kioskConfig(){
  let s = await q.one(db.settings,{key:'kiosk_config'});
  if(!s){
    const studios={};
    for(const slug of Object.keys(KIOSK_STUDIOS)){
      studios[slug]={ enabled:false, token:require('crypto').randomBytes(12).toString('hex'),
        interval_s:12, idle_s:15, night_off:'21:30', night_on:'07:30',
        widgets:{...KIOSK_DEFAULT_WIDGETS}, announcement:'', custom_slides:[] };
    }
    s = await q.insert(db.settings,{key:'kiosk_config', value:{studios}, at:nowISO()});
  }
  return s.value;
}
async function kioskAuth(req,res){
  const slug=String(req.params.studio||req.query.studio||req.body?.studio||'').toLowerCase();
  if(!KIOSK_STUDIOS[slug]){ res.status(404).json({error:'Neznáme štúdio'}); return null; }
  const cfg=await kioskConfig();
  const st=cfg.studios[slug];
  const k=String(req.query.k||req.body?.k||'');
  if(!st || !st.enabled || k!==st.token){ res.status(403).json({error:'Kiosk nie je aktivovaný alebo neplatný kľúč'}); return null; }
  return { slug, city:KIOSK_STUDIOS[slug], st, cfg };
}
// Séria: po sebe idúce týždne s aspoň 1 absolvovanou hodinou
function weekKey(d){ const x=new Date(d+'T12:00:00'); const day=(x.getDay()+6)%7; x.setDate(x.getDate()-day); return x.toISOString().slice(0,10); }
async function visitStreakWeeks(userId){
  const bks=(await q.find(db.bookings,{user_id:userId, status:'attended'})).map(b=>b.booking_date||(b.created_at||'').slice(0,10)).filter(Boolean);
  const weeks=new Set(bks.map(weekKey));
  let streak=0; let cur=weekKey(today());
  while(weeks.has(cur) && streak<99){ streak++; const d=new Date(cur+'T12:00:00'); d.setDate(d.getDate()-7); cur=d.toISOString().slice(0,10); }
  return streak;
}

// ═══════════════════════════════════════════════════════════════════════════════
// DOCHÁDZKA: attendance_status — pravda o tom, kto naozaj prišiel
// ═══════════════════════════════════════════════════════════════════════════════
// `status` (confirmed/attended/cancelled) riadi rezerváciu a kapacitu, preto doň
// no_show NEPRIDÁVAME — polovica kódu filtruje na status:'confirmed'. Účasť má
// vlastné pole, takže sa dá opraviť bez dopadu na rezervačnú logiku.
//   pending  — termín ešte nebol / nevieme
//   attended — potvrdená účasť (QR, tréner, online)
//   no_show  — termín prebehol a neprišla
//   unknown  — historické dáta spred zavedenia (NIE no_show, nemáme dôkaz)
const ATT_SOURCES = ['qr','trainer','admin','online_auto','auto'];
// Server beží v UTC, hodiny sú v SK čase — bez toho by sa no-show označoval o hodinu-dve vedľa.
function skOffsetMs(dateStr){
  const d = new Date(dateStr + 'T12:00:00Z');
  const sk = new Date(d.toLocaleString('en-US',{timeZone:'Europe/Bratislava'}));
  const utc = new Date(d.toLocaleString('en-US',{timeZone:'UTC'}));
  return sk.getTime() - utc.getTime();
}
function skDateTimeMs(dateStr, timeStr){
  if(!/^\d{4}-\d{2}-\d{2}$/.test(dateStr||'') || !/^\d{2}:\d{2}/.test(timeStr||'')) return NaN;
  return Date.parse(`${dateStr}T${timeStr.slice(0,5)}:00Z`) - skOffsetMs(dateStr);
}
// Koniec hodiny: time_end, inak time_start + 60 min. Hodina cez polnoc = ďalší deň.
function classEndMs(booking, cls){
  const start = booking.class_time_start || cls?.time_start;
  const end = cls?.time_end || booking.class_time_end;
  if(!start) return NaN;
  const startMs = skDateTimeMs(booking.booking_date, start);
  if(!end) return startMs + 60*60000;
  let endMs = skDateTimeMs(booking.booking_date, end);
  if(endMs <= startMs) endMs += 24*60*60000;
  return endMs;
}
function attSourceFrom(attended_by){
  const v = String(attended_by||'');
  if(/^kiosk_/.test(v)) return 'qr';
  if(v==='online_auto') return 'online_auto';
  if(/admin_fix|system_retro/.test(v)) return 'admin';
  return v ? 'trainer' : 'admin';
}
// Odkedy sa no-show vôbec vyhodnocuje. Staré 'confirmed' rezervácie nemáme ako
// posúdiť (chýbal QR aj potvrdzovanie) — tie ostanú 'unknown', nie no_show.
let NO_SHOW_FROM = null;
async function noShowFrom(){
  if(NO_SHOW_FROM) return NO_SHOW_FROM;
  const s = await q.one(db.settings,{key:'no_show_from'});
  if(s?.value){ NO_SHOW_FROM = s.value; return NO_SHOW_FROM; }
  NO_SHOW_FROM = today();
  await q.insert(db.settings,{key:'no_show_from', value:NO_SHOW_FROM, at:nowISO()}).catch(()=>{});
  return NO_SHOW_FROM;
}
// Doplní attendance_status tam, kde chýba (staré záznamy aj nové z ciest, ktoré
// ho ešte nenastavujú). Idempotentné — beží pri štarte aj pred no-show jobom.
async function normalizeAttendance(){
  const from = await noShowFrom();
  const rows = await q.find(db.bookings,{attendance_status:{$exists:false}});
  if(!rows.length) return 0;
  const clsCache = {};
  let n = 0;
  for(const b of rows){
    let st, src = null;
    if(b.status==='attended'){ st='attended'; src=attSourceFrom(b.attended_by); }
    else if(b.status==='cancelled'){ st='cancelled'; }
    else {
      if(!(b.class_id in clsCache)) clsCache[b.class_id] = await q.one(db.classes,{_id:b.class_id});
      const endMs = classEndMs(b, clsCache[b.class_id]);
      const ended = Number.isFinite(endMs) ? endMs < Date.now() : String(b.booking_date||'') < today();
      st = !ended ? 'pending' : (String(b.booking_date||'') >= from ? 'pending' : 'unknown');
    }
    await q.update(db.bookings,{_id:b._id},{$set:{attendance_status:st, ...(src?{attendance_source:src}:{})}});
    n++;
  }
  if(n) console.log(`📋 Dochádzka: doplnený attendance_status pri ${n} rezerváciách`);
  return n;
}
// Označí neprítomné. Beží každú hodinu, takže reálne označí 60–120 min po hodine.
async function markNoShows(){
  const from = await noShowFrom();
  await normalizeAttendance();
  const rows = (await q.find(db.bookings,{attendance_status:'pending', status:'confirmed'}))
    .filter(b => String(b.booking_date||'') >= from);
  if(!rows.length) return 0;
  const clsCache = {};
  const now = Date.now();
  let n = 0;
  for(const b of rows){
    if(!(b.class_id in clsCache)) clsCache[b.class_id] = await q.one(db.classes,{_id:b.class_id});
    const endMs = classEndMs(b, clsCache[b.class_id]);
    if(!Number.isFinite(endMs) || now < endMs + 60*60000) continue;
    await q.update(db.bookings,{_id:b._id},{$set:{attendance_status:'no_show', attendance_source:'auto', no_show_at:nowISO()}});
    // počítadlo pre skórovanie leadov v trénerskom paneli
    if(b.user_id && !b.is_child_booking){ const u=await q.one(db.users,{_id:b.user_id});
      if(u) await q.update(db.users,{_id:u._id},{$set:{no_show_count:(u.no_show_count||0)+1}}); }
    n++;
    // Recovery ide notifikáciou v appke, nie mailom — mailový limit je vzácny.
    if(b.user_id && !b.is_child_booking) await q.insert(db.notifications,{user_id:b.user_id, type:'no_show',
      title:'Nezachytili sme ťa na hodine 💛',
      body:`${b.class_name||'Hodina'} ${String(b.booking_date||'').split('-').reverse().join('.')} — ak si sa nestihla pípnuť, napíš trénerke. Inak si vyber náhradný termín, tešíme sa na teba!`,
      read:false, created_at:nowISO()}).catch(()=>{});
  }
  if(n) console.log(`📋 Dochádzka: ${n}× označené ako no-show`);
  return n;
}

// ── Funnel timestampy na klientke ────────────────────────────────────────────
// Sú to len CACHE pre rýchly dashboard — pravdou ostávajú bookings a transakcie.
// Preto sa dajú kedykoľvek prepočítať (rebuildFunnelStamps) a nikdy sa neprepisujú
// smerom nahor (raz nastavený prvý dátum sa nemení).
async function stampFirst(userId, field, when){
  if(!userId || !when) return;
  const u = await q.one(db.users,{_id:userId});
  if(!u) return;
  const cur = u[field];
  if(!cur || String(when) < String(cur)) await q.update(db.users,{_id:userId},{$set:{[field]:when}});
}
async function rebuildFunnelStamps(){
  const users = await q.find(db.users,{is_child:{$ne:true}});
  const bks = await q.find(db.bookings,{});
  const txs = await q.find(db.transactions,{});
  const pays = (await q.find(db.payments,{})).filter(p=>['completed','active'].includes(p.status));
  const first = {};
  const put=(uid,f,v)=>{ if(!uid||!v) return; const o=first[uid]=first[uid]||{}; if(!o[f]||String(v)<String(o[f])) o[f]=v; };
  // Druhá návšteva je vlastný krok: väčšina ľudí neodíde kvôli cene, ale preto,
  // že sa druhýkrát nedostane do sály. Bez tohto kroku nevidno, kde to padá.
  const attDates={};
  for(const b of bks){
    if(!b.user_id || b.status==='cancelled') continue;
    put(b.user_id,'first_booking_at', b.created_at||b.booking_date);
    if(b.status==='attended'){
      put(b.user_id,'first_attended_at', b.attended_at||b.booking_date);
      (attDates[b.user_id]=attDates[b.user_id]||[]).push(b.attended_at||b.booking_date);
    }
  }
  for(const [uid,list] of Object.entries(attDates)){
    if(list.length<2) continue;
    const sorted=list.map(String).sort();
    put(uid,'second_attended_at', sorted[1]);
  }
  for(const t of txs){ if((+t.amount||0)>0) put(t.user_id,'first_paid_at', t.created_at||t.date); }
  for(const p of pays){ if((+p.amount||0)>0) put(p.user_id,'first_paid_at', p.captured_at||p.activated_at||p.created_at); }
  // Prvé PLATENÉ členstvo — permanentka ani jednorazový vstup sa sem nerátajú
  for(const m of await q.find(db.memberships,{})){
    const plan=MEMBERSHIP_PLANS[m.plan_id];
    if(plan && plan.type==='bundle') continue;
    if(!(+m.price>0 || m.payment_method)) continue;
    put(m.user_id,'first_membership_at', m.started_at||m.start_date||m.created_at);
  }
  let n=0;
  for(const u of users){
    const f = first[u._id] || {};
    const set = {};
    for(const k of ['first_booking_at','first_attended_at','second_attended_at','first_paid_at','first_membership_at'])
      if(f[k] && u[k]!==f[k]) set[k]=f[k];
    if(Object.keys(set).length){ await q.update(db.users,{_id:u._id},{$set:set}); n++; }
  }
  if(n) console.log(`📊 Funnel: prepočítané timestampy pri ${n} klientkach`);
  return n;
}

// Obsah pre kiosk (slideshow dáta) — token-auth, žiadne osobné citlivé údaje
app.get('/api/kiosk/content', async(req,res)=>{
  try{
    const a=await kioskAuth(req,res); if(!a) return;
    const {city, st}=a;
    const todayS=today(); const dow=new Date().getDay();
    const nowHM=new Date().toTimeString().slice(0,5);
    // Dnešný program v tomto meste
    const classes=(await q.find(db.classes,{active:true}))
      .filter(c=>c.day_of_week===dow && (c.location||'').toLowerCase().includes(city.toLowerCase().split(' ')[0].toLowerCase()));
    const program=[];
    let running=null, next=null;
    for(const c of classes.sort((x,y)=>(x.time_start||'').localeCompare(y.time_start||''))){
      const booked=await q.count(db.bookings,{class_id:c._id, booking_date:todayS, status:{$in:['confirmed','attended']}});
      const item={ name:c.name, emoji:c.emoji||'💃', time_start:c.time_start, time_end:c.time_end, booked, capacity:c.capacity||30, instructor:c.instructor||'' };
      program.push(item);
      if(c.time_start<=nowHM && nowHM<(c.time_end||'23:59')) running=item;
      else if(c.time_start>nowHM && !next) next=item;
    }
    // Štatistiky
    const allB=await q.find(db.bookings,{});
    const todayAtt=allB.filter(b=>b.booking_date===todayS && b.status==='attended').length;
    const mon=new Date(); mon.setDate(mon.getDate()-((mon.getDay()+6)%7)); const monS=mon.toISOString().slice(0,10);
    const weekAtt=allB.filter(b=>(b.booking_date||'')>=monS && ['attended','confirmed'].includes(b.status)).length;
    const totalAtt=allB.filter(b=>b.status==='attended').length;
    // Klient mesiaca + narodeniny (mená sú verejné v komunite; kiosk je v štúdiu)
    let spotlight=null, bdays=[];
    try{
      const monthStr=todayS.slice(0,7);
      const users=(await q.find(db.users,{is_admin:{$ne:true}})).filter(u=>u.user_type!=='trainer'&&!u.is_child&&!u.anonymous&&!(u.imported&&!u.claimed));
      const mmdd=todayS.slice(5);
      bdays=users.filter(u=>(u.birthday||'').slice(5)===mmdd).map(u=>({name:u.name, av:!!u.avatar, id:u._id}));
      const att={}; allB.forEach(b=>{ if((b.booking_date||'').startsWith(monthStr)&&['attended','confirmed'].includes(b.status)&&b.user_id) att[b.user_id]=(att[b.user_id]||0)+1; });
      const top=Object.entries(att).sort((a,b)=>b[1]-a[1]).slice(0,3).map(([id,n])=>{ const u=users.find(x=>x._id===id); return u?{name:u.name, visits:n, av:!!u.avatar, id}:null; }).filter(Boolean);
      spotlight=top;
    }catch(e){}
    // Málo obsadené dnešné hodiny (promo)
    const promoClass=program.filter(p=>!running||p!==running).sort((x,y)=>(x.booked/x.capacity)-(y.booked/y.capacity))[0]||null;
    // Nadchádzajúce eventy a masterclassy — pozvánka na kiosku (reálne dáta z ev_events)
    const APP_BASE=String(APP_URL||"").replace(/[/]+$/,"");
    let events=[];
    try{
      events=(await q.find(db.ev_events,{}))
        .filter(e=>e.slug && e.name && e.active!==false && (e.date||'')>=todayS)
        .sort((a,b)=>String(a.date).localeCompare(String(b.date)))
        .slice(0,3)
        .map(e=>({ slug:e.slug, name:e.name, subtitle:e.subtitle||'', date:e.date,
                   date_label:e.date_label||'', venue:e.venue||'', address:e.address||'',
                   url: APP_BASE + '/event/' + e.slug, types:e.types||[] }));
      // Ku každému typu vstupenky doplň reálnu cenu a zostávajúce miesta
      for(const ev of events){
        const tickets=await q.find(db.ev_tickets,{event_slug:ev.slug});
        ev.types=(ev.types||[]).map(t=>{
          const sold=tickets.filter(x=>x.type===t.key && x.status!=='void').length;
          const left=(t.capacity==null)?null:Math.max(0,t.capacity-sold);
          const presaleOn=!t.presale_until || new Date(t.presale_until)>=new Date();
          return { key:t.key, name:t.name, includes:(t.includes||[]).slice(0,4),
                   presale:t.presale, door:t.door, member:t.member,
                   presale_on:presaleOn, left, sold_out: left!=null && left<=0 };
        });
      }
    }catch(e){}
    res.json({ ok:true, city, now:nowHM,
      config:{ interval_s:st.interval_s||12, idle_s:st.idle_s||15, night_off:st.night_off||'21:30', night_on:st.night_on||'07:30', widgets:st.widgets||KIOSK_DEFAULT_WIDGETS, announcement:st.announcement||'', custom_slides:st.custom_slides||[] },
      program, running, next,
      stats:{ today:todayAtt, week:weekAtt, total:totalAtt },
      spotlight, birthdays:bdays,
      promo_class:promoClass,
      events,
      app_url:APP_URL });
  }catch(e){ res.status(500).json({error:e.message}); }
});

// QR check-in z kiosku: nájde bežiacu/najbližšiu dnešnú hodinu v meste a zapíše účasť
app.post('/api/kiosk/checkin', async(req,res)=>{
  try{
    const a=await kioskAuth(req,res); if(!a) return;
    const {city}=a;
    const qr=String(req.body.qr_data||'');
    const userId = qr.startsWith('FA:') ? qr.slice(3) : qr;
    const u=await q.one(db.users,{_id:userId});
    if(!u) return res.status(404).json({error:'Neplatný QR kód — skús to znova alebo sa ozvi trénerovi.'});
    // Cieľová hodina: beží práve teraz (±15 min pred začiatkom), inak najbližšia dnešná do 90 min
    const todayS=today(); const dow=new Date().getDay(); const nowMin=(d=>d.getHours()*60+d.getMinutes())(new Date());
    const toMin=t=>{ const [h,m]=String(t||'0:0').split(':').map(Number); return h*60+m; };
    const classes=(await q.find(db.classes,{active:true, day_of_week:dow}))
      .filter(c=>(c.location||'').toLowerCase().includes(city.toLowerCase().split(' ')[0].toLowerCase()))
      .sort((x,y)=>(x.time_start||'').localeCompare(y.time_start||''));
    // Kandidáti: hodina, ktorá práve beží (15 min pred až 15 min po konci) + najbližšia
    // do 90 min. Ak sedí viac hodín (napr. technika 18:00 + Zumba 19:00), kiosk sa PÝTA —
    // predtým bral prvú a ženy prichádzajúce na Zumbu končili zapísané na technike.
    const endOf=c=>{ const e=toMin(c.time_end); const st=toMin(c.time_start); return e>st?e:st+60; };
    const cands=classes.filter(c=>(nowMin>=toMin(c.time_start)-15 && nowMin<endOf(c)+15)
      || (toMin(c.time_start)>nowMin && toMin(c.time_start)-nowMin<=90));
    if(!cands.length) return res.status(400).json({error:'Dnes tu už nie je žiadna hodina na check-in.'});
    let cls;
    const pick=String(req.body.class_id||'');
    if(pick) cls=cands.find(c=>c._id===pick);
    if(!cls){
      // Rezervácia rozhoduje: kiosk uprednostní hodinu, na ktorú je prihlásená
      const myBks=await q.find(db.bookings,{user_id:u._id, booking_date:todayS, status:{$ne:'cancelled'}});
      const booked=cands.filter(c=>myBks.some(b=>b.class_id===c._id));
      if(booked.length===1) cls=booked[0];
    }
    if(!cls && cands.length===1) cls=cands[0];
    if(!cls){
      return res.json({ ok:true, choose:true, first:(u.name||'').split(' ')[0],
        options:cands.map(c=>({id:c._id, name:c.name, emoji:c.emoji||'💃', time_start:c.time_start, time_end:c.time_end||''})) });
    }
    // Zapíš účasť (rovnaká logika ako trénerský QR check-in)
    const exists=await q.one(db.bookings,{class_id:cls._id, user_id:u._id, booking_date:todayS, status:{$ne:'cancelled'}});
    let already=false, vc=u.visit_count||0;
    if(exists){
      already = exists.status==='attended';
      // Prišla neskôr, než job stihol označiť no-show? QR má prednosť — opravíme to.
      const fix = exists.attendance_status==='no_show' ? {no_show_corrected_at:nowISO(), no_show_corrected_by:'kiosk_'+a.slug} : {};
      if(exists.attendance_status==='no_show' && (u.no_show_count||0)>0)
        await q.update(db.users,{_id:u._id},{$set:{no_show_count:Math.max(0,(u.no_show_count||0)-1)}});
      await q.update(db.bookings,{_id:exists._id},{$set:{status:'attended', attended_at:nowISO(), attended_by:'kiosk_'+a.slug,
        attendance_status:'attended', attendance_source:'qr', ...fix}});
      if(!already && !exists.is_child_booking) vc=await creditAttendance(u);
    } else {
      const mem=await checkMembership(u._id);
      // Online-only plán nekryje živú hodinu — kiosk musí upozorniť, že treba vybrať vstupné
      const onlineOnly=mem&&/online/.test(String((mem.plan_id||'')+' '+(mem.plan_name||'')).toLowerCase());
      const hasMem=mem&&mem.status==='active'&&!onlineOnly, hasFree=!u.free_class_used, hasSingle=(u.single_entries||0)>0, hasCredit=(u.free_credits||0)>0;
      if(!hasMem&&!hasFree&&!hasSingle&&!hasCredit) return res.status(402).json({error:(onlineOnly?'Máš len ONLINE členstvo — živú hodinu nekryje. ':'Nemáš aktívne členstvo ani vstup — ')+'ozvi sa prosím trénerovi na hodine. 💛', name:u.name});
      const upd={};
      if(!hasMem){ if(hasFree) upd.free_class_used=true; else if(hasCredit) upd.free_credits=(u.free_credits||0)-1; else if(hasSingle) upd.single_entries=(u.single_entries||0)-1; }
      if(Object.keys(upd).length) await q.update(db.users,{_id:u._id},{$set:upd});
      await q.insert(db.bookings,{ class_id:cls._id, class_name:cls.name, class_emoji:cls.emoji||'💃',
        free_class: !hasMem&&hasFree,
        class_location:cls.location, class_time_start:cls.time_start, day_of_week:cls.day_of_week, day_name:DAYS_SK[cls.day_of_week],
        user_id:u._id, user_name:u.name, user_email:u.email, user_phone:u.phone||'',
        booking_date:todayS, status:'attended', attended_at:nowISO(), attended_by:'kiosk_'+a.slug,
        attendance_status:'attended', attendance_source:'qr', notes:'kiosk', created_at:nowISO() });
      vc=await creditAttendance(u);
    }
    const streak=await visitStreakWeeks(u._id);
    const birthdayToday=(u.birthday||'').slice(5)===todayS.slice(5);
    res.json({ ok:true, already,
      user:{ id:u._id, name:u.name, first:(u.name||'').split(' ')[0], av:!!u.avatar, visit_count:vc,
        points_gain:5, streak_weeks:streak, birthday:birthdayToday },
      class_name:cls.name });
  }catch(e){ res.status(500).json({error:e.message}); }
});

