// ═══════════════════════════════════════════════════════════════════════════════
// SÚKROMNÉ HODINY — kalendár trénera, booking klienta, 24h storno, účtovanie
// ═══════════════════════════════════════════════════════════════════════════════
const PRIVATE_DEFAULT_RATE = 25;   // €/hodina, admin mení per tréner
const PRIVATE_DEFAULT_SPLIT = 70;  // % z ceny ide trénerovi
function privateSettings(u){
  return { enabled: !!u.private_enabled,
    rate: +u.private_rate>0 ? +u.private_rate : PRIVATE_DEFAULT_RATE,
    split: (u.private_split>=0 && u.private_split<=100) ? +u.private_split : PRIVATE_DEFAULT_SPLIT };
}
function privSlotStartMs(s){ return new Date(`${s.date}T${s.time_start||'00:00'}:00`).getTime(); }
// Zľava na súkromné hodiny podľa aktívneho členstva: Bronze −10 %, Silver −20 %, Gold −30 %
const PRIVATE_MEMBER_DISCOUNT = { bronze:10, silver:20, gold:30 };
async function privateDiscountFor(userId){
  const m = await checkMembership(userId);
  if(!m || m.status!=='active') return { pct:0, plan:null };
  const pct = PRIVATE_MEMBER_DISCOUNT[m.plan_id] || 0;
  return { pct, plan: pct ? (m.plan_name||m.plan_id) : null };
}
function privDiscounted(price, pct){ return +((+price||0)*(1-(pct||0)/100)).toFixed(2); }
// Zárobok trénera zo súkromných hodín za mesiac: podiel z absolvovaných + prepadnuté storná
async function privateEarningsFor(trainerId, month){
  const bks = await q.find(db.private_bookings,{trainer_id:trainerId});
  let sum=0, count=0;
  for(const b of bks){
    if(!String(b.date||'').startsWith(month)) continue;
    if(b.status==='completed'){ sum += (+b.price||0)*((+b.split||PRIVATE_DEFAULT_SPLIT)/100); count++; }
    else if(b.status==='cancelled_late'){ sum += (+b.price||0); } // neskoré storno prepadá celé trénerovi
  }
  return { amount:+sum.toFixed(2), count };
}

// ── Tréner: moje nastavenia + sloty ──────────────────────────────────────────
app.get('/api/trainer/private', trainerAuth, async(req,res)=>{
  try{
    let t=req.trainerUser;
    if(req.query.trainer_id && req.trainerUser.is_admin){ const tu=await q.one(db.users,{_id:req.query.trainer_id}); if(tu) t=tu; }
    const slots=(await q.find(db.private_slots,{trainer_id:t._id, status:{$ne:'cancelled'}})).filter(s=>s.date>=today()).sort((a,b)=>(a.date+a.time_start).localeCompare(b.date+b.time_start));
    const bookings=await q.find(db.private_bookings,{trainer_id:t._id});
    const bkBySlot=Object.fromEntries(bookings.map(b=>[b.slot_id,b]));
    const out=slots.map(s=>{ const b=bkBySlot[s._id];
      return { id:s._id, date:s.date, time_start:s.time_start, duration_min:s.duration_min||60, city:s.city, location:s.location||'', price:s.price, status:s.status,
        booking: (b&&['booked','completed','cancelled_late'].includes(b.status)) ? { id:b._id, client_id:b.client_id, client_name:b.client_name, client_phone:b.client_phone||'', pay_method:b.pay_method, paid:!!b.paid, status:b.status } : null };
    });
    const m=today().slice(0,7);
    const earn=await privateEarningsFor(t._id, m);
    const DAYS_W=['Nedeľa','Pondelok','Utorok','Streda','Štvrtok','Piatok','Sobota'];
    const recurring=(await q.find(db.private_recurring,{trainer_id:t._id, active:{$ne:false}}))
      .map(r=>({id:r._id, weekday:r.weekday, weekday_name:DAYS_W[r.weekday], time_start:r.time_start, duration_min:r.duration_min||60, city:r.city, location:r.location||''}));
    // Ručne zapísané hodiny s neregistrovanými (svadobný tanec a pod.) — tento mesiac
    const guests=bookings.filter(b=>b.manual && String(b.date||'').startsWith(m))
      .sort((a,b)=>(b.date+(b.time_start||'')).localeCompare(a.date+(a.time_start||'')))
      .map(b=>({ id:b._id, date:b.date, time_start:b.time_start||'', duration_min:b.duration_min||60, city:b.city||'',
        name:b.client_name, phone:b.client_phone||'', price:+b.price||0, pay_method:b.pay_method,
        cut:+b.trainer_cut||0, can_delete: b.date===today() }));
    res.json({ ok:true, settings:privateSettings(t), slots:out, recurring, guests, month_earn:earn.amount, month_count:earn.count });
  }catch(e){ res.status(500).json({error:e.message}); }
});

// ── Tréner: RUČNÝ ZÁPIS súkromnej hodiny s neregistrovaným človekom ──────────
// Svadobný tanec, jednorazovky, ľudia bez účtu v appke. Zapíše sa rovno ako
// ABSOLVOVANÁ (nejde cez rezerváciu), meno sa píše ručne. Vznikne tržba, podiel
// trénera aj hotovostná evidencia — návšteva/body/odznaky NIE (nie je komu).
app.post('/api/trainer/private-manual', trainerAuth, async(req,res)=>{
  try{
    const t=req.trainerUser;
    const st=privateSettings(t);
    if(!st.enabled && !t.is_admin) return res.status(403).json({error:'Súkromné hodiny ti musí najprv povoliť admin.'});
    const name=String(req.body.name||'').trim().slice(0,80);
    if(name.length<2) return res.status(400).json({error:'Zadaj meno klienta'});
    const phone=String(req.body.phone||'').trim().slice(0,30);
    const date=/^\d{4}-\d{2}-\d{2}$/.test(req.body.date||'') ? req.body.date : today();
    if(date>today()) return res.status(400).json({error:'Zapisuj len už odučené hodiny (dnes alebo v minulosti)'});
    if(date<'2020-01-01') return res.status(400).json({error:'Neplatný dátum'});
    const time_start=/^\d{2}:\d{2}$/.test(req.body.time_start||'') ? req.body.time_start : '';
    const duration_min=[30,45,60,90,120].includes(+req.body.duration_min) ? +req.body.duration_min : 60;
    const price=+(+req.body.price>=0 ? +req.body.price : st.rate*(duration_min/60)).toFixed(2);
    if(!(price>=0 && price<=1000)) return res.status(400).json({error:'Neplatná cena (0–1000 €)'});
    const pay_method=['cash','transfer','free'].includes(req.body.pay_method) ? req.body.pay_method : 'cash';
    const city=String(req.body.city||'').trim().slice(0,60);
    const note=String(req.body.note||'').trim().slice(0,200);
    const split=+st.split||PRIVATE_DEFAULT_SPLIT;
    const cut=+(price*(split/100)).toFixed(2);
    const bk=await q.insert(db.private_bookings,{ slot_id:null, manual:true, trainer_id:t._id, trainer_name:t.name,
      client_id:null, client_name:name, client_phone:phone, date, time_start, duration_min, city, location:'',
      price, split, pay_method, paid: pay_method!=='transfer', note, status:'completed',
      trainer_cut:cut, completed_at:nowISO(), recorded_by:t._id, created_at:nowISO() });
    // Tržba — hodina zadarmo (napr. ukážková) sa do tržieb neráta
    if(price>0) await q.insert(db.transactions,{type:'private_lesson', amount:price, user_id:null, user_name:name,
      date, method:pay_method, note:`Súkromná hodina (ručne, ${t.name}) ${date}${time_start?' '+time_start:''}${note?' — '+note:''}`,
      recorded_by:t._id, created_at:nowISO()}).catch(()=>{});
    // Hotovosť u trénera → rovnaká automatizácia ako pri predaji na mieste
    if(pay_method==='cash' && price>0){
      await q.insert(db.payouts,{_type:'cash_collected', trainer_id:t._id, trainer_name:t.name, amount:price,
        note:`Súkromná hodina — ${name}`, month:today().slice(0,7), date:today(), status:'held', created_at:nowISO()});
      const admins=await q.find(db.users,{is_admin:true});
      for(const a of admins) await q.insert(db.notifications,{user_id:a._id, type:'cash_collected',
        title:`💵 ${t.name}: súkromná hodina ${price.toFixed(2)} €`,
        body:`${name} (neregistrovaný/á) · ${date.split('-').reverse().join('.')} — hotovosť u trénera.`,
        read:false, created_at:nowISO()}).catch(()=>{});
    }
    await auditLog(req,'private_manual',`${t.name}: súkromná hodina ${name} ${date} (${price.toFixed(2)} €)`,null,{price, pay_method},'');
    res.json({ok:true, id:bk._id, price, trainer_cut:cut});
  }catch(e){ res.status(500).json({error:e.message}); }
});
// Zmazať ručný zápis — len vlastný a len dnešný (preklep), rovnako ako pri hotovosti
app.delete('/api/trainer/private-manual/:id', trainerAuth, async(req,res)=>{
  try{
    const b=await q.one(db.private_bookings,{_id:req.params.id, manual:true});
    if(!b || (b.trainer_id!==req.trainerUser._id && !req.trainerUser.is_admin)) return res.status(404).json({error:'Nenájdené'});
    if(b.date!==today()) return res.status(400).json({error:'Zmazať sa dá len dnešný zápis — starší nechaj opraviť admina'});
    await q.remove(db.private_bookings,{_id:b._id},{});
    await q.remove(db.transactions,{type:'private_lesson', user_id:null, user_name:b.client_name, date:b.date, recorded_by:b.trainer_id},{});
    if(b.pay_method==='cash' && +b.price>0)
      await q.remove(db.payouts,{_type:'cash_collected', trainer_id:b.trainer_id, date:b.date, amount:+b.price, status:'held', note:`Súkromná hodina — ${b.client_name}`},{});
    await auditLog(req,'private_manual_delete',`${b.trainer_name}: zmazaný zápis ${b.client_name} ${b.date}`,b,null,'');
    res.json({ok:true});
  }catch(e){ res.status(500).json({error:e.message}); }
});

// Materializuj sloty z „navždy" pravidiel na najbližších 28 dní (idempotentné)
async function materializeRecurringSlots(){
  const rules=await q.find(db.private_recurring,{active:{$ne:false}});
  let created=0;
  for(const r of rules){
    const t=await q.one(db.users,{_id:r.trainer_id});
    if(!t || !privateSettings(t).enabled) continue;
    const price=+(privateSettings(t).rate*((r.duration_min||60)/60)).toFixed(2);
    for(let i=0;i<28;i++){
      const d=new Date(Date.now()+i*864e5);
      if(d.getDay()!==r.weekday) continue;
      const ds=d.toISOString().slice(0,10);
      if(ds<today()) continue;
      const dup=await q.one(db.private_slots,{trainer_id:r.trainer_id, date:ds, time_start:r.time_start, status:{$ne:'cancelled'}});
      if(dup) continue;
      await q.insert(db.private_slots,{ trainer_id:r.trainer_id, trainer_name:r.trainer_name, date:ds, time_start:r.time_start,
        duration_min:r.duration_min||60, city:r.city, location:r.location||'', price, status:'open', rule_id:r._id, created_at:nowISO() });
      created++;
    }
  }
  return created;
}

// Tréner/admin: pridať sloty (raz, X týždňov, alebo „navždy" = týždenné pravidlo)
app.post('/api/trainer/private-slots', trainerAuth, async(req,res)=>{
  try{
    let t=req.trainerUser;
    if(req.body.trainer_id && req.trainerUser.is_admin){ const tu=await q.one(db.users,{_id:req.body.trainer_id}); if(tu) t=tu; }
    const st=privateSettings(t);
    if(!st.enabled && !req.trainerUser.is_admin) return res.status(403).json({error:'Súkromné hodiny ti musí najprv povoliť admin (sekcia Súkromné hodiny).'});
    const {date, time_start, city} = req.body;
    const duration_min = [60,90,120].includes(+req.body.duration_min) ? +req.body.duration_min : 60;
    if(!/^\d{4}-\d{2}-\d{2}$/.test(String(date))||!/^\d{2}:\d{2}$/.test(String(time_start))||!city) return res.status(400).json({error:'Chýba dátum, čas alebo mesto'});
    if(date<today()) return res.status(400).json({error:'Dátum je v minulosti'});
    // ♾️ „Navždy": ulož týždenné pravidlo (deň v týždni + čas) — termíny sa dopĺňajú automaticky
    if(req.body.repeat_weeks==='forever'){
      const weekday=new Date(date+'T12:00:00').getDay();
      const dupR=await q.one(db.private_recurring,{trainer_id:t._id, weekday, time_start, active:{$ne:false}});
      if(dupR) return res.status(400).json({error:'Také týždenné pravidlo už máš (rovnaký deň a čas).'});
      const rule=await q.insert(db.private_recurring,{ trainer_id:t._id, trainer_name:t.name, weekday, time_start,
        duration_min, city:String(city), location:String(req.body.location||'').slice(0,120), active:true, created_at:nowISO() });
      const created=await materializeRecurringSlots();
      return res.json({ok:true, created, forever:true, rule_id:rule._id});
    }
    const repeat = Math.min(Math.max(+req.body.repeat_weeks||1,1),8);
    const price=+(st.rate*(duration_min/60)).toFixed(2);
    let created=0;
    for(let w=0;w<repeat;w++){
      const d=new Date(date+'T12:00:00'); d.setDate(d.getDate()+7*w);
      const ds=d.toISOString().slice(0,10);
      const dup=await q.one(db.private_slots,{trainer_id:t._id, date:ds, time_start, status:{$ne:'cancelled'}});
      if(dup) continue;
      await q.insert(db.private_slots,{ trainer_id:t._id, trainer_name:t.name, date:ds, time_start,
        duration_min, city:String(city), location:String(req.body.location||'').slice(0,120),
        price, status:'open', created_at:nowISO() });
      created++;
    }
    res.json({ok:true, created});
  }catch(e){ res.status(500).json({error:e.message}); }
});

// Zrušiť „navždy" pravidlo (+ odstráni jeho budúce voľné termíny; rezervované ostávajú)
