app.get('/api/trainer/earnings', trainerAuth, async(req,res)=>{
  try {
    // Zárobky sú OSOBNÉ — vždy pre reálne prihláseného človeka (nie mentora asistenta).
    // Aj asistent, ktorý sám odučí hodinu (nastaví sa ako inštruktor), musí vidieť svoj zárobok.
    let t = req.trainerUser;
    // Admin si vie pozrieť konkrétneho trénera cez ?trainer_id=
    if(req.query.trainer_id && req.trainerUser?.is_admin){
      const tu = await q.one(db.users,{_id:req.query.trainer_id});
      if(tu) t = tu;
    }
    const tName = t.name;
    const rule = await q.one(db.payout_rules,{trainer:tName}) || {...DEFAULT_PAYOUT_RULE};
    const thr = rule.per_client_threshold||0;
    // Posledných 12 mesiacov (UTC — rovnaký základ ako today() a dátumy rezervácií,
    // inak by lokálne časové pásmo mohlo vynechať aktuálny mesiac)
    const months=[]; const ty=+today().slice(0,4), tm=+today().slice(5,7);
    for(let i=0;i<12;i++){ const d=new Date(Date.UTC(ty, tm-1-i, 1)); months.push(d.toISOString().slice(0,7)); }
    // Tipy pre tohto trénera (80 % podiel) — súčet po mesiacoch
    const myTips = await q.find(db.tips,{to_user_id:t._id, status:'paid'});
    const tipByMonth={};
    for(const tp of myTips){ const mm=(tp.month||(tp.created_at||'').slice(0,7)); tipByMonth[mm]=(tipByMonth[mm]||0)+(+tp.trainer_cut||0); }
    const rows=[];
    for(const m of months){
      const st=(await trainerMonthStats(m)).find(s=>s.instructor===tName || (tName&&s.instructor&&s.instructor.includes(tName.split(' ')[0]))) || {sessions:0,attendances:0,revenue:0,newClients:0,fullClasses:0,session_atts:[]};
      const {base,bonuses,billable}=computePayout(rule,st);
      const affiliate = await affiliateCommissionFor(t._id, m);
      const tips = +(tipByMonth[m]||0).toFixed(2);
      const rec=await q.one(db.payouts,{trainer:tName,month:m});
      const ded=rec?.deductions||0;
      const cash=await cashCollectedFor(tName, m); // vybraná hotovosť = zrážka, kým sa neodovzdá
      const priv=await privateEarningsFor(t._id, m);
      const total=+(base+bonuses+affiliate+tips+priv.amount-ded-cash.deduct).toFixed(2);
      const items=[
        {label:'Základ za hodinu', count:st.sessions, per:rule.fixed_per_class||0, amount:+((rule.fixed_per_class||0)*st.sessions).toFixed(2)},
        {label:'🎭 Súkromné hodiny (môj podiel)', count:priv.count, per:'', amount:priv.amount},
        {label:(thr>0?`Klienti nad ${thr} na hodine`:'Odmena za účastníka'), count:billable, per:rule.per_client||0, amount:+((rule.per_client||0)*billable).toFixed(2)},
        {label:'Bonus za plnú hodinu', count:st.fullClasses, per:rule.bonus_full_class||0, amount:+((rule.bonus_full_class||0)*st.fullClasses).toFixed(2)},
        {label:'Bonus za nového klienta', count:st.newClients, per:rule.bonus_new_member||0, amount:+((rule.bonus_new_member||0)*st.newClients).toFixed(2)},
        {label:'Affiliate provízie (moja línia)', count:'', per:'', amount:affiliate},
        {label:'💛 Tipy od klientov (80 %)', count:'', per:'', amount:tips},
        {label:'💵 Vybraná hotovosť od klientov (zrážka)', count:'', per:'', amount:-cash.deduct},
      ].filter(x=>x.per||x.amount);
      const paid_total=+((rec?.payments||[]).reduce((s,p)=>s+(+p.amount||0),0) || (rec?.status==='paid'&&!(rec?.payments||[]).length ? total : 0)).toFixed(2);
      rows.push({month:m, sessions:st.sessions, attendances:st.attendances, revenue:+st.revenue.toFixed(2),
        base:+base.toFixed(2), bonuses:+bonuses.toFixed(2), affiliate, tips, private:priv.amount, deductions:ded,
        cash_deduct:cash.deduct, cash_pending:cash.pending, total,
        paid_total, outstanding:+Math.max(0,total-paid_total).toFixed(2), payments:rec?.payments||[],
        status: rec?.status||'draft', paid: rec?.status==='paid', payment_method: rec?.payment_method||null, paid_at: rec?.paid_at||null, items});
    }
    const grand=rows.reduce((s,r)=>s+r.total,0);
    const grandAffiliate=rows.reduce((s,r)=>s+r.affiliate,0);
    const grandTips=rows.reduce((s,r)=>s+(r.tips||0),0);
    res.json({ trainer:tName, trainer_id:t._id, months:rows, grand_total:+grand.toFixed(2), grand_affiliate:+grandAffiliate.toFixed(2), grand_tips:+grandTips.toFixed(2) });
  } catch(e){ res.status(500).json({error:e.message}); }
});

// ═══════════════════════════════════════════════════════════════════════════════
// DENNÉ ÚLOHY TRÉNEROV (marketing) — bodovanie, mesačný súhrn, cena, história
// ═══════════════════════════════════════════════════════════════════════════════
// Body podľa náročnosti: video najviac, správa najmenej.
const TRAINER_TASKS = [
  { key:'video',   label:'Video / Reel',           icon:'🎬', points:10, hint:'Krátke video o hodinách, zumbe, atmosfére' },
  { key:'karusel', label:'Karusel (viac fotiek)',  icon:'🖼️', points:7,  hint:'Album/karusel na Instagrame alebo FB' },
  { key:'foto',    label:'Fotka / príspevok',       icon:'📸', points:5,  hint:'Fotka z hodiny, motivačný príspevok' },
  { key:'story',   label:'Story + zdieľať odkaz',   icon:'📲', points:3,  hint:'Story s odkazom na appku / registráciu' },
  { key:'sprava',  label:'Napísať / osloviť ľudí',  icon:'✍️', points:2,  hint:'DM alebo osloviť potenciálnych klientov' },
];
const TASK_POINTS = Object.fromEntries(TRAINER_TASKS.map(t=>[t.key,t.points]));
async function taskPrizeFor(month){ const s=await q.one(db.settings,{key:'trainer_task_prizes'}); return (s?.value && s.value[month]) || ''; }
async function taskLeaderboard(month){
  const logs = await q.find(db.task_logs,{month});
  const by={};
  logs.forEach(l=>{ const b=by[l.user_id]=by[l.user_id]||{user_id:l.user_id,name:l.user_name,points:0,days:new Set(),counts:{},hours:0};
    b.days.add(l.date);
    if(l.task_key==='hours'){ b.hours+=(+l.hours||0); }
    else { b.points+=(l.points||0); b.counts[l.task_key]=(b.counts[l.task_key]||0)+(+l.count||1); } });
  return Object.values(by).map(b=>({user_id:b.user_id,name:b.name,points:b.points,active_days:b.days.size,counts:b.counts,hours:+b.hours.toFixed(1)}))
    .sort((a,b)=>b.points-a.points);
}
// Tréner: moje úlohy, dnešné počty, mesačný súhrn, cena, poradie, tímová tabuľka
app.get('/api/tasks/my', trainerAuth, async(req,res)=>{
  try {
    const u=req.trainerUser;
    const month=(req.query.month||today().slice(0,7)).slice(0,7);
    const day=today();
    const logs=await q.find(db.task_logs,{user_id:u._id, month});
    const todayCounts={}; let todayHours=0;
    logs.filter(l=>l.date===day).forEach(l=>{ if(l.task_key==='hours') todayHours+=(+l.hours||0); else todayCounts[l.task_key]=(todayCounts[l.task_key]||0)+(+l.count||1); });
    const total=logs.filter(l=>l.task_key!=='hours').reduce((s,l)=>s+(l.points||0),0);
    const monthHours=logs.filter(l=>l.task_key==='hours').reduce((s,l)=>s+(+l.hours||0),0);
    const activeDays=new Set(logs.map(l=>l.date)).size;
    const board=await taskLeaderboard(month);
    const rank=board.findIndex(r=>r.user_id===u._id);
    res.json({ tasks:TRAINER_TASKS, month, day, today_counts:todayCounts, today_hours:todayHours,
      total_points:total, month_hours:+monthHours.toFixed(1), active_days:activeDays,
      prize:await taskPrizeFor(month), my_rank: rank>=0?rank+1:null, board });
  } catch(e){ res.status(500).json({error:e.message}); }
});
// Deň (default dnes, nie budúcnosť)
function taskDayOf(req){
  let d=String(req.body.date||req.query.date||'');
  if(!/^\d{4}-\d{2}-\d{2}$/.test(d)) return today();
  // Povoľ aj „zajtra" v UTC — klient počíta „dnes" v lokálnom čase (napr. CEST +2h),
  // takže bez tejto tolerancie by sa lokálne dnes zrazilo na UTC-dnes a dni by sa zlievali.
  const maxD=new Date(Date.now()+36*3600e3).toISOString().slice(0,10);
  if(d>maxD) d=today();
  return d;
}
// Tímový rozpis za konkrétny deň
async function taskDayBoard(date){
  const logs = await q.find(db.task_logs,{date});
  const by={};
  logs.forEach(l=>{ const b=by[l.user_id]=by[l.user_id]||{user_id:l.user_id,name:l.user_name,points:0,counts:{},hours:0};
    if(l.task_key==='hours') b.hours+=(+l.hours||0);
    else { b.points+=(l.points||0); b.counts[l.task_key]=(b.counts[l.task_key]||0)+(+l.count||1); } });
  return Object.values(by).map(b=>({...b,hours:+b.hours.toFixed(1)})).sort((a,b)=>b.points-a.points);
}
// Tréner: nastav počet danej aktivity na deň (0 = zmazať). Body = počet × sadzba.
app.post('/api/tasks/set', trainerAuth, async(req,res)=>{
  try {
    const u=req.trainerUser;
    const key=String(req.body.task_key||'');
    if(!TASK_POINTS[key]) return res.status(400).json({error:'Neznáma úloha'});
    const count=Math.max(0,Math.min(99, parseInt(req.body.count)||0));
    const day=taskDayOf(req); const month=day.slice(0,7);
    const ex=await q.one(db.task_logs,{user_id:u._id, date:day, task_key:key});
    if(count<=0){ if(ex) await q.remove(db.task_logs,{_id:ex._id},{}); return res.json({ok:true,count:0,points:0}); }
    const points=count*TASK_POINTS[key];
    if(ex) await q.update(db.task_logs,{_id:ex._id},{$set:{count,points}});
    else await q.insert(db.task_logs,{ user_id:u._id, user_name:u.name, task_key:key, count, points, date:day, month, created_at:nowISO() });
    res.json({ ok:true, count, points });
  } catch(e){ res.status(500).json({error:e.message}); }
});
// Tréner: koľko hodín dnes odpracoval (informatívne, sčítava sa v mesiaci)
app.post('/api/tasks/hours', trainerAuth, async(req,res)=>{
  try {
    const u=req.trainerUser;
    const hours=Math.max(0,Math.min(24, parseFloat(req.body.hours)||0));
    const day=taskDayOf(req); const month=day.slice(0,7);
    const ex=await q.one(db.task_logs,{user_id:u._id, date:day, task_key:'hours'});
    if(hours<=0){ if(ex) await q.remove(db.task_logs,{_id:ex._id},{}); return res.json({ok:true,hours:0}); }
    if(ex) await q.update(db.task_logs,{_id:ex._id},{$set:{hours}});
    else await q.insert(db.task_logs,{ user_id:u._id, user_name:u.name, task_key:'hours', hours, points:0, count:0, date:day, month, created_at:nowISO() });
    res.json({ ok:true, hours });
  } catch(e){ res.status(500).json({error:e.message}); }
});
// Tréner: rozpis za konkrétny deň (moje počty + čo spravili iní tréneri v ten deň)
app.get('/api/tasks/day', trainerAuth, async(req,res)=>{
  try {
    const u=req.trainerUser;
    const date=taskDayOf(req);
    const mine=await q.find(db.task_logs,{user_id:u._id, date});
    const myCounts={}; let myHours=0;
    mine.forEach(l=>{ if(l.task_key==='hours') myHours+=(+l.hours||0); else myCounts[l.task_key]=(myCounts[l.task_key]||0)+(+l.count||1); });
    res.json({ tasks:TRAINER_TASKS, date, is_today:date===today(),
      my_counts:myCounts, my_hours:myHours, team:await taskDayBoard(date) });
  } catch(e){ res.status(500).json({error:e.message}); }
});
// Tréner/admin: rebríček za konkrétny mesiac (+ cena, víťaz ak už ukončený)
app.get('/api/tasks/board', trainerAuth, async(req,res)=>{
  try {
    const month=(req.query.month||today().slice(0,7)).slice(0,7);
    const board=await taskLeaderboard(month);
    const cur=today().slice(0,7);
    res.json({ month, tasks:TRAINER_TASKS, board, prize:await taskPrizeFor(month),
      ongoing: month===cur, winner: (month<cur ? (board[0]||null) : null) });
  } catch(e){ res.status(500).json({error:e.message}); }
});
// Tréner/admin: história (víťazi + ceny minulých mesiacov)
app.get('/api/tasks/history', trainerAuth, async(req,res)=>{
  try {
    const logs=await q.find(db.task_logs,{});
    const prizes=(await q.one(db.settings,{key:'trainer_task_prizes'}))?.value||{};
    const months=[...new Set(logs.map(l=>l.month))].sort().reverse();
    const cur=today().slice(0,7);
    const out=[];
    for(const m of months){
      const board=await taskLeaderboard(m);
      out.push({ month:m, ongoing:m===cur, prize:prizes[m]||'', winner:(m<cur?board[0]||null:null), top3:board.slice(0,3) });
    }
    res.json({ months:out });
  } catch(e){ res.status(500).json({error:e.message}); }
});
// Admin: detailný prehľad všetkých trénerov za mesiac
app.get('/api/tasks/admin/overview', adminAuth, async(req,res)=>{
  try {
    const month=(req.query.month||today().slice(0,7)).slice(0,7);
    const rows=await taskLeaderboard(month);
    // doplň trénerov s 0 bodmi
    const trainers=(await q.find(db.users,{})).filter(x=>x.is_admin||x.user_type==='trainer'||x.user_type==='manager');
    const have=new Set(rows.map(r=>r.user_id));
    trainers.forEach(t=>{ if(!have.has(t._id)) rows.push({user_id:t._id,name:t.name,points:0,active_days:0,counts:{}}); });
    rows.sort((a,b)=>b.points-a.points);
    res.json({ month, tasks:TRAINER_TASKS, rows, prize:await taskPrizeFor(month),
      total_points: rows.reduce((s,r)=>s+r.points,0) });
  } catch(e){ res.status(500).json({error:e.message}); }
});
// Admin: nastav cenu pre mesiac
app.put('/api/tasks/admin/prize', adminAuth, async(req,res)=>{
  try {
    const month=String(req.body.month||today().slice(0,7)).slice(0,7);
    const prize=String(req.body.prize||'').slice(0,200);
    const ex=await q.one(db.settings,{key:'trainer_task_prizes'});
    const map=(ex?.value)||{}; map[month]=prize;
    if(ex) await q.update(db.settings,{key:'trainer_task_prizes'},{$set:{value:map,updated_at:nowISO()}});
    else await q.insert(db.settings,{key:'trainer_task_prizes',value:map,created_at:nowISO()});
    res.json({ ok:true, month, prize });
  } catch(e){ res.status(500).json({error:e.message}); }
});

// ── Asistent trénera ──────────────────────────────────────────────────────────
function canManageAssistant(u){ return u && (u.is_admin || u.user_type==='trainer' || u.user_type==='manager'); }
app.get('/api/trainer/assistant', trainerAuth, async(req,res)=>{
  const t=req.trainerUser;
  const list = await q.find(db.users,{assistant_of:t._id, is_assistant:true});
  const assistants = list.map(a=>({id:a._id,name:a.name,email:a.email,avatar:a.avatar||null}));
  res.json({ assistants, assistant: assistants[0]||null, can_manage: canManageAssistant(t) });
});
app.post('/api/trainer/assistant', trainerAuth, async(req,res)=>{
  try {
    const t=req.trainerUser;
    if(!canManageAssistant(t)) return res.status(403).json({error:'Len tréner môže priradiť asistenta'});
    const uid=String(req.body.user_id||''); if(!uid) return res.status(400).json({error:'Chýba user_id'});
    const target=await q.one(db.users,{_id:uid}); if(!target) return res.status(404).json({error:'Používateľ nenájdený'});
    if(target._id===t._id) return res.status(400).json({error:'Nemôžeš byť svoj asistent'});
    // viacero asistentov je povolených — len pridaj tohto
    await q.update(db.users,{_id:uid},{$set:{is_assistant:true, assistant_of:t._id}});
    await q.insert(db.notifications,{user_id:uid,type:'assistant',title:'🤝 Stal si sa asistentom!',
      body:`${t.name} ťa určil za svojho asistenta. V appke máš teraz prístup do trénerského panela (bookovanie, QR) a nový odznak. 💛`,read:false,created_at:nowISO()}).catch(()=>{});
    await auditLog(req,'set_assistant',uid,{},{trainer:t._id},'');
    res.json({ ok:true });
  } catch(e){ res.status(500).json({error:e.message}); }
});
app.delete('/api/trainer/assistant/:id', trainerAuth, async(req,res)=>{
  try {
    const t=req.trainerUser;
    if(!canManageAssistant(t)) return res.status(403).json({error:'Nemáš oprávnenie'});
    const target=await q.one(db.users,{_id:req.params.id});
    if(target && target.assistant_of===t._id){ await q.update(db.users,{_id:target._id},{$set:{is_assistant:false,assistant_of:null}}); }
    res.json({ ok:true });
  } catch(e){ res.status(500).json({error:e.message}); }
});

// Všetci klienti (pre trénera aj admina) s členstvom/mestom/vstupmi — filtre rieši frontend
app.get('/api/trainer/students', trainerAuth, async(req,res)=>{
  const users = (await q.find(db.users,{active:{$ne:false}, is_admin:{$ne:true}, is_child:{$ne:true}}))
    .filter(u=>(u.user_type||'client')!=='trainer' && !u.anonymous);
  // aktívne členstvá do mapy (rýchle)
  const memMap={};
  (await q.find(db.memberships,{status:'active'})).forEach(m=>{
    if(m.expires_at && m.expires_at<today()) return;
    if(!memMap[m.user_id]) memMap[m.user_id]={plan_id:m.plan_id, name:(MEMBERSHIP_PLANS[m.plan_id]?.name||m.plan_name||'Členstvo')};
  });
  // posledné mesto z rezervácií
  const lastCity={}, lastDate={};
  for(const b of (await q.find(db.bookings,{}))){ if(!b.user_id) continue; const d=b.booking_date||(b.created_at||'').slice(0,10);
    if(!lastDate[b.user_id]||d>lastDate[b.user_id]){ lastDate[b.user_id]=d; if(b.class_location) lastCity[b.user_id]=b.class_location; } }
  const result = users.map(u=>({
    id:u._id, name:u.name, email:u.email, phone:u.phone||'', created_at:u.created_at,
    city: u.city||lastCity[u._id]||'', visit_count:u.visit_count||0,
    single_entries:u.single_entries||0,
    membership: memMap[u._id]?memMap[u._id].name:null, plan_id: memMap[u._id]?memMap[u._id].plan_id:null,
  })).sort((a,b)=>a.name.localeCompare(b.name));
  res.json(result);
});

// Update class stream URL (trainer/admin)
app.put('/api/admin/classes/:id/stream', adminAuth, async(req,res)=>{
  const {stream_url,stream_platform,stream_notes,stream_key} = req.body;
  const $set = {stream_url:stream_url||'',stream_platform:stream_platform||'',stream_notes:stream_notes||''};
  if(stream_key!==undefined) $set.stream_key = String(stream_key||'').replace(/[^a-zA-Z0-9_-]/g,'');
  await q.update(db.classes,{_id:req.params.id},{$set});
  // Jeden večer = jeden prenos: ďalšie aktívne online hodiny z toho istého mesta
  // v ten istý deň dostanú rovnaký link (napr. piatok 18:00 technika + 19:00 Zumba).
  try{
    const cls=await q.one(db.classes,{_id:req.params.id});
    if(cls && cls.category==='Online' && stream_url){
      const siblings=(await q.find(db.classes,{category:'Online', active:true,
        day_of_week:cls.day_of_week}))
        .filter(c=>c._id!==cls._id && (c.stream_city||'')===(cls.stream_city||''));
      for(const sib of siblings)
        await q.update(db.classes,{_id:sib._id},{$set:{stream_url:stream_url||'', stream_platform:stream_platform||''}});
      if(siblings.length) console.log('🌐 Stream link zdieľaný s '+siblings.length+' online hodinou/ami v ten deň');
    }
  }catch(e){}
  res.json({ok:true, stream_key:$set.stream_key});
});

// ═══════════════════════════════════════════════════════════════════════════════
// ATTENDANCE DASHBOARD – Admin + Trainer
// ═══════════════════════════════════════════════════════════════════════════════

// Full schedule with booking counts (admin sees all; trainer sees their own)
app.get('/api/attendance/schedule', trainerAuth, async(req,res)=>{
  try {
    const u = req.trainerUser;
    // Tréner vidí VŠETKY hodiny (aby sa mohol prihlásiť, že učí), nielen svoje.
    const classes = await q.find(db.classes, {active:true});
    const cxls = await q.find(db.class_cancellations,{ date:{$gte:today()} });
    const result = [];
    for(const c of classes){
      // Obsadenosť pre NAJBLIŽŠÍ termín (rovnako ako to vidí klient), nie súčet cez všetky dátumy
      const bdate = sessionDateFor(c);
      const confirmed = await q.count(db.bookings,{class_id:c._id, booking_date:bdate, status:{$in:['confirmed','attended']}});
      const waitlist  = await q.count(db.bookings,{class_id:c._id, booking_date:bdate, status:'waitlist'});
      const si = await sessionInstructor(c, bdate);
      result.push({...c, confirmed, waitlist, next_date:bdate, spotsLeft:Math.max(0,c.capacity-confirmed), dayName:DAYS_SK[c.day_of_week],
        session_instructor:si.instructor, session_instructor_id:si.instructor_id, instructor_overridden:si.overridden,
        cancelled_next: cxls.some(x=>x.class_id===c._id && x.date===bdate),
        viewer_id:u._id, viewer_is_admin:!!u.is_admin });
    }
    result.sort((a,b)=>a.day_of_week-b.day_of_week||a.time_start.localeCompare(b.time_start));
    res.json(result);
  } catch(e){ res.status(500).json({error:e.message}); }
});

// Inštruktor konkrétneho termínu (class_id + date)
app.get('/api/attendance/session-instructor', trainerAuth, async(req,res)=>{
  const cls=await q.one(db.classes,{_id:String(req.query.class_id||'')});
  if(!cls) return res.status(404).json({error:'Hodina nenájdená'});
  const date=/^\d{4}-\d{2}-\d{2}$/.test(req.query.date||'') ? req.query.date : sessionDateFor(cls);
  const si=await sessionInstructor(cls, date);
  res.json({ ...si, date, viewer_id:req.trainerUser._id, viewer_is_admin:!!req.trainerUser.is_admin });
});
// Zoznam trénerov (pre výber inštruktora hodiny)
app.get('/api/attendance/trainers', trainerAuth, async(req,res)=>{
  const list=(await q.find(db.users,{})).filter(u=>u.active!==false && (u.is_admin||u.user_type==='trainer'||u.user_type==='manager'));
  list.sort((a,b)=>(a.name||'').localeCompare(b.name||''));
  res.json(list.map(u=>({id:u._id, name:u.name})));
});

// Nastav/zmeň inštruktora konkrétneho termínu (class_id + date). Platí, kým to niekto nezmení.
// Admin môže priradiť ktoréhokoľvek trénera; tréner môže „prihlásiť sa, že učím" (iba seba).
app.post('/api/attendance/session-instructor', trainerAuth, async(req,res)=>{
  try{
    const u=req.trainerUser;
    const class_id=String(req.body.class_id||'');
    const cls=await q.one(db.classes,{_id:class_id});
    if(!cls) return res.status(404).json({error:'Hodina nenájdená'});
    const date=/^\d{4}-\d{2}-\d{2}$/.test(req.body.date||'') ? req.body.date : sessionDateFor(cls);
    let instructor_id = String(req.body.instructor_id||'');
    if(!instructor_id){
      // Prázdne id: ADMIN = vráť pôvodného trénera; TRÉNER = prihlás sám seba („učím ja")
      if(u.is_admin){
        await q.remove(db.session_instructors,{class_id, date},{multi:true});
        const si=await sessionInstructor(cls, date);
        return res.json({ ok:true, ...si, date });
      }
      instructor_id = u._id;
    }
    // Tréner (nie admin) môže nastaviť len seba
    if(!u.is_admin) instructor_id=u._id;
    const tgt=await q.one(db.users,{_id:instructor_id});
    if(!tgt || !(tgt.is_admin||tgt.user_type==='trainer'||tgt.user_type==='manager'))
      return res.status(400).json({error:'Neplatný tréner'});
    const ex=await q.one(db.session_instructors,{class_id, date});
    const prevInsId = ex?.instructor_id || cls.instructor_id || null; // koho nahradil
    const doc={ class_id, date, instructor_id:tgt._id, instructor_name:tgt.name, set_by:u._id, set_by_name:u.name, set_at:nowISO() };
    if(ex) await q.update(db.session_instructors,{_id:ex._id},{$set:doc});
    else await q.insert(db.session_instructors, doc);
    await auditLog(req,'set_session_instructor',class_id,{date},{instructor:tgt.name},'');
    // Upozorni relevantných ľudí, že hodinu učí (prebral) niekto iný
    if(prevInsId!==tgt._id){
      const dLbl=(date||'').split('-').reverse().join('.');
      const recips=new Set();
      const admins=await q.find(db.users,{is_admin:true}); admins.forEach(a=>recips.add(a._id));
      if(prevInsId) recips.add(prevInsId);          // predošlý tréner
      if(cls.instructor_id) recips.add(cls.instructor_id); // štandardný tréner hodiny
      recips.delete(tgt._id); recips.delete(u._id);  // nie tomu, kto to spravil, ani novému
      const claim = u._id===tgt._id; // tréner sa prihlásil sám
      for(const rid of recips){
        await q.insert(db.notifications,{ user_id:rid, type:'session_instructor', from_id:u._id,
          title: claim ? `🎓 ${tgt.name} preberá hodinu` : `🎓 Zmena trénera hodiny`,
          body: `${cls.name} · ${cls.location} · ${dLbl} — teraz ju učí ${tgt.name}.`,
          read:false, created_at:nowISO() }).catch(()=>{});
      }
    }
    res.json({ ok:true, instructor_id:tgt._id, instructor:tgt.name, overridden:true, date });
  }catch(e){ res.status(500).json({error:e.message}); }
});

// Zruš konkrétnu hodinu (dátum) — upozorni booknutých, vráť kredit z permanentky,
// daj oznam na nástenku, znemožni booknutie, pozvi na najbližšiu hodinu v tom meste.
app.post('/api/attendance/cancel-session', trainerAuth, async(req,res)=>{
  try {
    const { class_id } = req.body;
    let { date, reason } = req.body;
    const cls = await q.one(db.classes,{_id:class_id});
    if(!cls) return res.status(404).json({error:'Hodina nenájdená'});
    date = date || sessionDateFor(cls);
    reason = (reason||'').slice(0,300);
    // Idempotencia
    if(await q.one(db.class_cancellations,{class_id, date}))
      return res.json({ ok:true, already:true });
    await q.insert(db.class_cancellations,{ class_id, date, class_name:cls.name, location:cls.location,
      reason, cancelled_by: req.trainerUser?._id||null, cancelled_by_name: req.trainerUser?.name||'', created_at:nowISO() });

    // Najbližšia iná hodina v tom istom meste (na pozvánku)
    const cityClasses = (await q.find(db.classes,{location:cls.location, active:true})).filter(c=>c._id!==class_id);
    let nextInfo=null, nextBest=null;
    for(const c of cityClasses){
      const d = displayNextDateForDay(c.day_of_week);
      if(await q.one(db.class_cancellations,{class_id:c._id, date:d})) continue; // aj tá zrušená
      if(!nextBest || d < nextBest.date) nextBest = {date:d, c};
    }
    if(nextBest){ nextInfo = { name:nextBest.c.name, date:nextBest.date, time:nextBest.c.time_start, location:nextBest.c.location }; }
    const inviteTxt = nextInfo ? ` Pozývame ťa na najbližšiu hodinu v ${cls.location}: <b>${nextInfo.name}</b> ${nextInfo.date} o ${nextInfo.time}.` : '';

    // Zruš rezervácie + vráť permanentkový vstup + notifikuj
    const bookings = await q.find(db.bookings,{class_id, booking_date:date, status:{$nin:['cancelled','cancelled_studio']}});
    let refunded=0;
    for(const b of bookings){
      // Vráť všetko, čím klientka zaplatila — nielen permanentkový vstup
      let backTxt='';
      const u0 = await q.one(db.users,{_id:b.user_id});
      if(u0){
        if(b.access_method==='single_entry'){
          await q.update(db.users,{_id:u0._id},{$set:{single_entries:(u0.single_entries||0)+1}}); refunded++;
          backTxt=' Tvoj vstup z permanentky sme ti vrátili.';
        } else if(b.access_method==='free_credit'){
          await q.update(db.users,{_id:u0._id},{$set:{free_credits:(u0.free_credits||0)+1}}); refunded++;
          backTxt=' Hodinu zdarma sme ti vrátili.';
        } else if(b.access_method==='free_class' || b.free_class){
          await q.update(db.users,{_id:u0._id},{$set:{free_class_used:false}}); refunded++;
          backTxt=' Prvú hodinu zdarma máš stále k dispozícii.';
        } else if(b.access_method==='parent_single_entry' && b.booked_by){
          const pu=await q.one(db.users,{_id:b.booked_by});
          if(pu){ await q.update(db.users,{_id:pu._id},{$set:{single_entries:(pu.single_entries||0)+1}}); refunded++; backTxt=' Vstup z rodičovskej permanentky sme vrátili.'; }
        } else if(b.access_method==='parent_free_credit' && b.booked_by){
          const pu=await q.one(db.users,{_id:b.booked_by});
          if(pu){ await q.update(db.users,{_id:pu._id},{$set:{free_credits:(pu.free_credits||0)+1}}); refunded++; backTxt=' Hodinu zdarma sme vrátili rodičovi.'; }
        }
      }
      await q.update(db.bookings,{_id:b._id},{$set:{status:'cancelled_studio', cancelled_reason:reason||'Zrušené štúdiom', cancelled_at:nowISO()}});
      const refundNote = backTxt;
      await q.insert(db.notifications,{user_id:b.user_id, type:'class_cancelled',
        title:`❌ Hodina zrušená: ${cls.name}`,
        body:`${cls.name} dňa ${date}${cls.time_start?' o '+cls.time_start:''} v ${cls.location} sa NEKONÁ${reason?' ('+reason+')':''}.${refundNote}${inviteTxt}`,
        read:false, created_at:nowISO() }).catch(()=>{});
      const u = await q.one(db.users,{_id:b.user_id});
      if(u?.email) sendMail(u.email, `Hodina zrušená: ${cls.name} (${date})`,
        emailTemplate('Hodina sa nekoná 😔',
          `<p>Ahoj <b>${u.name}</b>,</p><p>Mrzí nás to — hodina <b>${cls.name}</b> dňa <b>${date}</b>${cls.time_start?' o '+cls.time_start:''} v <b>${cls.location}</b> sa <b>nekoná</b>${reason?` (${reason})`:''}.</p>${b.access_method==='single_entry'?'<p>Tvoj vstup z permanentky sme ti <b>vrátili</b> späť.</p>':''}${nextInfo?`<p>Pozývame ťa na najbližšiu hodinu v ${cls.location}: <b>${nextInfo.name}</b> ${nextInfo.date} o ${nextInfo.time}. 💃</p>`:''}`,
          '🗓️ Pozrieť rozvrh', `${APP_URL}/schedule`)).catch(()=>{});
    }

    // Oznam na nástenku (feed) — vidia všetci členovia
    await q.insert(db.feed,{ author_id:'studio', author_name:'Fusion Academy', author_badge:{emoji:'📢',label:'Oznam'},
      studio_announcement:true, city:cls.location,
      text:`📢 Zrušená hodina — ${cls.location}\n\nHodina „${cls.name}" dňa ${date}${cls.time_start?' o '+cls.time_start:''} sa NEKONÁ${reason?` (${reason})`:''}.${nextInfo?`\n\nNajbližšia hodina v ${cls.location}: ${nextInfo.name} ${nextInfo.date} o ${nextInfo.time}. Tešíme sa na teba! 💃`:''}`,
      image:null, reactions:{}, comments:[], created_at:nowISO() }).catch(()=>{});

    // Online prenos beží z tejto hodiny — ak sa hodina nekoná, nekoná sa ani vysielanie.
    // Zruší sa spárovaná online hodina (rovnaký deň, čas a mesto vysielania).
    let onlineCancelled=null;
    if(cls.category!=='Online' && !req.body.skip_online){
      const pair=(await q.find(db.classes,{category:'Online', active:true, day_of_week:cls.day_of_week}))
        .find(o=>o.time_start===cls.time_start && (o.stream_city||'')===(cls.location||''));
      if(pair && !(await q.one(db.class_cancellations,{class_id:pair._id, date}))){
        await q.insert(db.class_cancellations,{ class_id:pair._id, date, class_name:pair.name, location:'Online',
          reason: reason||`Zrušená hodina v ${cls.location}`, cancelled_by:req.trainerUser?._id||null,
          cancelled_by_name:req.trainerUser?.name||'', auto_from:class_id, created_at:nowISO() });
        const onBk=await q.find(db.bookings,{class_id:pair._id, booking_date:date, status:{$nin:['cancelled','cancelled_studio']}});
        for(const b of onBk){
          await q.update(db.bookings,{_id:b._id},{$set:{status:'cancelled_studio', cancelled_reason:reason||'Zrušené štúdiom', cancelled_at:nowISO()}});
          await q.insert(db.notifications,{user_id:b.user_id, type:'class_cancelled',
            title:'❌ Online hodina zrušená', body:`Online vysielanie ${date}${pair.time_start?' o '+pair.time_start:''} sa NEKONÁ${reason?' ('+reason+')':''} — nekoná sa ani hodina v ${cls.location}, z ktorej vysielame.`,
            read:false, created_at:nowISO()}).catch(()=>{});
        }
        onlineCancelled={id:pair._id, name:pair.name, time:pair.time_start, notified:onBk.length};
      }
    }

    await auditLog(req,'class_cancel',class_id,{},{date, reason, notified:bookings.length, refunded, online:!!onlineCancelled},reason||'');
    res.json({ ok:true, notified:bookings.length, refunded, date, next:nextInfo, online_cancelled:onlineCancelled });
  } catch(e){ res.status(500).json({error:e.message}); }
});
app.get('/api/attendance/cancellations', trainerAuth, async(req,res)=>{
  const list = await q.find(db.class_cancellations,{ date:{$gte:today()} });
  res.json(list);
});

// Attendees for a specific class (optionally filtered to ?date=YYYY-MM-DD)
app.get('/api/attendance/class/:classId', trainerAuth, async(req,res)=>{
  try {
    const query = {class_id:req.params.classId, status:{$in:['confirmed','attended']}};
    // bez explicitného ?date zobraz účastníkov NAJBLIŽŠIEHO termínu (zhodné s počtom pre klienta),
    // ?date=all zobrazí naprieč všetkými termínmi
    if(req.query.date && req.query.date!=='all') query.booking_date = req.query.date;
    else if(!req.query.date){ const cls=await q.one(db.classes,{_id:req.params.classId}); if(cls) query.booking_date = sessionDateFor(cls); }
    const bookings = await q.find(db.bookings, query, {booking_date:-1});
    const result = [];
    for(const b of bookings){
      const u = await q.one(db.users,{_id:b.user_id});
      const m = u ? await checkMembership(u._id) : null;
      result.push({
        booking_id: b._id,
        booking_date: b.booking_date,
        status: b.status,
        attendance_status: b.attendance_status||'pending',
        is_child_booking: !!b.is_child_booking,
        child_name: b.child_name||null,
        booked_by_name: b.booked_by_name||null,
        access_method: b.access_method||null,
        user_id: b.user_id,
        av: !!(u && u.avatar),
        pay_on_site: !!b.pay_on_site,
        pay_amount: b.pay_amount||null,
        entry_collected: b.entry_collected||null,
        name: b.user_name||u?.name||'—',
        email: b.user_email||u?.email||'—',
        phone: b.user_phone||u?.phone||'—',
        visit_count: u?.visit_count||0,
        membership: m ? m.plan_name : null,
        free_class_used: u?.free_class_used||false,
        single_entries: u?.single_entries||0,
        notes: b.notes||'',
        created_at: b.created_at
      });
    }
    res.json(result);
  } catch(e){ res.status(500).json({error:e.message}); }
});

// Manual booking by admin/trainer.
// method: 'membership' (covered by active membership) | 'single_entry' (deduct 1 pass) |
//         'free' (comp / first-free) | undefined (backward-compat, uses is_free)
app.post('/api/attendance/manual-booking', trainerAuth, async(req,res)=>{
  try {
    const {user_id, class_id, booking_date, is_free, note} = req.body;
    let method = req.body.method;
    if(!method) method = is_free ? 'free' : 'membership';
    if(!user_id||!class_id) return res.status(400).json({error:'Chýba user_id alebo class_id'});
    const cls = await q.one(db.classes,{_id:class_id});
    if(!cls) return res.status(404).json({error:'Hodina nenájdená'});
    const u = await q.one(db.users,{_id:user_id});
    if(!u) return res.status(404).json({error:'Používateľ nenájdený'});
    const bdate = booking_date || sessionDateFor(cls);
    const exists = await q.one(db.bookings,{class_id,user_id,booking_date:bdate,status:{$ne:'cancelled'}});
    if(exists) return res.status(400).json({error:'Tento klient je už prihlásený na túto hodinu'});

    // ── Apply the chosen booking method ─────────────────────────────────────────
    const upd = {};
    let methodNote = '';
    if(method==='single_entry'){
      if((u.single_entries||0) <= 0) return res.status(400).json({error:`${u.name} nemá žiadny jednorazový vstup ani permanentku.`});
      upd.single_entries = (u.single_entries||0) - 1;
      methodNote = '🎟️ Jednorazový vstup';
    } else if(method==='free'){
      if((u.free_credits||0) > 0){ upd.free_credits = (u.free_credits||0) - 1; methodNote='🎁 Hodina zadarmo (kredit)'; }
      else { if(!u.free_class_used) upd.free_class_used = true; methodNote = u.free_class_used ? '🎁 Hodina zadarmo (tréner)' : '🎁 Prvá hodina zdarma'; }
    } else { // membership
      methodNote = '🏅 Členstvo';
    }
    upd.visit_count = (u.visit_count||0) + 1;
    if((u.visit_count||0)===0 && !u.is_child){ // 1. odchodená hodina — event_id fca_<uid> dedupne s creditAttendance
      metaCapi('FirstClassAttended',{email:u.email, fbclid:u.fbclid, event_id:'fca_'+u._id}).catch(()=>{});
      stampFirst(u._id, 'first_attended_at', nowISO()).catch(()=>{});
    }
    if(u.winback_sent) upd.winback_sent = false;
    applyLeadTrial(upd, u); // lead → automaticky „Bola na hodine"

    await q.insert(db.bookings,{
      class_id, class_name:cls.name, class_emoji:cls.emoji||'💃',
      class_location:cls.location, class_time_start:cls.time_start, class_time_end:cls.time_end,
      day_of_week:cls.day_of_week, day_name:DAYS_SK[cls.day_of_week],
      user_id:u._id, user_name:u.name, user_email:u.email, user_phone:u.phone||'',
      booking_date:bdate, status:'attended', attended_at:nowISO(), attended_by:req.trainerUser._id, access_method:method,
      free_class: method==='free', // zdarma — nepočíta sa do €/klient bonusu trénera
      notes: note || methodNote,
      manual: true, manual_by: req.trainerUser._id, created_at:nowISO()
    });
    await q.update(db.users,{_id:u._id},{$set:upd});
    await q.insert(db.notifications,{user_id:u._id,type:'booking',title:'Rezervácia potvrdená ✅',body:`${cls.name} – ${bdate} o ${cls.time_start} · ${methodNote}`,read:false,created_at:nowISO()});
    res.json({ok:true, booking_date:bdate, visit_count:upd.visit_count, method, method_note:methodNote, single_entries:upd.single_entries!==undefined?upd.single_entries:(u.single_entries||0)});
  } catch(e){ res.status(500).json({error:e.message}); }
});

// Rich client list for the trainer booking picker: name, city, membership/pass status.
// Filters: ?q= (name/email), ?city=, ?filter=membership|pass|free|none
app.get('/api/attendance/clients', trainerAuth, async(req,res)=>{
  try {
    const { q:query, city, filter } = req.query;
    // Zahrnuté sú aj tréneri/admini — aj oni sa vedia prihlásiť na hodinu ako účastníci.
    let users = await q.find(db.users,{active:{$ne:false}, is_child:{$ne:true}});
    if(query && query.trim().length>=1){ users = rankUserMatches(users, query.trim()); } // bez diakritiky + radenie
    const out = [];
    for(const u of users.slice(0,250)){
      const m = await checkMembership(u._id);
      const active = m && (m.status==='active');
      let uCity = u.city || null;
      if(!uCity){
        const last = (await q.find(db.bookings,{user_id:u._id},{booking_date:-1}))[0];
        uCity = last?.class_location || null;
      }
      out.push({
        id:u._id, name:u.name, phone:u.phone||'', city:uCity||null,
        visit_count:u.visit_count||0,
        membership: active ? m.plan_name : null,
        single_entries: u.single_entries||0,
        free_credits: u.free_credits||0,
        free_class_used: !!u.free_class_used
      });
    }
    let list = out;
    if(filter==='membership') list = list.filter(u=>u.membership);
    else if(filter==='pass') list = list.filter(u=>u.single_entries>0);
    else if(filter==='free') list = list.filter(u=>u.free_credits>0 || !u.free_class_used);
    else if(filter==='none') list = list.filter(u=>!u.membership && u.single_entries<=0 && u.free_credits<=0 && u.free_class_used);
    if(city && city!=='all') list = list.filter(u=>(u.city||'').toLowerCase()===city.toLowerCase());
    list.sort((a,b)=>a.name.localeCompare(b.name));
    res.json(list.slice(0,80));
  } catch(e){ res.status(500).json({error:e.message}); }
});

// Stav klienta pre inteligentné zapísanie na hodinu (členstvo / kredit / nič)
app.get('/api/attendance/client-status', trainerAuth, async(req,res)=>{
  try{
    const u = await q.one(db.users,{_id:req.query.user_id});
    if(!u) return res.status(404).json({error:'Klient nenájdený'});
    const m = await checkMembership(u._id);
    const SUBS=['bronze','silver','gold','kids','online_basic','online_premium'];
    const active = !!(m && m.status==='active');
    const isSub = active && SUBS.includes(m.plan_id);
    res.json({ id:u._id, name:u.name,
      single_entries: u.single_entries||0, free_credits: u.free_credits||0, free_class_used: !!u.free_class_used,
      membership: isSub ? (m.plan_name||MEMBERSHIP_PLANS[m.plan_id]?.name||'Členstvo') : null,
      plan_id: active ? m.plan_id : null,
      expires_at: active ? (m.expires_at||null) : null });
  }catch(e){ res.status(500).json({error:e.message}); }
});
// Record single-entry / permanentka sale for a user (entries = počet vstupov)
app.post('/api/attendance/single-entry', trainerAuth, async(req,res)=>{
  try {
    const {user_id, amount, payment_method, note} = req.body;
    if(!user_id) return res.status(400).json({error:'Chýba user_id'});
    const u = await q.one(db.users,{_id:user_id});
    if(!u) return res.status(404).json({error:'Používateľ nenájdený'});
    const count = Math.max(1, Math.min(50, +req.body.entries||1));
    const price = +(amount!=null ? amount : (count===10?80:count*10));
    const entries = (u.single_entries||0) + count;
    const label = count>1 ? `${count}-vstupová permanentka` : 'Jednorazový vstup';
    await q.update(db.users,{_id:user_id},{$set:{single_entries:entries}});
    await q.insert(db.transactions,{
      type:'single_entry', user_id, user_name:u.name, amount:price, date:today(),
      payment_method:payment_method||'cash', note:note||`${label} (${count}×)`,
      recorded_by:req.trainerUser._id, created_at:nowISO(), month:today().slice(0,7)
    });
    await q.insert(db.notifications,{user_id,type:'payment',title:`${label} zakúpená ✅`,body:`Zostatok: ${entries} vstup(ov)`,read:false,created_at:nowISO()});
    createInvoice({user_id, client_name:u.name, client_email:u.email,
      items:[{desc:label, qty:count, total:price}], total:price,
      method:payment_method==='card'?'Karta na mieste':(payment_method||'Hotovosť')});
    awardPurchaseCommission({buyer_id:user_id, amount:price, product_name:label});
    res.json({ok:true, single_entries:entries, added:count});
  } catch(e){ res.status(500).json({error:e.message}); }
});

// Give a free class to a user (reset free_class_used flag)
app.post('/api/attendance/give-free', trainerAuth, async(req,res)=>{
  try {
    const {user_id, note} = req.body;
    if(!user_id) return res.status(400).json({error:'Chýba user_id'});
    const u = await q.one(db.users,{_id:user_id});
    if(!u) return res.status(404).json({error:'Používateľ nenájdený'});
    // Give one free entry credit (separate from single_entries so it's visible)
    const freeCredits = (u.free_credits||0) + 1;
    await q.update(db.users,{_id:user_id},{$set:{free_credits:freeCredits}});
    await q.insert(db.notifications,{user_id,type:'gift',title:'🎁 Dostali ste hodinu zadarmo!',body:note||'Admin vám pridal bezplatnú hodinu.',read:false,created_at:nowISO()});
    res.json({ok:true, free_credits:freeCredits});
  } catch(e){ res.status(500).json({error:e.message}); }
});

// Record membership sale
app.post('/api/attendance/record-membership', trainerAuth, async(req,res)=>{
  try {
    const {user_id, plan_id, amount, payment_method, note} = req.body;
    if(!user_id||!plan_id) return res.status(400).json({error:'Chýba user_id alebo plan_id'});
    const u = await q.one(db.users,{_id:user_id});
    if(!u) return res.status(404).json({error:'Používateľ nenájdený'});
    const plan = MEMBERSHIP_PLANS[plan_id];
    if(!plan) return res.status(400).json({error:'Neznámy plán'});
    // Create/renew membership — obnova NADVÄZUJE na koniec bežiaceho členstva,
    // aby skorá platba klientku neukrátila (predtým vždy dnes+30).
    const startDate = today();
    const existingMem = await q.one(db.memberships,{user_id, status:'active'});
    const baseExp = (existingMem && existingMem.expires_at && String(existingMem.expires_at).slice(0,10) >= today())
      ? new Date(existingMem.expires_at) : new Date();
    const expires = new Date(baseExp); expires.setDate(expires.getDate()+30);
    const expiresDate = expires.toISOString().slice(0,10);
    await q.insert(db.memberships,{
      user_id, user_name:u.name, plan_id, plan_name:plan.name,
      price:amount||plan.price, payment_method:payment_method||'cash',
      start_date:startDate, expires_at:expiresDate, status:'active',
      recorded_by:req.trainerUser._id, note:note||'', created_at:nowISO()
    });
    await q.insert(db.transactions,{
      type:'membership', user_id, user_name:u.name, amount:amount||plan.price, date:today(),
      payment_method:payment_method||'cash', note:note||`Členstvo ${plan.name}`,
      plan_id, recorded_by:req.trainerUser._id, created_at:nowISO(), month:today().slice(0,7)
    });
    if(u.user_type==='lead') await q.update(db.users,{_id:user_id},{$set:{user_type:'client'}}); // lead → klient
    await q.insert(db.notifications,{user_id,type:'membership',title:`Členstvo ${plan.name} aktivované ✅`,body:`Platné do ${expiresDate}`,read:false,created_at:nowISO()});
    createInvoice({user_id, client_name:u.name, client_email:u.email,
      items:[{desc:`Členstvo ${plan.name}`, qty:1, total:+(amount||plan.price)}], total:+(amount||plan.price),
      method:payment_method==='card'?'Karta na mieste':(payment_method||'Hotovosť')});
    awardPurchaseCommission({buyer_id:user_id, amount:+(amount||plan.price), product_name:`Členstvo ${plan.name}`});
    res.json({ok:true, plan_name:plan.name, expires_at:expiresDate});
  } catch(e){ res.status(500).json({error:e.message}); }
});

// Search users (for manual booking autocomplete)
// Hľadanie bez diakritiky ("Notová" nájde aj "Notova" a naopak) + radenie podľa zhody
function searchNorm(s){ return String(s||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,''); }
function rankUserMatches(users, query){
  const needle = searchNorm(query);
  return users
    .map(u=>{ const n=searchNorm(u.name), e=searchNorm(u.email);
      let score=-1;
      if(n.startsWith(needle)||e.startsWith(needle)) score=0;                       // presný začiatok
      else if(n.split(' ').some(w=>w.startsWith(needle))) score=1;                  // začiatok priezviska
      else if(n.includes(needle)||e.includes(needle)) score=2;                      // hocikde
      return {u, score};
    })
    .filter(x=>x.score>=0)
    .sort((a,b)=>a.score-b.score || searchNorm(a.u.name).localeCompare(searchNorm(b.u.name)))
    .map(x=>x.u);
}
app.get('/api/attendance/search-users', trainerAuth, async(req,res)=>{
  try {
    const {q:query} = req.query;
    if(!query||query.length<2) return res.json([]);
    const all = await q.find(db.users,{active:{$ne:false}});
    const users = rankUserMatches(all, query);
    const parentNames = {};
    const out = [];
    for(const u of users.slice(0,15)){
      let parentName = null;
      if(u.is_child && u.parent_id){
        if(!(u.parent_id in parentNames)){ const p=await q.one(db.users,{_id:u.parent_id}); parentNames[u.parent_id]=p?p.name:null; }
        parentName = parentNames[u.parent_id];
      }
      out.push({id:u._id,name:u.name,email:u.is_child?'(dieťa)':u.email,phone:u.phone||'',visit_count:u.visit_count||0,single_entries:u.single_entries||0,free_credits:u.free_credits||0,is_child:!!u.is_child,parent_name:parentName});
    }
    res.json(out);
  } catch(e){ res.status(500).json({error:e.message}); }
});

// Admin: cancel a booking on behalf of user
app.delete('/api/attendance/booking/:id', trainerAuth, async(req,res)=>{
  try {
    const b = await q.one(db.bookings,{_id:req.params.id});
    if(!b) return res.status(404).json({error:'Rezervácia nenájdená'});
    await q.update(db.bookings,{_id:req.params.id},{$set:{status:'cancelled',cancelled_at:nowISO(),cancelled_by:req.trainerUser._id}});
    if(b.status==='confirmed') await promoteWaitlist(b.class_id, b.booking_date);
    // Vstup vraciame len keď o to admin/tréner výslovne požiada — pri no-show
    // (klientka sa prihlásila a neprišla) musí vstup prepadnúť.
    let vratene='';
    const chceVratit = req.body?.refund===true || req.body?.refund==='1' || req.query?.refund==='1';
    if(chceVratit && b.status==='confirmed') vratene = await refundBookingAccess(b);
    sendBookingCancelEmail(b, true).catch(()=>{});
    res.json({ok:true, refunded:!!vratene, refund_note:vratene||null});
  } catch(e){ res.status(500).json({error:e.message}); }
});

// Pripíše ABSOLVOVANÚ hodinu klientovi: +1 návšteva, míľnik/odznaky, uvítací e-mail po 1. hodine.
// Volá sa až keď tréner POTVRDÍ účasť (QR alebo „potvrdiť hodinu"). Vstupy sa NEdedukujú
// (tie sa strhli už pri rezervácii). Vráti nový počet návštev.
async function creditAttendance(u){
  if(!u) return 0;
  const newCount=(u.visit_count||0)+1;
  const upd={visit_count:newCount};
  if(newCount===1 && !u.is_child)
    metaCapi('FirstClassAttended',{email:u.email, fbclid:u.fbclid, event_id:'fca_'+u._id}).catch(()=>{});
  if(u.user_type==='lead') upd.user_type='client'; // bola na hodine → už je klientka, nie lead
  if(u.winback_sent) upd.winback_sent=false;
  try{ applyLeadTrial(upd, u); }catch(e){}
  await q.update(db.users,{_id:u._id},{$set:upd});
  const notifUid = u.parent_id || u._id;
  const milestone = LOYALTY_MILESTONES.find(m=>m.visits===newCount);
  if(milestone){
    await q.insert(db.notifications,{user_id:notifUid,type:'loyalty',title:`🏆 Nový odznak: ${milestone.label}`,
      body:`Gratulujeme! ${newCount} návštev — ${milestone.label}.`,read:false,created_at:nowISO()}).catch(()=>{});
  }
  stampFirst(u._id, 'first_attended_at', nowISO()).catch(()=>{}); // funnel cache — pravdou ostávajú bookings
  if(!u.is_child) sendFirstClassEmail(u._id).catch(()=>{});
  checkNewAchievements(u._id).catch(()=>{}); // odznaky za návštevy/mestá + notif priateľom
  // Bola na hodine (zdarma), ale ešte nič nekúpila → prepni maily z „príď zadarmo"
  // (lead_nurture/welcome) na trial_followup (motivácia ku kúpe). Raz na osobu.
  (async()=>{
    try{
      if(u.is_child || u.is_admin || u.trial_followup_enrolled) return;
      if((u.single_entries||0)>0) return;
      const mem = await q.one(db.memberships,{user_id:u._id, status:'active'});
      if(mem && (mem.expires_at||'')>new Date().toISOString()) return;
      await cancelSequence(u._id,'lead_nurture');
      await cancelSequence(u._id,'welcome');
      await enqueueSequence(u._id,'trial_followup');
      await q.update(db.users,{_id:u._id},{$set:{trial_followup_enrolled:true, trial_followup_at:nowISO()}});
    }catch(e){}
  })();
  return newCount;
}

// Tréner/admin: POTVRDIŤ HODINU ako absolvovanú — všetkým „confirmed" na daný termín
// pripíše návštevu + body (a označí attended). Idempotentné (attended sa preskočia).
app.post('/api/attendance/confirm-session', trainerAuth, async(req,res)=>{
  try{
    const cls=await q.one(db.classes,{_id:String(req.body.class_id||'')});
    if(!cls) return res.status(404).json({error:'Hodina nenájdená'});
    if(cls.category==='Online') return res.status(400).json({error:'Online hodiny sa potvrdzujú automaticky pri štarte vysielania — účasť aj body dostanú klientky samé, tréner za ne výplatu nemá.'});
    const date=/^\d{4}-\d{2}-\d{2}$/.test(req.body.date||'') ? req.body.date : sessionDateFor(cls);
    const rows=await q.find(db.bookings,{class_id:cls._id, booking_date:date, status:'confirmed'});
    // Tréner najprv odškrtne, kto NEPRIŠIEL — bez toho by sa každý prihlásený
    // zapísal ako prítomný a no-show dáta by neexistovali (a body by dostal aj ten,
    // kto tam nebol). absent_ids = _id rezervácií.
    const absent=new Set((Array.isArray(req.body.absent_ids)?req.body.absent_ids:[]).map(String));
    let credited=0, noShows=0;
    for(const b of rows){
      if(absent.has(String(b._id))){
        await q.update(db.bookings,{_id:b._id},{$set:{attendance_status:'no_show', attendance_source:'trainer',
          no_show_at:nowISO(), no_show_by:req.trainerUser._id}});
        noShows++;
        if(b.user_id && !b.is_child_booking){ const nu=await q.one(db.users,{_id:b.user_id});
          if(nu) await q.update(db.users,{_id:nu._id},{$set:{no_show_count:(nu.no_show_count||0)+1}}); }
        if(b.user_id && !b.is_child_booking) await q.insert(db.notifications,{user_id:b.user_id, type:'no_show',
          title:'Nezachytili sme ťa na hodine 💛',
          body:`${b.class_name||'Hodina'} ${String(b.booking_date||'').split('-').reverse().join('.')} — vyber si prosím náhradný termín, tešíme sa na teba!`,
          read:false, created_at:nowISO()}).catch(()=>{});
        continue;
      }
      const wasNoShow = b.attendance_status==='no_show';
      await q.update(db.bookings,{_id:b._id},{$set:{status:'attended', attended_at:nowISO(), attended_by:req.trainerUser._id,
        attendance_status:'attended', attendance_source:'trainer',
        ...(wasNoShow?{no_show_corrected_at:nowISO(), no_show_corrected_by:req.trainerUser._id}:{})}});
      if(!b.is_child_booking && b.user_id){
        const u=await q.one(db.users,{_id:b.user_id});
        if(u){ await creditAttendance(u); credited++;
          if(wasNoShow && (u.no_show_count||0)>0) await q.update(db.users,{_id:u._id},{$set:{no_show_count:Math.max(0,(u.no_show_count||0)-1)}});
        }
      } else credited++;
    }
    // Zárobok trénera za túto hodinu (základ + € za klienta nad limit) — informatívne
    const si = await sessionInstructor(cls, date);
    const rules = Object.fromEntries((await q.find(db.payout_rules,{})).map(r=>[r.trainer,r]));
    const ruleFor = ins => { if(rules[ins]) return {...DEFAULT_PAYOUT_RULE,...rules[ins]};
      const key=Object.keys(rules).find(k=>ins&&k&&(k.includes(ins.split(' ')[0])||ins.includes(k.split(' ')[0])));
      return {...DEFAULT_PAYOUT_RULE,...(key?rules[key]:{})}; };
    const rule = ruleFor(si.instructor);
    const totalAttended = await q.count(db.bookings,{class_id:cls._id, booking_date:date, status:'attended'});
    const freeAttended = await q.count(db.bookings,{class_id:cls._id, booking_date:date, status:'attended', free_class:true});
    // Klientky na hodine zdarma sa nerátajú do €/klient bonusu nad prahom
    const billable = Math.max(0, (totalAttended - freeAttended) - (rule.per_client_threshold||0));
    const sessionEarn = +((rule.fixed_per_class||0) + (rule.per_client||0)*billable).toFixed(2);
    // Notifikáciu o zárobku pošli LEN keď sa reálne niečo nové potvrdilo (žiadne duplicity).
    if(credited>0 && si.instructor_id){
      await q.insert(db.notifications,{ user_id:si.instructor_id, type:'earning',
        title:`💰 Hodina potvrdená — +${sessionEarn.toFixed(2)} €`,
        body:`${cls.name} · ${cls.location} · ${date} — ${totalAttended} účastníkov. Pripísané do tvojej výplaty.`,
        read:false, created_at:nowISO() }).catch(()=>{});
    }
    if(credited>0) await auditLog(req,'confirm_session',cls._id,{date},{credited, earn:sessionEarn},'');
    res.json({ ok:true, credited, no_shows:noShows, already:credited===0, date, class_name:cls.name, instructor:si.instructor, attended:totalAttended, session_earn:sessionEarn });
  }catch(e){ res.status(500).json({error:e.message}); }
});

// ─── QR CHECK-IN ─────────────────────────────────────────────────────────────
// POST /api/attendance/qr-checkin  { qr_data: "FA:userId", class_id }
// Returns member info + books them into the class
app.post('/api/attendance/qr-checkin', trainerAuth, async(req,res)=>{
  try {
    const {qr_data, class_id} = req.body;
    if(!qr_data) return res.status(400).json({error:'Chýba QR kód'});
    // Parse userId from "FA:userId" format
    const userId = qr_data.startsWith('FA:') ? qr_data.slice(3) : qr_data;
    const u = await q.one(db.users,{_id:userId});
    if(!u) return res.status(404).json({error:'Člen nenájdený – neplatný QR kód'});
    const mem = u ? await checkMembership(u._id) : null;
    const userData = {
      id: u._id, name: u.name, email: u.email, phone: u.phone||'',
      visit_count: u.visit_count||0, free_class_used: u.free_class_used||false,
      single_entries: u.single_entries||0, free_credits: u.free_credits||0,
      membership: mem ? {plan:mem.plan_name, expires:mem.expires_at} : null,
    };
    // If class_id provided, book them in
    if(class_id){
      const cls = await q.one(db.classes,{_id:class_id});
      if(!cls) return res.json({ok:true, user:userData, booking:null, note:'Hodina nenájdená'});
      const bdate = sessionDateFor(cls);
      const exists = await q.one(db.bookings,{class_id,user_id:u._id,booking_date:bdate,status:{$ne:'cancelled'}});
      if(exists){
        // Mark physical attendance na existujúcej rezervácii + pripíš návštevu/body (ak už nebola attended)
        const already = exists.status==='attended';
        await q.update(db.bookings,{_id:exists._id},{$set:{status:'attended',attended_at:nowISO(),attended_by:req.trainerUser._id}});
        let vc = u.visit_count||0;
        if(!already && !exists.is_child_booking){ vc = await creditAttendance(u); }
        else if(!u.is_child) sendFirstClassEmail(u._id).catch(()=>{});
        return res.json({ok:true, user:{...userData, visit_count:vc}, booking:{existing:true, attended:true, booking_date:bdate, class_name:cls.name}});
      }
      // Determine access type (first free class governed by free_class_used only)
      const hasMem = mem && mem.status === 'active';
      const hasFree = !u.free_class_used;
      const hasSingle = (u.single_entries||0) > 0;
      const hasCredit = (u.free_credits||0) > 0;
      if(!hasMem && !hasFree && !hasSingle && !hasCredit){
        return res.json({ok:false, user:userData, error:'membership_required', note:'Žiadne platné členstvo ani vstup'});
      }
      await q.insert(db.bookings,{
        class_id, class_name:cls.name, class_emoji:cls.emoji||'💃',
        class_location:cls.location, class_time_start:cls.time_start,
        day_of_week:cls.day_of_week, day_name:DAYS_SK[cls.day_of_week],
        user_id:u._id, user_name:u.name, user_email:u.email, user_phone:u.phone||'',
        booking_date:bdate, status:'attended', attended_at:nowISO(), attended_by:req.trainerUser._id,
        free_class: !hasMem&&hasFree,
        notes:'📱 QR check-in', manual:true, manual_by:req.trainerUser._id, created_at:nowISO()
      });
      const upd = {visit_count:(u.visit_count||0)+1};
      if(hasFree && !u.free_class_used) upd.free_class_used = true;
      else if(hasCredit && !hasMem) upd.free_credits = (u.free_credits||0) - 1;
      else if(hasSingle && !hasMem && !hasFree) upd.single_entries = (u.single_entries||0) - 1;
      applyLeadTrial(upd, u); // lead → automaticky „Bola na hodine"
      await q.update(db.users,{_id:u._id},{$set:upd});
      if(!u.is_child) sendFirstClassEmail(u._id).catch(()=>{});
      await q.insert(db.notifications,{user_id:u._id,type:'checkin',title:'✅ Check-in potvrdený',
        body:`${cls.name} – ${bdate} o ${cls.time_start}`,read:false,created_at:nowISO()});
      checkNewAchievements(u._id).catch(()=>{}); // nové odznaky (návštevy, mestá) + notif priateľom
      return res.json({ok:true, user:{...userData, visit_count:upd.visit_count},
        booking:{booking_date:bdate, class_name:cls.name, access_type: hasMem?'membership':hasFree?'free':hasCredit?'credit':'single'}});
    }
    // No class_id – just member lookup
    res.json({ok:true, user:userData});
  } catch(e){ res.status(500).json({error:e.message}); }
});

// GET /api/me/qr – return QR payload for the logged-in user (or ?child_id= for a child)
app.get('/api/me/qr', auth, async(req,res)=>{
  try {
    if(req.query.child_id){
      const child = await q.one(db.users,{_id:req.query.child_id});
      if(!child || child.parent_id !== req.session.uid) return res.status(403).json({error:'Neplatný detský profil'});
      return res.json({qr_data:'FA:'+child._id, name:child.name});
    }
    const u = await q.one(db.users,{_id:req.session.uid});
    if(!u) return res.status(401).json({error:'Not logged in'});
    res.json({qr_data:'FA:'+u._id, name:u.name});
  } catch(e){ res.status(500).json({error:e.message}); }
});

