// FAMILY ACCOUNTS – parent manages child profiles (no own login)
// ═══════════════════════════════════════════════════════════════════════════════
const MAX_CHILDREN = 6;

app.get('/api/family/children', auth, async(req,res)=>{
  try {
    const children = await q.find(db.users,{parent_id:req.session.uid, active:{$ne:false}},{created_at:1});
    const out = [];
    for(const c of children){
      const m = await checkMembership(c._id);
      const upcoming = await q.find(db.bookings,{user_id:c._id,status:'confirmed',booking_date:{$gte:today()}},{booking_date:1});
      out.push({
        id:c._id, name:c.name, birth_date:c.birth_date||null, birth_year:c.birth_year||null,
        visit_count:c.visit_count||0, single_entries:c.single_entries||0, free_credits:c.free_credits||0,
        free_class_used:c.free_class_used||false,
        membership: m ? {plan_name:m.plan_name, expires_at:m.expires_at, status:m.status||'active'} : null,
        upcoming: upcoming.slice(0,3),
      });
    }
    res.json(out);
  } catch(e){ res.status(500).json({error:e.message}); }
});

app.post('/api/family/children', auth, async(req,res)=>{
  try {
    const name = (req.body.name||'').trim();
    if(!name) return res.status(400).json({error:'Chýba meno dieťaťa'});
    // Full date of birth (YYYY-MM-DD); birth_year derived for display
    let birth_date = null, birth_year = null;
    if(req.body.birth_date){
      if(!/^\d{4}-\d{2}-\d{2}$/.test(req.body.birth_date)) return res.status(400).json({error:'Neplatný dátum narodenia'});
      const dt = new Date(req.body.birth_date);
      const y = dt.getFullYear();
      if(isNaN(dt.getTime()) || y < 1990 || dt > new Date()) return res.status(400).json({error:'Neplatný dátum narodenia'});
      birth_date = req.body.birth_date; birth_year = y;
    } else if(req.body.birth_year){
      const y = +req.body.birth_year;
      if(y < 1990 || y > new Date().getFullYear()) return res.status(400).json({error:'Neplatný rok narodenia'});
      birth_year = y;
    }
    const count = await q.count(db.users,{parent_id:req.session.uid, active:{$ne:false}});
    if(count >= MAX_CHILDREN) return res.status(400).json({error:`Maximálne ${MAX_CHILDREN} detí na účet`});
    const token = Math.random().toString(36).slice(2,10);
    const internalEmail = 'child-'+token+'@internal.local';
    // Children get a unique (unused) referral_code to satisfy the unique index
    let childCode = 'CHILD-'+token.toUpperCase();
    while(await q.one(db.users,{referral_code:childCode})) childCode = 'CHILD-'+Math.random().toString(36).slice(2,10).toUpperCase();
    const child = await q.insert(db.users,{ account_creation_type:'child',
      name, email:internalEmail, referral_code:childCode, parent_id:req.session.uid, is_child:true, birth_date, birth_year,
      user_type:'client', is_admin:false, active:true,
      visit_count:0, free_class_used:false, single_entries:0, free_credits:0, referral_credit:0,
      created_at:today()
    });
    res.json({ok:true, id:child._id, name:child.name});
  } catch(e){ res.status(500).json({error:e.message}); }
});

app.put('/api/family/children/:id', auth, async(req,res)=>{
  try {
    const child = await q.one(db.users,{_id:req.params.id});
    if(!child || child.parent_id !== req.session.uid) return res.status(403).json({error:'Neplatný detský profil'});
    const upd = {};
    if(req.body.name!==undefined){ const n=(req.body.name||'').trim(); if(!n) return res.status(400).json({error:'Chýba meno'}); upd.name=n; }
    if(req.body.birth_date!==undefined){
      if(req.body.birth_date && !/^\d{4}-\d{2}-\d{2}$/.test(req.body.birth_date)) return res.status(400).json({error:'Neplatný dátum narodenia'});
      upd.birth_date = req.body.birth_date || null;
      upd.birth_year = req.body.birth_date ? new Date(req.body.birth_date).getFullYear() : null;
    } else if(req.body.birth_year!==undefined) upd.birth_year = +req.body.birth_year || null;
    await q.update(db.users,{_id:child._id},{$set:upd});
    res.json({ok:true});
  } catch(e){ res.status(500).json({error:e.message}); }
});

app.delete('/api/family/children/:id', auth, async(req,res)=>{
  try {
    const child = await q.one(db.users,{_id:req.params.id});
    if(!child || child.parent_id !== req.session.uid) return res.status(403).json({error:'Neplatný detský profil'});
    // Soft-delete + cancel future bookings
    await q.update(db.users,{_id:child._id},{$set:{active:false}});
    const future = await q.find(db.bookings,{user_id:child._id,status:'confirmed',booking_date:{$gte:today()}});
    for(const b of future) await q.update(db.bookings,{_id:b._id},{$set:{status:'cancelled',cancelled_at:nowISO()}});
    res.json({ok:true});
  } catch(e){ res.status(500).json({error:e.message}); }
});

// ═══════════════════════════════════════════════════════════════════════════════
// EMAIL NOTIFICATIONS (Nodemailer – optional, falls back gracefully)
// ═══════════════════════════════════════════════════════════════════════════════
let mailer = null;
let resendApiKey = null;
let brevoApiKey = null;
(async()=>{
  try {
    // Prefer Brevo HTTP API if BREVO_API_KEY is set (works on Railway – HTTPS, no SMTP)
    if(process.env.BREVO_API_KEY){
      brevoApiKey = process.env.BREVO_API_KEY;
      console.log('✉️  Brevo API nakonfigurovaný');
      return;
    }
    // Resend HTTP API if RESEND_API_KEY is set
    if(process.env.RESEND_API_KEY){
      resendApiKey = process.env.RESEND_API_KEY;
      console.log('✉️  Resend API nakonfigurovaný');
      return;
    }
    const nodemailer = require('nodemailer');
    if(process.env.SMTP_HOST && process.env.SMTP_USER && process.env.SMTP_PASS){
      mailer = nodemailer.createTransport({
        host: process.env.SMTP_HOST,
        port: +process.env.SMTP_PORT||587,
        secure: process.env.SMTP_SECURE==='true',
        auth: { user:process.env.SMTP_USER, pass:process.env.SMTP_PASS }
      });
      console.log('✉️  SMTP mailer nakonfigurovaný');
    }
  } catch(e){ /* nodemailer not installed – silent fallback */ }
})();

// Maily sa reálne odosielajú LEN z produkcie. Lokálny beh a QA testy generujú
// desiatky notifikácií (predaje, rezervácie, vstupenky) — tie končili v schránke
// majiteľa ako spam. MAIL_ON=1 zapne odosielanie aj mimo produkcie, ak treba
// odladiť konkrétny mail.
// RAILWAY_ENVIRONMENT je poistka: aj keby sa raz stratilo NODE_ENV=production zo
// štartovacieho príkazu, produkcia na Railway maily posielať nesmie prestať.
const MAIL_ENABLED = process.env.MAIL_OFF==='1' ? false
  : (process.env.MAIL_ON==='1' || process.env.NODE_ENV==='production' || !!process.env.RAILWAY_ENVIRONMENT);
if(!MAIL_ENABLED) console.log('✉️  Odosielanie mailov VYPNUTÉ (nie je produkcia) — MAIL_ON=1 ho zapne');

// Stropy podľa priority: kým transakčné (1–2) môžu do 295/deň, marketing (10) len do 200.
// Vyššie číslo = nižšia priorita = skorší stop. (FUNNEL-006, spec AJ.)
const MAIL_TIER_CAPS={1:295,2:295,3:285,4:270,5:255,6:240,7:240,8:225,9:225,10:200};
async function mailBudgetOk(priority, sentOverride){
  const p=Math.min(10,Math.max(1,Math.round(+priority||4)));
  const cap=MAIL_TIER_CAPS[p];
  const sent = sentOverride!==undefined ? +sentOverride
    : (await q.find(db.mail_log,{})).filter(m=>(m.created_at||'').startsWith(today())).length;
  return sent < cap;
}
async function sendMail(to, subject, html, opts){
  // @import.local = syntetické adresy klientov zo starého zoznamu (majú len telefón,
  // kontaktujú sa SMSkou) — nikdy na ne nič neposielaj.
  if(/@import\.local$/i.test(String(to||''))) return false;
  // QA: MAIL_CAPTURE=1 → mail sa zaloguje a linky sa prepíšu, ale NIKDY sa neodošle.
  // Capture má prednosť VŽDY — aj pred MAIL_ON (28.8.: test s MAIL_ON+MAIL_CAPTURE
  // reálne odoslal 9 QA mailov, prišli bounce — už sa to stať nemôže).
  const capture = process.env.MAIL_CAPTURE==='1';
  if(!MAIL_ENABLED && !capture){ console.log(`✉️  [mail vypnutý] ${to} · ${subject}`); return false; }
  const priority=(opts&&+opts.priority)||4;
  if(!capture && !(await mailBudgetOk(priority))){
    console.log(`✉️  [mail budžet] preskočené p${priority} · ${to} · ${subject}`);
    return false;
  }
  // Mail log + tracking pixel (CRM P3): každý odoslaný mail sa zaloguje a otvorenie
  // sa zaznamená cez 1×1 pixel — open rate vidno v /api/admin/mail-log/stats.
  try{
    const log=await q.insert(db.mail_log,{to:String(to), subject:String(subject||''),
      template:(opts&&opts.template)||null, created_at:nowISO(), opened_at:null, clicked_at:null, click_count:0});
    if(typeof html==='string'){
      // FUNNEL-012 click-tracking: každý odkaz ide cez /api/mail/click/<log>/<idx>.
      // Ciele sa ukladajú do mail_logu a redirect ide podľa indexu — žiadny open-redirect
      // cez URL parameter. Pixel/click linky sa neprepisujú (má ich len server).
      const links=[];
      html=html.replace(/href=(["'])(https?:\/\/[^"']+)\1/g,(m,qt,url)=>{
        if(url.includes('/api/mail/')) return m;
        const idx=links.push(url)-1;
        return 'href='+qt+APP_URL+'/api/mail/click/'+log._id+'/'+idx+qt;
      });
      if(links.length) await q.update(db.mail_log,{_id:log._id},{$set:{links}});
      if(html.includes('</body>'))
        html=html.replace('</body>',`<img src="${APP_URL}/api/mail/open/${log._id}.gif" width="1" height="1" alt="" style="display:none"></body>`);
      else
        html+=`<img src="${APP_URL}/api/mail/open/${log._id}.gif" width="1" height="1" alt="" style="display:none">`;
    }
  }catch(e){}
  if(capture) return false; // QA capture — zalogované, nič sa neposiela
  // Brevo HTTP API (preferred on Railway – HTTPS, no blocked SMTP ports)
  if(brevoApiKey){
    try {
      const fromAddr = process.env.SMTP_FROM || process.env.SMTP_USER || 'gruber.marek@gmail.com';
      const r = await fetch('https://api.brevo.com/v3/smtp/email', {
        method:'POST',
        headers:{'api-key':brevoApiKey,'Content-Type':'application/json'},
        body: JSON.stringify({
          sender:{ name:'Fusion Academy', email:fromAddr },
          to:[{ email:to }],
          subject, htmlContent:html
        })
      });
      const j = await r.json().catch(()=>({}));
      if(r.ok){ return true; }
      console.error('Brevo error:', JSON.stringify(j));
      return false;
    } catch(e){ console.error('Brevo error:', e.message); return false; }
  }
  // Resend HTTP API (preferred on Railway)
  if(resendApiKey){
    try {
      const fromAddr = process.env.SMTP_FROM || 'noreply@latindancefusion.art';
      const r = await fetch('https://api.resend.com/emails', {
        method:'POST',
        headers:{'Authorization':`Bearer ${resendApiKey}`,'Content-Type':'application/json'},
        body: JSON.stringify({ from:`Fusion Academy <${fromAddr}>`, to:[to], subject, html })
      });
      const j = await r.json();
      if(j.id){ return true; }
      console.error('Resend error:', JSON.stringify(j));
      return false;
    } catch(e){ console.error('Resend error:', e.message); return false; }
  }
  if(!mailer) return false;
  try {
    const fromAddr = process.env.SMTP_FROM || process.env.SMTP_USER;
    await mailer.sendMail({ from:`"Fusion Academy" <${fromAddr}>`, to, subject, html });
    return true;
  } catch(e){ console.error('Mail error:', e.message); return false; }
}

// Send booking confirmation email
app.post('/api/bookings', auth, async(req,res)=>{
  try {
    const {class_id, booking_date, notes, override_free, for_child_id}=req.body;
    if(!class_id || class_id==='null' || class_id==='undefined') return res.status(400).json({error:'Chýba trieda'});
    const cls=await q.one(db.classes,{_id:class_id});
    if(!cls||!cls.active){
      const who=await q.one(db.users,{_id:req.session.uid});
      console.warn('⚠️ booking 404: class_id='+class_id+' user='+(who&&who.email)+' exists='+!!cls+(cls?' active='+cls.active:''));
      return res.status(404).json({error:'Hodina nenájdená', stale:true});
    }
    // Jednorazový termín sa dá rezervovať len na svoj dátum
    if(!classRunsOn(cls, booking_date||today())) return res.status(404).json({error:'Hodina nenájdená', stale:true});
    const parent=await q.one(db.users,{_id:req.session.uid});
    // ── Booking for a child profile? ────────────────────────────────────────────
    let target = parent;
    if(for_child_id){
      const child = await q.one(db.users,{_id:for_child_id});
      if(!child || child.parent_id !== req.session.uid || child.active===false)
        return res.status(403).json({error:'Neplatný detský profil'});
      target = child;
    }
    const isChild = target !== parent;
    const u = target; // gate + visit-count apply to the target (self or child)

    // ── Free-class / membership gate ───────────────────────────────────────────
    // Private lessons are never free (category check)
    const isPrivate = /súkromn/i.test(cls.name) || /súkromn/i.test(cls.category||'');
    const isOnlineClass = cls.category==='Online';
    const isTechClass = cls.category==='Technika';
    const visitCount = u.visit_count || 0;
    let payOnSite = false; // rezervácia bez členstva/kreditu so sľubom platby na mieste
    let deductPlan = null; // odpočet vstupu/kreditu sa vykoná až po úspešnej validácii
    // Čím klientka za hodinu „zaplatila" — bez tohto sa jej pri zrušení nedal vrátiť vstup
    let accessMethod = u.free_class_used ? 'membership' : 'free_class';
    // "First class free" is governed solely by free_class_used — the same flag the
    // client profile shows. Do NOT also gate on visit_count, or a client whose free
    // class is still available (flag false) but has visits from other paths gets
    // wrongly redirected to buy membership.
    // ── TECHNICKÝ TRÉNING (kategória Technika) — vlastný cenník ────────────────
    // Členstvo hodinu NEkryje. Platí bežná permanentka/vstup, alebo platba na mieste
    // podľa členstva: 10 € / Bronze 9 € / Silver 8 € / Gold 7 €.
    // „Prvá hodina zadarmo" platí aj na techniku (spotrebuje sa rovnako ako pri Zumbe).
    let techPrice=null;
    if(isTechClass && !u.is_admin && u.user_type!=='trainer'){
      const freeDates=(await q.one(db.settings,{key:'tech_free_dates'}))?.value||[];
      const bdatePre=booking_date||displayNextDateForDay(cls.day_of_week);
      if(freeDates.includes(bdatePre)){ accessMethod='promo_free'; }
      else if(!u.free_class_used){ accessMethod='free_class'; }
      else {
        const m=await checkMembership(u._id);
        const active=m && m.status==='active' && (!m.expires_at || m.expires_at>=today());
        const plan=String((m?.plan_id||'')+' '+(m?.plan_name||'')).toLowerCase();
        if((u.free_credits||0)>0){ deductPlan={uid:u._id, field:'free_credits', value:u.free_credits-1}; accessMethod='free_credit'; }
        else if((u.single_entries||0)>0){ deductPlan={uid:u._id, field:'single_entries', value:u.single_entries-1}; accessMethod='single_entry'; }
        else {
          // Cenník podľa členstva: Gold 7 / Silver 8 / Bronze 9 / bez členstva 10 (Gold už NIE JE zdarma)
          techPrice=active&&/gold/.test(plan)?7:(active&&/silver/.test(plan)?8:(active&&/bronze/.test(plan)?9:10));
          if(req.body.pay_on_site){ payOnSite=true; accessMethod='pay_on_site'; }
          else return res.status(402).json({ error:'membership_required', can_pay_on_site:true, tech_price:techPrice,
            message:`Technický tréning: ${techPrice} € jednorazovo${techPrice<10?' (zľava podľa členstva)':''}. Platí aj permanentka — vstup si kúpiš kartou v Obchode, alebo zaplatíš na mieste.` });
        }
      }
    }
    if(!u.is_admin && u.user_type !== 'trainer' && !isOnlineClass && !isTechClass){
      if(u.free_class_used){
        // Not first visit – need membership or single entry credit
        const m = await checkMembership(u._id);
        // Online-only plány (Online Basic/Premium) NEkryjú živé hodiny — inak by Online Basic
        // klientka prešla ako „membership" a nikto by od nej nevybral vstupné.
        const isOnlineOnlyPlan = m && /online/.test(String((m.plan_id||'')+' '+(m.plan_name||'')).toLowerCase());
        const hasMembership = m && (m.status==='active') && (!m.expires_at || m.expires_at >= today()) && !isOnlineOnlyPlan;
        const singleEntries = u.single_entries || 0;
        const freeCredits = u.free_credits || 0;
        // ── Dieťa bez vlastného členstva/vstupov → skús ČLENSTVO/VSTUPY RODIČA ──
        // Mama s členstvom môže dcéru booknúť zo svojho účtu; vstup/kredit sa odráta jej.
        let parentCover = null;
        if(isChild && !hasMembership && singleEntries <= 0 && freeCredits <= 0){
          const pm = await checkMembership(parent._id);
          const pHasMem = pm && (pm.status==='active') && (!pm.expires_at || pm.expires_at >= today());
          if(pHasMem) parentCover = {method:'parent_membership'};
          else if((parent.free_credits||0) > 0) parentCover = {method:'parent_free_credit', deduct:{uid:parent._id, field:'free_credits', value:(parent.free_credits||0)-1}};
          else if((parent.single_entries||0) > 0) parentCover = {method:'parent_single_entry', deduct:{uid:parent._id, field:'single_entries', value:(parent.single_entries||0)-1}};
        }
        if(!hasMembership && singleEntries <= 0 && freeCredits <= 0 && !parentCover){
          if(req.body.pay_on_site){
            // Klient sľúbil zaplatiť vstup na mieste (cash) — rezerváciu povoľ a výrazne označ,
            // aby tréner/admin vedel vybrať vstupné/členské. Nič sa neodpočítava.
            payOnSite = true;
          } else return res.status(402).json({
            error:'membership_required',
            can_pay_on_site: true,
            message: isChild
              ? `Prvá hodina zadarmo pre ${u.name} bola využitá. Na ďalšiu potrebuje členstvo alebo jednorazový vstup (10 €).`
              : 'Prvá hodina zadarmo bola využitá. Na ďalšiu hodinu potrebuješ členstvo alebo jednorazový vstup (10 €).',
            visit_count: visitCount,
            free_class_used: !!u.free_class_used
          });
        }
        // Use free credit first, then single entry, then membership.
        // POZOR: odpočet sa vykoná až PO kontrole kapacity/duplicity/zrušenia —
        // inak zamietnutá rezervácia zožrala klientke vstup (reálne sa stávalo).
        if(!hasMembership){
          if(freeCredits > 0){
            deductPlan={uid:u._id, field:'free_credits', value:freeCredits-1};
            accessMethod='free_credit';
          } else if(singleEntries > 0){
            deductPlan={uid:u._id, field:'single_entries', value:singleEntries-1};
            accessMethod='single_entry';
          } else if(parentCover){
            accessMethod=parentCover.method;
            if(parentCover.deduct) deductPlan=parentCover.deduct;
          } else if(payOnSite) accessMethod='pay_on_site';
        }
      }
    }

    const bdate=booking_date||displayNextDateForDay(cls.day_of_week);
    if(await q.one(db.class_cancellations,{class_id, date:bdate})) return res.status(400).json({error:'Táto hodina je zrušená a nedá sa rezervovať.'});
    // Kapacita sa počíta pre KONKRÉTNY termín — predtým sa sčítavali rezervácie zo
    // všetkých týždňov dokopy, takže po pár týždňoch hlásila obľúbená hodina „plná" navždy.
    const booked=await q.count(db.bookings,{class_id, booking_date:bdate, status:{$ne:'cancelled'}});
    if(booked>=cls.capacity) return res.status(400).json({error:'Hodina je plne obsadená – skúste čakací zoznam'});
    const exists=await q.one(db.bookings,{class_id,user_id:u._id,booking_date:bdate,status:{$ne:'cancelled'}});
    if(exists) return res.status(400).json({error:isChild?`${u.name} je už na túto hodinu prihlásené`:'Na túto hodinu ste sa už prihlásili'});
    // Validácia prešla — až teraz odpočítaj vstup/kredit
    if(deductPlan) await q.update(db.users,{_id:deductPlan.uid||u._id},{$set:{[deductPlan.field]: deductPlan.value}});
    const booking=await q.insert(db.bookings,{
      class_id, class_name:cls.name, class_emoji:cls.emoji||'💃',
      class_location:cls.location, class_time_start:cls.time_start, class_time_end:cls.time_end,
      day_of_week:cls.day_of_week, day_name:DAYS_SK[cls.day_of_week],
      user_id:u._id, user_name:u.name, user_email:isChild?parent.email:u.email, user_phone:u.phone||parent.phone||'',
      booked_by:parent._id, booked_by_name:parent.name, is_child_booking:isChild, child_name:isChild?u.name:null,
      booking_date:bdate, status:'confirmed', pay_on_site:payOnSite, notes:notes||'',
      pay_amount: payOnSite ? (techPrice||10) : null, // koľko vybrať na mieste (technika má cenník podľa členstva)
      free_class: !u.free_class_used, // 1. hodina zdarma (aj technika) — nepočíta sa do €/klient bonusu trénera
      access_method: accessMethod,    // pre korektné vrátenie vstupu pri zrušení
      created_at:nowISO()
    });
    if(payOnSite){
      // Daj vedieť adminom, že príde klient bez členstva — vybrať platbu na mieste.
      // Zlúčené s prípadnou „Čaká platba" žiadosťou tej istej klientky z obchodu (jedna karta).
      await adminPayNotify(u, 'pay_on_site', '💵 Rezervácia s platbou na mieste',
        `${u.name} — ${cls.name} ${bdate}${techPrice?` (${techPrice} € podľa členstva)`:''}. Nemá členstvo ani vstupy, vybrať platbu na mieste.`).catch(()=>{});
    }
    // POZOR: rezervácia sama NEpripočíta návštevu ani body — pripíšu sa až keď tréner
    // POTVRDÍ absolvovanie hodiny (QR alebo „potvrdiť hodinu"). Tu len spotrebuj 1. hodinu zdarma
    // (rezervácia miesta) a resetni winback príznak.
    const userUpd = {};
    if(!u.free_class_used && !isOnlineClass) userUpd.free_class_used = true; // platí aj pre techniku
    if(u.winback_sent) userUpd.winback_sent = false;
    if(Object.keys(userUpd).length) await q.update(db.users,{_id:u._id},{$set: userUpd});
    const notifUid = parent._id;
    const who = isChild ? `${u.name}: ` : '';
    await q.insert(db.notifications,{user_id:notifUid,type:'booking',title:`Rezervácia potvrdená ✅`,body:`${who}${cls.name} – ${bdate} o ${cls.time_start}`,read:false,created_at:nowISO()});
    // NOTE: the thank-you + membership offer email is sent AFTER the client actually
    // attends their first class (see runDailyJobs → "Post-first-class follow-up"),
    // not here at booking time, so we don't thank them before they've been.
    // Send confirmation email — pri PRVEJ rezervácii (nie dieťa) pošli priateľské uvítanie
    const isFirstBooking = !isChild && (await q.count(db.bookings,{user_id:u._id, status:{$ne:'cancelled'}}))===1;
    if(isFirstBooking){
      await sendFirstBookingWelcome(u, cls, bdate, booking._id);
    } else if(parent.email){
      sendMail(parent.email,`Rezervácia potvrdená – ${cls.name}`,`<h2>Rezervácia potvrdená ✅</h2><p>Ahoj <b>${parent.name}</b>,</p><p>Rezervácia ${isChild?`pre <b>${u.name}</b> `:''}na hodinu <b>${cls.name}</b> bola úspešne zaznamenaná.</p><ul><li>Dátum: <b>${bdate}</b></li><li>Čas: <b>${cls.time_start}–${cls.time_end||''}</b></li><li>Miesto: <b>${cls.location}</b></li></ul><p>📅 <a href="${APP_URL}/cal/booking/${booking._id}.ics" style="color:#C9A84C;font-weight:bold">Pridať do kalendára</a></p><p>Tešíme sa na vás!</p><p><i>Fusion Academy</i></p>`, {priority:3, template:'booking_confirm'}).catch(()=>{});
    }
    // Rezervácia na dnešok = ranný pripomienkový mail by už nebehol → pošli hneď
    if(bdate===today()) sendFirstClassDayReminder(booking).catch(()=>{});
    res.json({ok:true, id:booking._id, class_name:cls.name, booking_date:bdate, visit_count:u.visit_count||0, for_child:isChild?u.name:null});
  } catch(e){res.status(500).json({error:e.message});}
});

