app.get('/api/client/spotlight', auth, async(req,res)=>{
  try {
    const now = new Date();
    const monthStr = today().slice(0,7);
    const mmdd = today().slice(5); // MM-DD
    const users = (await q.find(db.users,{is_admin:{$ne:true}}))
      .filter(u=>u.user_type!=='trainer' && !u.is_child && !u.anonymous && !(u.imported && !u.claimed));
    const uName = Object.fromEntries(users.map(u=>[u._id,u]));

    const yearStr = today().slice(0,4);
    const allUsers = await q.find(db.users,{});
    const bookings = await q.find(db.bookings,{});
    const activeMems = await q.find(db.memberships,{status:'active'});
    const memActive = {}, memName = {}, memTier = {};
    const paidTiersSpot = await paidMembershipTierMap();
    activeMems.forEach(m=>{ if(!m.expires_at || m.expires_at>=today()){ memActive[m.user_id]=true; memName[m.user_id]=MEMBERSHIP_PLANS[m.plan_id]?.name||m.plan_name||'Členstvo'; memTier[m.user_id]=effectiveMemTier(paidTiersSpot[m.user_id]||null, m.plan_id||null, !!m.gift); } });

    const adjacency={}; allUsers.forEach(u=>{ if(u.sponsor_id) (adjacency[u.sponsor_id]=adjacency[u.sponsor_id]||[]).push(u._id); });
    // Víťaz za dané obdobie (prefix YYYY-MM alebo YYYY)
    const winnerFor = async (prefix)=>{
      const refCount={}; allUsers.forEach(u=>{ if((u.created_at||'').startsWith(prefix) && u.sponsor_id) refCount[u.sponsor_id]=(refCount[u.sponsor_id]||0)+1; });
      const attCount={}, onlineCount={};
      bookings.forEach(b=>{ const d=b.booking_date||(b.created_at||'').slice(0,10);
        if((d||'').startsWith(prefix) && ['attended','confirmed'].includes(b.status) && b.user_id){
          const on=/online/i.test(b.class_name||'')||/online/i.test(b.class_location||'')||b.online===true;
          if(on) onlineCount[b.user_id]=(onlineCount[b.user_id]||0)+1; else attCount[b.user_id]=(attCount[b.user_id]||0)+1;
        } });
      const buyerSet=await membershipBuyersInPeriod(prefix);
      const merchMap=await merchCountMapInPeriod(prefix);
      const privMap=await privCountMapInPeriod(prefix);
      // body z kolesa dennej odmeny + míľniky série — bez nich rebríček nesedel s „Tvoje body"
      const spinBy={}; (await q.find(db.spins,{})).forEach(s=>{ if((s.date||'').startsWith(prefix)){ const b=spinBy[s.user_id]=spinBy[s.user_id]||{p:0,c:0}; b.p+=(+s.points||0); if(!s.milestone) b.c++; } });
      // ⭐ schválené Google recenzie (+10 b) — musia sedieť s admin sumárom bodov
      const reviewBySpot={}; (await q.find(db.review_claims,{status:'approved'})).forEach(c=>{ if(String(c.decided_at||c.created_at||'').startsWith(prefix)) reviewBySpot[c.user_id]=(reviewBySpot[c.user_id]||0)+1; });
      const ranked=[];
      for(const u of users){
        const nm=newMemberPointsFor(u._id, adjacency, buyerSet);
        const md=merchDownlinePointsFor(u._id, adjacency, merchMap);
        const bd=buildPointItems({ hours:attCount[u._id]||0, online:onlineCount[u._id]||0, refs:refCount[u._id]||0, hasMem:!!memActive[u._id], memName:memName[u._id]||null, memTier:memTier[u._id]||null, newMemberCount:nm.count, newMemberPoints:nm.points, merchCount:merchMap[u._id]||0, merchLineCount:md.count, merchLinePoints:md.points, privCount:privMap[u._id]||0, spinPoints:(spinBy[u._id]||{}).p||0, spinCount:(spinBy[u._id]||{}).c||0, reviewCount:reviewBySpot[u._id]||0 }, prefix);
        if(bd.total>0) ranked.push({ id:u._id, name:u.name, avatar:u.avatar||null, refs:refCount[u._id]||0, hours:attCount[u._id]||0, score:bd.total, points:bd.total, breakdown:bd.items, badge:getMemberBadge(u.created_at, u) });
      }
      ranked.sort((a,b)=>b.points-a.points);
      return ranked;
    };
    const rankedMonth = await winnerFor(monthStr);
    const rankedYear  = await winnerFor(yearStr);
    const winner = rankedMonth[0]||null;
    const winnerYear = rankedYear[0]||null;
    const rewardsCfg = (await q.one(db.settings,{key:'rewards'}))?.value || {};

    // birthdays & namedays today (non-anonymous)
    const todayName = SK_NAMEDAYS[mmdd] || '';
    const nameTargets = todayName ? todayName.split(/\s+a\s+|,\s*/).map(stripDia).filter(Boolean) : [];
    const birthdays=[], namedays=[];
    const todayISO=today(); const me=req.session.uid;
    for(const u of users){
      if(u.birthday && u.birthday.slice(5)===mmdd){
        const wishes=await q.find(db.birthday_wishes,{to_id:u._id, date:todayISO});
        birthdays.push({ id:u._id, name:u.name, avatar:u.avatar||null,
          wishers: wishes.map(w=>({id:w.from_id, name:w.from_name})),
          wish_count: wishes.length,
          i_wished: wishes.some(w=>w.from_id===me),
          is_me: u._id===me });
      }
      const fn = stripDia(firstName(u.name));
      if(fn && nameTargets.includes(fn)) namedays.push({id:u._id, name:u.name, avatar:u.avatar||null});
    }
    const slim = w => ({ id:w.id, name:w.name, avatar:w.avatar, points:w.points, breakdown:w.breakdown, badge:w.badge });
    // „Tvoje body" — pozícia a body prihlásenej klientky v mesačnom aj ročnom rebríčku
    const myRank = ranked => { const i=ranked.findIndex(w=>w.id===req.session.uid);
      return i>=0 ? {points:ranked[i].points, rank:i+1, total:ranked.length, breakdown:ranked[i].breakdown}
                  : {points:0, rank:null, total:ranked.length, breakdown:[]}; };
    // Posledná korunovaná Klientka mesiaca — glow-up karta s cenami na dashboarde
    let lastWinner=null;
    try{
      const w=(await q.find(db.monthly_winners,{})).filter(x=>x.type!=='year')
        .sort((a,b)=>String(b.month).localeCompare(String(a.month)))[0];
      if(w){ const wu=await q.one(db.users,{_id:w.user_id});
        lastWinner={ month:w.month, id:w.user_id, name:w.user_name, avatar:wu?.avatar||null,
          points:w.points, prizes:w.prizes||[], value:w.value||0 }; }
    }catch(e){}
    res.json({ month: monthStr, year: yearStr, today_nameday: todayName,
      clientOfMonth: winner, clientOfYear: winnerYear, lastWinner,
      topMonth: rankedMonth.slice(0,5).map(slim), topYear: rankedYear.slice(0,5).map(slim),
      myMonth: myRank(rankedMonth), myYear: myRank(rankedYear),
      rewards: { year_end: rewardsCfg.year_end||'', disclaimer: rewardsCfg.disclaimer||'',
        month_prizes: rewardsCfg.month_prizes||[], year_prizes: rewardsCfg.year_prizes||[] },
      birthdays, namedays,
      me_anonymous: !!(await q.one(db.users,{_id:req.session.uid}))?.anonymous });
  } catch(e){ res.status(500).json({error:e.message}); }
});

// ── Referral cieľ: motivačný progress k odmenám za nové registrácie ──────────
// 1 nová = 🎒 športová taška · 2 nové = 🎟️ 50 % zľava na event · 3 nové = ⭐ masterclass zdarma
const REFERRAL_GOAL_FROM = '2026-08-05'; // štart kampane
const REFERRAL_GOAL_TO   = '2026-08-31'; // deadline — do konca augusta, nech je to poriadna súťaž
const REFERRAL_GOAL_TIERS = [
  { need:1, emoji:'🎒', label:'Športová taška Fusion' },
  { need:2, emoji:'🎟️', label:'50 % zľava na event' },
  { need:3, emoji:'⭐', label:'Masterclass event ZDARMA' },
];
// Ráta sa až PLATIACA kamoška: registrácia v okne súťaže + reálne zaplatené
// členstvo alebo permanentka/vstupy (darčeky a 0 € sa nerátajú).
async function referralGoalHasPaid(uid){
  const tx=(await q.find(db.transactions,{user_id:uid}))
    .find(t=>['membership','single_entry'].includes(t.type) && t.payment_method!=='free' && ((+t.amount||0)>0 || t.payment_method==='referral_credit'));
  if(tx) return true;
  const mem=(await q.find(db.memberships,{user_id:uid})).find(m=>(+m.price||0)>0 && m.payment_method);
  if(mem) return true;
  const pay=(await q.find(db.payments,{user_id:uid})).find(p=>['completed','active'].includes(p.status));
  return !!pay;
}
async function referralGoalCount(userId){
  const refs=(await q.find(db.users,{sponsor_id:userId}))
    .filter(u=>!u.is_child && !u.anonymous && (u.created_at||'')>=REFERRAL_GOAL_FROM && (u.created_at||'').slice(0,10)<=REFERRAL_GOAL_TO);
  let n=0; for(const r of refs){ if(await referralGoalHasPaid(r._id)) n++; }
  return n;
}
// Admin report výzvy: kto priviedol koľko platiacich kamošiek + aká odmena mu
// patrí (nákup tašiek, zľavy na event, masterclass) + súčty na objednávku.
app.get('/api/admin/referral-goal-report', adminAuth, async(req,res)=>{
  try{
    const refs=(await q.find(db.users,{}))
      .filter(u=>u.sponsor_id && !u.is_child && !u.anonymous
        && (u.created_at||'')>=REFERRAL_GOAL_FROM && (u.created_at||'').slice(0,10)<=REFERRAL_GOAL_TO
        && !/@test-fa-qa\.local$/i.test(String(u.email||'')));
    const bySponsor={};
    for(const r of refs){
      const paid=await referralGoalHasPaid(r._id);
      (bySponsor[r.sponsor_id]=bySponsor[r.sponsor_id]||{registered:[], paid:[]});
      bySponsor[r.sponsor_id][paid?'paid':'registered'].push({name:r.name, created:(r.created_at||'').slice(0,10)});
    }
    const rows=[];
    for(const [sid, v] of Object.entries(bySponsor)){
      const s=await q.one(db.users,{_id:sid}); if(!s || s.is_admin) continue;
      const n=v.paid.length;
      rows.push({ sponsor:s.name, email:s.email, phone:s.phone||'', paying:n,
        registeredOnly:v.registered.length,
        paidNames:v.paid.map(x=>x.name), registeredNames:v.registered.map(x=>x.name),
        rewards:{ taska:n>=1, event50:n>=2, masterclass:n>=3 } });
    }
    rows.sort((a,b)=>b.paying-a.paying || b.registeredOnly-a.registeredOnly);
    const totals={ taska:rows.filter(r=>r.rewards.taska).length,
      event50:rows.filter(r=>r.rewards.event50).length,
      masterclass:rows.filter(r=>r.rewards.masterclass).length,
      payingTotal:rows.reduce((s,r)=>s+r.paying,0),
      registeredTotal:rows.reduce((s,r)=>s+r.registeredOnly+r.paying,0) };
    res.json({ok:true, from:REFERRAL_GOAL_FROM, to:REFERRAL_GOAL_TO, ended:today()>REFERRAL_GOAL_TO, rows, totals});
  }catch(e){ res.status(500).json({error:e.message}); }
});

app.get('/api/client/referral-goal', auth, async(req,res)=>{
  try{
    const count=await referralGoalCount(req.session.uid);
    const daysLeft=Math.max(0, Math.ceil((new Date(REFERRAL_GOAL_TO+'T23:59:59')-Date.now())/86400000));
    res.json({ ok:true, count, from:REFERRAL_GOAL_FROM, to:REFERRAL_GOAL_TO, days_left:daysLeft, ended:today()>REFERRAL_GOAL_TO,
      tiers:REFERRAL_GOAL_TIERS.map(t=>({...t, reached:count>=t.need})) });
  }catch(e){ res.status(500).json({error:e.message}); }
});
// Po registrácii cez referral: skontroluj dosiahnutie odmeny a daj vedieť sponzorke aj adminom
async function referralGoalCheck(sponsorId){
  try{
    if(today()>REFERRAL_GOAL_TO) return; // súťaž skončila — odmeny sa už neodomýkajú
    const sp=await q.one(db.users,{_id:sponsorId});
    if(!sp || sp.is_admin || ['trainer','manager'].includes(sp.user_type)) return;
    const count=await referralGoalCount(sponsorId);
    const tier=REFERRAL_GOAL_TIERS.filter(t=>count>=t.need).length;
    if(tier<=(sp.referral_goal_notified||0)) return;
    await q.update(db.users,{_id:sp._id},{$set:{referral_goal_notified:tier}});
    const t=REFERRAL_GOAL_TIERS[tier-1];
    await q.insert(db.notifications,{user_id:sp._id,type:'referral_goal',
      title:`${t.emoji} Odmena odomknutá: ${t.label}!`,
      body: tier<REFERRAL_GOAL_TIERS.length
        ? `Máš ${count}. novú registráciu — ${t.label} je tvoja! Ďalšia méta: ${REFERRAL_GOAL_TIERS[tier].label}. 🔥`
        : `Máš ${count} nové registrácie — získala si VŠETKY odmeny vrátane: ${t.label}! 👑`,
      read:false,created_at:nowISO()}).catch(()=>{});
    const admins=await q.find(db.users,{is_admin:true});
    for(const a of admins) await q.insert(db.notifications,{user_id:a._id,type:'referral_goal',
      title:`🎯 Referral odmena: ${sp.name}`,
      body:`${sp.name} dosiahla ${count}. registráciu → odovzdať: ${t.emoji} ${t.label}`,
      read:false,created_at:nowISO()}).catch(()=>{});
  }catch(e){ console.error('referralGoalCheck:', e.message); }
}

// Zablahoželať oslávenkyni k narodeninám (dnes). Vidno kto blahoželal, s preklikom na profil.
app.post('/api/birthday/congratulate', auth, async(req,res)=>{
  try{
    const me=req.session.uid;
    const to=String(req.body.to_id||'');
    if(!to || to===me) return res.status(400).json({error:'Neplatné'});
    const u=await q.one(db.users,{_id:to});
    const meU=await q.one(db.users,{_id:me});
    if(!u) return res.status(404).json({error:'Nenájdená'});
    const todayISO=today(); const mmdd=todayISO.slice(5);
    if(!(u.birthday && u.birthday.slice(5)===mmdd)) return res.status(400).json({error:'Táto osoba dnes nemá narodeniny'});
    const ex=await q.one(db.birthday_wishes,{to_id:to, from_id:me, date:todayISO});
    if(!ex){
      await q.insert(db.birthday_wishes,{ to_id:to, from_id:me, from_name:meU?.name||'Člen', date:todayISO, created_at:nowISO() });
      await q.insert(db.notifications,{ user_id:to, type:'birthday_wish', from_id:me,
        title:'🎂 Blahoželanie k narodeninám!', body:`${meU?.name||'Niekto'} ti zablahoželal/a k narodeninám 💛`, read:false, created_at:nowISO() }).catch(()=>{});
    }
    const wishes=await q.find(db.birthday_wishes,{to_id:to, date:todayISO});
    res.json({ ok:true, wish_count:wishes.length, wishers:wishes.map(w=>({id:w.from_id, name:w.from_name})) });
  }catch(e){ res.status(500).json({error:e.message}); }
});

