// ─── Referral stats ───────────────────────────────────────────────────────────
// Client's downline network: 5 lines with each member's membership + earnings & rate per line
app.get('/api/client/network', auth, async(req,res)=>{
  try {
    const me=req.session.uid;
    const allU=await q.find(db.users,{});
    const membs=(await q.find(db.memberships,{})).filter(m=>!m._type);
    const now=new Date().toISOString();
    const activeMemb={};
    membs.forEach(m=>{ if((m.expires_at||'')>now) activeMemb[m.user_id]=m.plan_name; });
    const lines=[[],[],[],[],[]];
    let frontier=[me]; const seen=new Set([me]);
    for(let line=0; line<5; line++){
      const next=[];
      for(const pid of frontier){
        for(const k of allU.filter(u=>u.sponsor_id===pid && !u.is_admin && u.user_type!=='trainer' && !u.is_child)){
          if(seen.has(k._id)) continue; seen.add(k._id);
          lines[line].push({ id:k._id, name:k.anonymous?'Člen (skrytý)':k.name, anonymous:!!k.anonymous,
            gender:k.gender||null, joined:(k.created_at||'').slice(0,10), membership:activeMemb[k._id]||null });
          next.push(k._id);
        }
      }
      frontier=next;
    }
    let myComms=await q.find(db.commissions,{partner_id:me});
    // voliteľný mesačný filter provízií (?month=YYYY-MM), štruktúra ostáva celková
    const monthQ = /^\d{4}-\d{2}$/.test(req.query.month||'') ? req.query.month : null;
    if(monthQ) myComms = myComms.filter(c=>(c.created_at||'').slice(0,7)===monthQ);
    const earned=[0,0,0,0,0], pending=[0,0,0,0,0];
    myComms.forEach(c=>{ const l=c.level||0; if(l<5){ if(c.status==='paid') earned[l]+=(+c.amount||0); else pending[l]+=(+c.amount||0); } });
    res.json({
      month: monthQ,
      lines: lines.map((members,i)=>({ line:i+1, rate:LINE_RATES[i], count:members.length,
        earned:+earned[i].toFixed(2), pending:+pending[i].toFixed(2), members })),
      total_people: lines.reduce((s,l)=>s+l.length,0)
    });
  } catch(e){ res.status(500).json({error:e.message}); }
});

app.get('/api/client/referral', auth, async(req,res)=>{
  try {
    const u = await q.one(db.users,{_id:req.session.uid});
    if(!u) return res.status(404).json({error:'Nenájdený'});
    // Direct invites + total structure (rewards count everyone in the downline)
    const directCount = await referralCountOf(u._id);
    const refCount = await downlineCountOf(u._id);
    // How much earned from referral commissions
    const comms = await q.find(db.commissions,{partner_id:u._id});
    const earned = comms.reduce((s,c)=>s+(c.amount||0),0);
    const pendingEarned = comms.filter(c=>c.status==='pending').reduce((s,c)=>s+(c.amount||0),0);
    const paidEarned = comms.filter(c=>c.status==='paid').reduce((s,c)=>s+(c.amount||0),0);
    // Find current + next referral reward tier
    let currentTier = null, nextTier = null;
    for(const t of REFERRAL_REWARDS) {
      if(refCount >= t.referrals) currentTier = t;
      else { nextTier = t; break; }
    }
    const refLink = APP_URL + '/r/' + (u.referral_code||'');
    res.json({
      referral_code: u.referral_code,
      ref_link: refLink,
      ref_count: refCount,
      direct_count: directCount,
      earned_total: +earned.toFixed(2),
      earned_pending: +pendingEarned.toFixed(2),
      earned_paid: +paidEarned.toFixed(2),
      referral_credit: u.referral_credit||0,
      // Jeden spoločný „dostupný kredit" = referral kredit + čakajúce provízie
      available_credit: +((u.referral_credit||0) + pendingEarned).toFixed(2),
      current_tier: currentTier,
      next_tier: nextTier,
      all_tiers: REFERRAL_REWARDS,
    });
  } catch(e){res.status(500).json({error:e.message});}
});

// ─── Income history from the whole structure — zoskupenie deň/mesiac/rok/celkovo ─
app.get('/api/client/earnings-history', auth, async(req,res)=>{
  try {
    const group = ['day','month','year','all'].includes(req.query.group) ? req.query.group : 'month';
    const comms = await q.find(db.commissions,{partner_id:req.session.uid});
    const keyOf = c => {
      const iso = c.created_at || (c.month?c.month+'-01':'');
      const d = (iso||'').slice(0,10);
      if(group==='day') return d;                       // YYYY-MM-DD
      if(group==='year') return d.slice(0,4);           // YYYY
      if(group==='all') return 'all';
      return c.month || d.slice(0,7);                    // YYYY-MM
    };
    const buckets = {};
    for(const c of comms){
      const k = keyOf(c); if(!k) continue;
      if(!buckets[k]) buckets[k] = { period:k, total:0, paid:0, pending:0, lines:[0,0,0,0,0], count:0 };
      const b = buckets[k]; const amt = c.amount||0;
      b.total += amt; b.count++;
      if(c.status==='paid') b.paid += amt; else b.pending += amt;
      const lv = (typeof c.level==='number' && c.level>=0 && c.level<5) ? c.level : 0;
      b.lines[lv] += amt;
    }
    const rows = Object.values(buckets)
      .map(b=>({ ...b, month:b.period, total:+b.total.toFixed(2), paid:+b.paid.toFixed(2), pending:+b.pending.toFixed(2), lines:b.lines.map(x=>+x.toFixed(2)) }))
      .sort((a,b)=>String(b.period).localeCompare(String(a.period))); // newest first
    const grand = rows.reduce((s,r)=>s+r.total,0);
    res.json({ group, months: rows, rows, grand_total:+grand.toFixed(2), line_rates: LINE_RATES });
  } catch(e){res.status(500).json({error:e.message});}
});

// ─── Referral credit: request payout ─────────────────────────────────────────
app.post('/api/client/referral-credit/payout', auth, async(req,res)=>{
  try {
    const u = await q.one(db.users,{_id:req.session.uid});
    if(!u) return res.status(404).json({error:'Nenájdený'});
    // Kredit môže míňať v appke ktokoľvek, ale VYPLATIŤ na účet až ambasádorka.
    // Kto chce peniaze na účet, musí prejsť vstupným školením.
    const isAmb = !!(u.is_admin || u.user_type==='ambassador' || u.user_type==='trainer');
    if(!isAmb) return res.status(403).json({
      error:'Kredit si môžeš hneď použiť v appke — na členstvá, permanentky, merch, vstupenky aj súkromné hodiny. Na výplatu na účet treba absolvovať vstupné ambasádorské školenie.',
      need_training:true, training_url:'/skolenie' });
    // Dostupný kredit = referral kredit + čakajúce provízie (jeden pohár)
    const pendComms = await q.find(db.commissions,{partner_id:u._id,status:'pending'});
    const pendSum = +pendComms.reduce((s,c)=>s+(c.amount||0),0).toFixed(2);
    const available = +((u.referral_credit||0) + pendSum).toFixed(2);
    const iban = String(req.body.iban||'').replace(/\s+/g,'').trim();
    const name = String(req.body.name||u.name||'').slice(0,100).trim();
    let amount = +parseFloat(req.body.amount);
    if(!(amount>0)) amount = available; // fallback: celý kredit
    amount = +amount.toFixed(2);
    if(available < 100) return res.status(400).json({error:`Minimálna výplata je 100 €. Aktuálny dostupný kredit: ${available.toFixed(2)} €. Kredit môžeš použiť aj na členstvá, permanentky, merch, vstupenky na eventy či súkromné hodiny.`});
    if(amount < 100) return res.status(400).json({error:'Minimálna suma na výplatu je 100 €.'});
    if(amount > available) return res.status(400).json({error:`Zadaná suma (${amount.toFixed(2)} €) je vyššia ako dostupný kredit (${available.toFixed(2)} €).`});
    if(!iban || iban.length < 15) return res.status(400).json({error:'Zadaj platný IBAN.'});
    if(!name) return res.status(400).json({error:'Zadaj meno majiteľa účtu.'});
    // Vyrovnaj čakajúce provízie do jedného pohára a odpočítaj vyplácanú sumu; zvyšok ostáva ako kredit
    await q.update(db.commissions,{partner_id:u._id,status:'pending'},{$set:{status:'paid',paid_at:nowISO()}},{multi:true});
    const remaining = +(available - amount).toFixed(2);
    await q.update(db.users,{_id:u._id},{$set:{ referral_credit:remaining, referral_credit_pending:(u.referral_credit_pending||0)+amount, bank_account:iban, payout_name:name }});
    await q.insert(db.transactions,{
      type:'referral_payout_request', user_id:u._id, user_name:u.name,
      amount, payment_method:'payout', note:`Žiadosť o výplatu kreditu: ${amount.toFixed(2)} € · IBAN ${iban} · ${name}`,
      status:'pending', bank_account:iban, payout_name:name, created_at:nowISO(), month:today().slice(0,7)
    });
    await q.insert(db.notifications,{user_id:u._id,type:'payout',title:'Žiadosť o výplatu odoslaná 💸',body:`${amount.toFixed(2)} € bude prevedených na účet ${iban} po potvrdení adminom.`,read:false,created_at:nowISO()});
    const admins = await q.find(db.users,{is_admin:true});
    for(const a of admins) await q.insert(db.notifications,{user_id:a._id,type:'payout_request',title:`💸 Žiadosť o výplatu: ${u.name}`,body:`${amount.toFixed(2)} € · IBAN ${iban} · ${name}`,read:false,created_at:nowISO()});
    res.json({ok:true, requested:amount, remaining, message:`Žiadosť o výplatu ${amount.toFixed(2)} € bola odoslaná.`});
  } catch(e){ res.status(500).json({error:e.message}); }
});

// Darovať kredit inému členovi (z dostupného kreditu)
app.post('/api/client/credit/gift', auth, async(req,res)=>{
  try {
    const u = await q.one(db.users,{_id:req.session.uid});
    if(!u) return res.status(404).json({error:'Nenájdený'});
    let amount = +parseFloat(req.body.amount); amount = +(amount||0).toFixed(2);
    if(!(amount>0)) return res.status(400).json({error:'Zadaj sumu väčšiu ako 0 €.'});
    const rq = String(req.body.recipient||'').trim();
    if(!rq) return res.status(400).json({error:'Zadaj e-mail alebo meno príjemcu.'});
    const esc=s=>String(s||'').replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
    let rcpt = await q.one(db.users,{email:new RegExp('^'+esc(rq)+'$','i')});
    if(!rcpt){ const matches=(await q.find(db.users,{name:new RegExp(esc(rq),'i')})).filter(x=>x._id!==u._id); if(matches.length===1) rcpt=matches[0]; else if(matches.length>1) return res.status(400).json({error:'Viac zhôd mena — zadaj radšej e-mail príjemcu.'}); }
    if(!rcpt) return res.status(404).json({error:'Príjemca nenájdený. Skús e-mail.'});
    if(rcpt._id===u._id) return res.status(400).json({error:'Nemôžeš darovať kredit sám sebe 🙂'});
    const pendComms = await q.find(db.commissions,{partner_id:u._id,status:'pending'});
    const pendSum = +pendComms.reduce((s,c)=>s+(c.amount||0),0).toFixed(2);
    const available = +((u.referral_credit||0) + pendSum).toFixed(2);
    if(amount > available) return res.status(400).json({error:`Nemáš dosť kreditu. Dostupné: ${available.toFixed(2)} €.`});
    await q.update(db.commissions,{partner_id:u._id,status:'pending'},{$set:{status:'paid',paid_at:nowISO()}},{multi:true});
    await q.update(db.users,{_id:u._id},{$set:{ referral_credit:+(available-amount).toFixed(2) }});
    await q.update(db.users,{_id:rcpt._id},{$set:{ referral_credit:+((rcpt.referral_credit||0)+amount).toFixed(2) }});
    const anon = !!req.body.anonymous;
    const fromDisp = anon ? 'Niekto' : u.name;
    await q.insert(db.transactions,{type:'credit_gift', user_id:u._id, user_name:u.name, amount, payment_method:'credit', anonymous:anon, note:`Darček kreditu ${amount.toFixed(2)} € pre ${rcpt.name}${anon?' (anonymne)':''}`, status:'done', created_at:nowISO(), month:today().slice(0,7)});
    await q.insert(db.notifications,{user_id:rcpt._id,type:'credit',title:`🎁 Dostal/a si ${amount.toFixed(2)} € kredit!`,body:`${fromDisp} ti daroval/a kredit. Použi ho na členstvo, permanentku, merch alebo súkromné hodiny.`,read:false,created_at:nowISO()});
    await q.insert(db.notifications,{user_id:u._id,type:'credit',title:`Darček odoslaný 🎁`,body:`Daroval/a si ${amount.toFixed(2)} € kredit pre ${rcpt.name}.`,read:false,created_at:nowISO()});
    announceGiftCredit(u._id, rcpt._id, amount, anon).catch(()=>{});
    res.json({ok:true, recipient:rcpt.name, amount});
  } catch(e){ res.status(500).json({error:e.message}); }
});

